console.log("\n--- STAGE 20: Normalized DLT homography ---");

test("normalizePoints centers at origin and scales to sqrt(2)", () => {
  const pts = [{x:100,y:200},{x:300,y:200},{x:100,y:400},{x:300,y:400}];
  const { pts: np, T } = homography.normalizePoints(pts);
  // Centroid of normalized points should be ~(0,0)
  let cx = 0, cy = 0;
  for (const p of np) { cx += p.x; cy += p.y; }
  cx /= np.length; cy /= np.length;
  assertNear(cx, 0, 0.001, "centroid x");
  assertNear(cy, 0, 0.001, "centroid y");
  // Average distance from origin should be sqrt(2)
  let avgDist = 0;
  for (const p of np) avgDist += Math.hypot(p.x, p.y);
  avgDist /= np.length;
  assertNear(avgDist, Math.SQRT2, 0.01, "avg dist");
});

test("mat3Mul identity", () => {
  const I = [1,0,0, 0,1,0, 0,0,1];
  const A = [2,3,1, 4,5,6, 7,8,9];
  const R = homography.mat3Mul(I, A);
  for (let i = 0; i < 9; i++) assertNear(R[i], A[i], 1e-10, `element ${i}`);
});

test("normalized DLT handles large coordinate offset", () => {
  // Without normalization, points far from origin cause numerical issues.
  // With Hartley normalization, this should work fine.
  const offset = 10000;
  const src = [
    {x:offset, y:offset}, {x:offset+100, y:offset},
    {x:offset, y:offset+100}, {x:offset+100, y:offset+100}
  ];
  const dst = [
    {x:offset+10, y:offset+5}, {x:offset+90, y:offset+8},
    {x:offset+12, y:offset+95}, {x:offset+88, y:offset+92}
  ];
  const H = homography.computeHomography(src, dst);
  assert(H !== null, "should compute homography for large offsets");
  // Verify corners map correctly
  for (let i = 0; i < 4; i++) {
    const p = homography.applyHomography(H, src[i]);
    assertNear(p.x, dst[i].x, 0.5, `corner ${i} x`);
    assertNear(p.y, dst[i].y, 0.5, `corner ${i} y`);
  }
});

test("normalized DLT handles very large scale disparity", () => {
  // Source is tiny, destination is huge
  const src = [{x:0,y:0},{x:1,y:0},{x:0,y:1},{x:1,y:1}];
  const dst = [{x:0,y:0},{x:10000,y:0},{x:0,y:10000},{x:10000,y:10000}];
  const H = homography.computeHomography(src, dst);
  assert(H !== null, "should handle scale disparity");
  const p = homography.applyHomography(H, {x:0.5, y:0.5});
  assertNear(p.x, 5000, 1, "center x");
  assertNear(p.y, 5000, 1, "center y");
});

