test("subpixelRefineGradient on synthetic crosshair", () => {
  // Create a synthetic 50x50 grayscale image with a sharp cross at (25.3, 24.7)
  const W = 50, H = 50;
  const gray = new Uint8Array(W * H).fill(200);
  // Draw horizontal dark line at y ≈ 24-25
  for (let x = 10; x < 40; x++) {
    gray[24 * W + x] = 20;
    gray[25 * W + x] = 20;
  }
  // Draw vertical dark line at x ≈ 25-26
  for (let y = 10; y < 40; y++) {
    gray[y * W + 25] = 20;
    gray[y * W + 26] = 20;
  }
  // The gradient convergence should find center near (25.5, 24.5)
  const ref = finder.subpixelRefineGradient(gray, W, H, 25, 25, 8);
  // Should be within 2 pixels of the initial estimate (sanity check)
  assert(Math.abs(ref.x - 25) < 2, `refined x: ${ref.x}`);
  assert(Math.abs(ref.y - 25) < 2, `refined y: ${ref.y}`);
});

test("subpixelRefineGradient returns input for flat region", () => {
  // Flat gray: no gradients → determinant ~0 → should return original
  const W = 20, H = 20;
  const gray = new Uint8Array(W * H).fill(128);
  const ref = finder.subpixelRefineGradient(gray, W, H, 10, 10, 5);
  assertNear(ref.x, 10, 0.001, "flat x unchanged");
  assertNear(ref.y, 10, 0.001, "flat y unchanged");
});

test("subpixelRefineGradient rejects far refinement", () => {
  // Edge at one side: refinement would pull far from initial center
  const W = 30, H = 30;
  const gray = new Uint8Array(W * H);
  // Left half dark, right half light
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      gray[y * W + x] = x < 5 ? 20 : 200;
    }
  }
  // Initial center at (15, 15) — gradient pulls to x≈5, which is > winRadius=5
  const ref = finder.subpixelRefineGradient(gray, W, H, 15, 15, 5);
  // Should reject and return original because displacement > winRadius
  assertNear(ref.x, 15, 0.001, "rejected x");
  assertNear(ref.y, 15, 0.001, "rejected y");
});

