test("classifyModuleMultipoint on uniform color region", () => {
  // 20x20 RGBA image, all red
  const W = 20, H = 20;
  const rgba = new Uint8Array(W * H * 4);
  for (let i = 0; i < W * H; i++) {
    rgba[i * 4] = 255; rgba[i * 4 + 1] = 0; rgba[i * 4 + 2] = 0; rgba[i * 4 + 3] = 255;
  }
  const palette = sampler.HD_PALETTE_4;
  const result = sampler.classifyModuleMultipoint(rgba, W, H, 10, 10, 1, 3, palette);
  assertEq(result.index, 1, "should classify as red");
  assert(result.confidence > 0.5, `confidence should be high: ${result.confidence}`);
});

test("classifyModuleMultipoint majority vote beats single-point noise", () => {
  // 20x20 image: center pixel is noise (blue), but surrounding is red
  const W = 20, H = 20;
  const rgba = new Uint8Array(W * H * 4);
  for (let i = 0; i < W * H; i++) {
    rgba[i * 4] = 255; rgba[i * 4 + 1] = 0; rgba[i * 4 + 2] = 0; rgba[i * 4 + 3] = 255;
  }
  // Paint center pixel blue
  const cx = 10, cy = 10;
  const cidx = (cy * W + cx) * 4;
  rgba[cidx] = 0; rgba[cidx + 1] = 0; rgba[cidx + 2] = 255;
  const palette = sampler.HD_PALETTE_4;
  // Single-point at center with radius=0 → would classify as blue
  const singleRgb = sampler.sampleAvg(rgba, W, H, cx, cy, 0);
  const singleResult = sampler.classifyModuleLab(singleRgb, palette);
  assertEq(singleResult.index, 2, "single-point should see blue noise");
  // Multi-point → 4/5 cardinals see red → majority vote = red
  const multiResult = sampler.classifyModuleMultipoint(rgba, W, H, cx, cy, 0, 3, palette);
  assertEq(multiResult.index, 1, "multi-point majority should be red");
});

