test("applyRadialConfidenceWeighting reduces edge confidence", () => {
  const gs = 10;
  const conf = new Float32Array(gs * gs).fill(1.0);
  decodeEngine.applyRadialConfidenceWeighting(conf, gs, 0.3);
  // Center module (5,5) should be near 1.0
  const centerConf = conf[5 * gs + 5];
  // Corner module (0,0) should be near 0.3
  const cornerConf = conf[0];
  assert(centerConf > 0.9, `center conf should be high: ${centerConf}`);
  assert(cornerConf < 0.5, `corner conf should be low: ${cornerConf}`);
  assert(cornerConf >= 0.3, `corner conf should be >= minWeight: ${cornerConf}`);
});

