test("computeAlignmentPatternPositions produces 4x4 grid for gs=128", () => {
  const info = format.computeAlignmentPatternPositions(128);
  assert(info.centers.length === 16, `expected 16 centers, got ${info.centers.length}`);
  assert(info.count === 144, `expected 144 masked modules, got ${info.count}`);
  // Verify all centers are within grid bounds
  for (const { r, c } of info.centers) {
    assert(r >= 1 && r < 127 && c >= 1 && c < 127, `center (${r},${c}) out of bounds`);
  }
});

test("buildAlignmentMapping produces correct data count", () => {
  const info = format.computeAlignmentPatternPositions(128);
  const mapping = format.buildAlignmentMapping(128, info.mask);
  assertEq(mapping.dataCount, 128 * 128 - info.count, "data count = grid - masked");
  assertEq(mapping.dataToGrid.length, mapping.dataCount, "dataToGrid length");
  // No alignment positions should be in data mapping
  for (let di = 0; di < mapping.dataToGrid.length; di++) {
    const { r, c } = mapping.dataToGrid[di];
    assertEq(info.mask[r * 128 + c], 0, `data module ${di} at (${r},${c}) should not be masked`);
  }
});

