test("hdCalcCapacity returns different data bytes for nsym=32 vs nsym=64", () => {
  const config = format.HD_CONFIGS["128x128-4c"];
  const capStd = format.hdCalcCapacity(config, { nsym: 32 });
  const capHR = format.hdCalcCapacity(config, { nsym: 64 });
  // Same raw bytes and block count
  assertEq(capStd.rawBytes, capHR.rawBytes, "rawBytes should match");
  assertEq(capStd.numBlocks, capHR.numBlocks, "numBlocks should match");
  // Different data capacity
  assert(capStd.dataBytes > capHR.dataBytes, `standard dataBytes (${capStd.dataBytes}) > HR (${capHR.dataBytes})`);
  assertEq(capStd.blockK, 223, "standard blockK = 223");
  assertEq(capHR.blockK, 191, "HR blockK = 191");
  assertEq(capStd.nsym, 32, "standard nsym = 32");
  assertEq(capHR.nsym, 64, "HR nsym = 64");
  console.log(`   Standard: ${capStd.dataBytes} data bytes (blockK=${capStd.blockK}, ${capStd.numBlocks} blocks)`);
  console.log(`   High-red: ${capHR.dataBytes} data bytes (blockK=${capHR.blockK}, ${capHR.numBlocks} blocks)`);
});

test("hdRsEncode/hdRsDecode roundtrip with nsym=64", () => {
  const config = format.HD_CONFIGS["128x128-4c"];
  const capHR = format.hdCalcCapacity(config, { nsym: 64 });
  const testData = new Uint8Array(capHR.dataBytes);
  for (let i = 0; i < testData.length; i++) testData[i] = i & 0xFF;
  const encoded = gfRs.hdRsEncode(testData, capHR.rawBytes, { nsym: 64 });
  const decoded = gfRs.hdRsDecode(encoded.frame, capHR.rawBytes, { nsym: 64 });
  assert(decoded.data !== null, "decode should succeed");
  assertEq(decoded.failedBlocks, 0, "no failed blocks");
  assertEq(decoded.totalCorrected, 0, "no corrections needed");
  // Verify data matches
  for (let i = 0; i < testData.length; i++) {
    assertEq(decoded.data[i], testData[i], `byte ${i}`);
  }
});

test("hdRsDecode nsym=64 corrects more errors than nsym=32", () => {
  const config = format.HD_CONFIGS["128x128-4c"];
  const capHR = format.hdCalcCapacity(config, { nsym: 64 });
  const testData = new Uint8Array(capHR.dataBytes);
  for (let i = 0; i < testData.length; i++) testData[i] = (i * 7) & 0xFF;
  const encoded = gfRs.hdRsEncode(testData, capHR.rawBytes, { nsym: 64 });
  // Inject 250 errors spread across the frame. After de-interleaving, these
  // scatter across blocks. With 15 blocks, ~17 errors/block on average.
  // This exceeds t=16 (standard) but is well within t=32 (high-redundancy).
  // Use 250 to stay safely under 32/block even with uneven distribution.
  const corrupted = new Uint8Array(encoded.frame);
  const frameSize = corrupted.length;
  const errCount = 250;
  const errStep = Math.floor(frameSize / errCount);
  for (let i = 0; i < errCount; i++) {
    const pos = i * errStep;
    if (pos < frameSize) corrupted[pos] ^= 0xFF;
  }
  // Standard decode should fail (errors exceed t=16 per block)
  const stdResult = gfRs.hdRsDecode(corrupted, capHR.rawBytes, { nsym: 32 });
  assert(stdResult.data === null, `standard decode should fail: ${stdResult.failedBlocks}/${stdResult.numBlocks} failed`);
  // High-redundancy decode should succeed (errors within t=32 per block)
  const hrResult = gfRs.hdRsDecode(corrupted, capHR.rawBytes, { nsym: 64 });
  assert(hrResult.data !== null, `HR decode should succeed: ${hrResult.failedBlocks}/${hrResult.numBlocks} failed`);
  console.log(`   ${errCount} errors: standard FAIL (${stdResult.failedBlocks} blocks), HR corrected ${hrResult.totalCorrected}`);
});

test("clean roundtrip with high-redundancy encode", () => {
  // Note: RS(255,191) codewords are a mathematical subset of RS(255,223) codewords
  // because g64(x) = g32(x) * extra_terms. This means on a clean image with zero errors,
  // the standard decoder (nsym=32) will succeed on HR-encoded data — the syndromes are
  // all zero for both generator polynomials. This is correct behavior: the payload still
  // decodes correctly because the AHDX header's size fields constrain the data read.
  const testPayload = "High-redundancy RS code rate proof — clean image";
  const testFilename = "hr_clean.txt";
  const enc = renderer.encodeAndRender(testPayload, testFilename, {
    configName: "128x128-4c",
    nsym: 64,
  });
  const result = decodeEngine.decodeFrame(enc.img.data, enc.img.width, enc.img.height, {
    configName: "128x128-4c",
  });
  assert(result !== null, "result should not be null");
  assert(result.decoded === true, `decode should succeed: ${JSON.stringify(result.rsStats || result.error)}`);
  assertEq(result.filename, testFilename);
  const recoveredText = new TextDecoder().decode(result.payload);
  assertEq(recoveredText, testPayload, "payload mismatch");
  // Standard decoder may succeed on clean HR data (valid subset relationship)
  // — the important thing is the payload is correct
  console.log(`   HR clean: PASS — RS corrected ${result.rsStats.totalCorrected}, nsym=${result.nsym}`);
});

