// =========================================================================
// STAGE 31: Erasure-aware RS decoding
// =========================================================================
console.log("\n--- STAGE 31: Erasure-aware RS decoding ---");

test("rsDecodeWithErasures corrects more than standard with known positions", () => {
  // Encode a block with nsym=32 (t=16)
  const blockK = 223, nsym = 32, blockSize = 255;
  const data = new Uint8Array(blockK);
  for (let i = 0; i < blockK; i++) data[i] = (i * 13) & 0xFF;
  const encoded = gfRs.rsEncode(data, nsym);

  // Inject 20 errors — exceeds t=16 for standard decode
  const corrupted = new Uint8Array(encoded);
  const errorPositions = [];
  for (let e = 0; e < 20; e++) {
    const pos = e * 12; // spread errors across the block
    if (pos < blockSize) {
      corrupted[pos] ^= 0xFF;
      errorPositions.push(pos);
    }
  }

  // Standard decode should fail (20 > t=16)
  const stdResult = gfRs.rsDecode(corrupted, nsym);
  assert(!stdResult.ok, "standard decode should fail with 20 errors");

  // Erasure decode with all 20 positions known should succeed (20 erasures ≤ nsym=32)
  const erasureResult = gfRs.rsDecodeWithErasures(corrupted, nsym, errorPositions);
  assert(erasureResult.ok, `erasure decode should succeed: corrected=${erasureResult.corrected}`);
  // Verify data matches original
  for (let i = 0; i < blockK; i++) {
    assertEq(erasureResult.data[i], data[i], `byte ${i}`);
  }
  console.log(`   20 known erasures (nsym=32): standard FAIL, erasure PASS (corrected ${erasureResult.corrected})`);
});

test("rsDecodeWithErasures handles mixed errors + erasures", () => {
  const blockK = 223, nsym = 32, blockSize = 255;
  const data = new Uint8Array(blockK);
  for (let i = 0; i < blockK; i++) data[i] = (i * 7 + 3) & 0xFF;
  const encoded = gfRs.rsEncode(data, nsym);

  // Inject 10 known erasures + 8 unknown errors = 10 + 2*8 = 26 ≤ 32
  const corrupted = new Uint8Array(encoded);
  const erasurePositions = [];
  for (let e = 0; e < 10; e++) {
    const pos = e * 20;
    if (pos < blockSize) {
      corrupted[pos] ^= 0xAA;
      erasurePositions.push(pos);
    }
  }
  // Unknown errors at different positions
  for (let e = 0; e < 8; e++) {
    const pos = e * 20 + 10; // offset from erasures
    if (pos < blockSize) corrupted[pos] ^= 0x55;
  }

  // Standard decode: 18 total errors, > t=16 → should fail
  const stdResult = gfRs.rsDecode(corrupted, nsym);
  assert(!stdResult.ok, "standard decode should fail with 18 errors");

  // Erasure decode: 10 erasures + 8 errors = 10 + 16 = 26 ≤ 32 → should pass
  const erasureResult = gfRs.rsDecodeWithErasures(corrupted, nsym, erasurePositions);
  assert(erasureResult.ok, `mixed decode should succeed: corrected=${erasureResult.corrected}`);
  for (let i = 0; i < blockK; i++) {
    assertEq(erasureResult.data[i], data[i], `byte ${i}`);
  }
  console.log(`   10 erasures + 8 errors (nsym=32): standard FAIL, erasure PASS (corrected ${erasureResult.corrected})`);
});

test("rsDecodeWithErasures rejects when capacity exceeded", () => {
  const blockK = 223, nsym = 32, blockSize = 255;
  const data = new Uint8Array(blockK);
  for (let i = 0; i < blockK; i++) data[i] = i & 0xFF;
  const encoded = gfRs.rsEncode(data, nsym);

  // 33 erasures > nsym=32 → should fail
  const corrupted = new Uint8Array(encoded);
  const erasurePositions = [];
  for (let e = 0; e < 33; e++) {
    const pos = e * 7;
    if (pos < blockSize) {
      corrupted[pos] ^= 0xFF;
      erasurePositions.push(pos);
    }
  }
  const result = gfRs.rsDecodeWithErasures(corrupted, nsym, erasurePositions);
  assert(!result.ok, "should fail with 33 erasures > nsym=32");
});

test("hdRsDecode passes erasure positions through deinterleaver", () => {
  // Encode data, corrupt specific interleaved positions, pass them as erasures
  const config = format.HD_CONFIGS["128x128-4c"];
  const cap = format.hdCalcCapacity(config);
  const testData = new Uint8Array(cap.dataBytes);
  for (let i = 0; i < testData.length; i++) testData[i] = (i * 11) & 0xFF;
  const encoded = gfRs.hdRsEncode(testData, cap.rawBytes);

  // Corrupt 200 positions in the interleaved frame and record them as erasures
  const corrupted = new Uint8Array(encoded.frame);
  const erasurePositions = [];
  const frameSize = cap.numBlocks * 255;
  for (let i = 0; i < 200; i++) {
    const pos = i * Math.floor(frameSize / 200);
    if (pos < frameSize) {
      corrupted[pos] ^= 0xFF;
      erasurePositions.push(pos);
    }
  }

  // Without erasures: should fail (200 errors across 15 blocks ≈ 13/block > t=16)
  const noErasureResult = gfRs.hdRsDecode(corrupted, cap.rawBytes);
  // With erasures: each block gets ~13 erasures (≤ nsym=32) → should succeed
  const erasureResult = gfRs.hdRsDecode(corrupted, cap.rawBytes, { erasurePositions });
  assert(erasureResult.data !== null, `erasure HD decode should succeed: ${erasureResult.failedBlocks}/${erasureResult.numBlocks} failed`);
  console.log(`   200 frame erasures: no-erasure ${noErasureResult.failedBlocks} failed, with-erasure ${erasureResult.failedBlocks} failed`);
});

test("rsDecodeWithErasures with zero erasures equals standard decode", () => {
  const blockK = 223, nsym = 32, blockSize = 255;
  const data = new Uint8Array(blockK);
  for (let i = 0; i < blockK; i++) data[i] = (i * 3) & 0xFF;
  const encoded = gfRs.rsEncode(data, nsym);

  // Inject 10 errors (within standard t=16)
  const corrupted = new Uint8Array(encoded);
  for (let e = 0; e < 10; e++) corrupted[e * 20] ^= 0xFF;

  const stdResult = gfRs.rsDecode(corrupted, nsym);
  const erasureResult = gfRs.rsDecodeWithErasures(corrupted, nsym, []);
  assert(stdResult.ok, "standard should succeed");
  assert(erasureResult.ok, "erasure with empty list should succeed");
  assertEq(stdResult.corrected, erasureResult.corrected, "correction count should match");
});

