test("buildAlignmentGridMapper returns valid mapper on clean image", () => {
  const enc = renderer.encodeAndRender("Align-grid mapper unit test", "ag_unit.txt", {
    configName: "128x128-4c",
  });
  const config = format.HD_CONFIGS["128x128-4c"];
  const layout = format.computeSymbolLayout(config.grid, config.canvasPx);
  const canonPts = format.computeCanonicalFinderPoints(layout);
  const fids = finder.detectFinders(enc.img.data, enc.img.width, enc.img.height);
  assert(fids !== null, "should find finders");
  const sourcePts = [fids.TL, fids.TR, fids.BL, fids.BR];
  const Hmat = homography.computeHomography(canonPts, sourcePts);

  const anchors = decodeEngine.detectAlignmentAnchors(Hmat, layout, enc.img.data, enc.img.width, enc.img.height, config.grid);
  assert(anchors.length >= 4, `need >=4 anchors, got ${anchors.length}`);

  const mapper = decodeEngine.buildAlignmentGridMapper(Hmat, layout, config.grid, enc.img.data, enc.img.width, enc.img.height, anchors);
  assert(mapper !== null, "mapper should be built");

  // Verify mapper maps center of data grid approximately correctly
  const centerCx = layout.dataOriginPx + (config.grid / 2) * layout.modPx;
  const centerCy = layout.dataOriginPx + (config.grid / 2) * layout.modPx;
  const mapped = mapper(centerCx, centerCy);
  const expected = homography.applyHomography(Hmat, { x: centerCx, y: centerCy });
  const delta = Math.hypot(mapped.x - expected.x, mapped.y - expected.y);
  assert(delta < layout.modPx * 2, `center mapping delta ${delta.toFixed(2)} should be < 2 modPx`);
  console.log(`   ${anchors.length} anchors, mapper built, center delta = ${delta.toFixed(3)}px`);
});

