test("alignment-grid mapper scores well on clean image timing strips", () => {
  const enc = renderer.encodeAndRender("Align-grid timing test scoring", "ag_timing.txt", {
    configName: "128x128-4c",
  });
  const config = format.HD_CONFIGS["128x128-4c"];
  const layout = format.computeSymbolLayout(config.grid, config.canvasPx);
  const canonPts = format.computeCanonicalFinderPoints(layout);
  const fids = finder.detectFinders(enc.img.data, enc.img.width, enc.img.height);
  assert(fids !== null, "should find finders");
  const sourcePts = [fids.TL, fids.TR, fids.BL, fids.BR];
  const Hmat = homography.computeHomography(canonPts, sourcePts);

  const anchors = decodeEngine.detectAlignmentAnchors(Hmat, layout, enc.img.data, enc.img.width, enc.img.height, config.grid);
  const mapper = decodeEngine.buildAlignmentGridMapper(Hmat, layout, config.grid, enc.img.data, enc.img.width, enc.img.height, anchors);
  assert(mapper !== null, "mapper should be built");

  // Score via dual timing strips
  const { qzPx, modPx, totalMod } = layout;
  let ok = 0, tot = 0;
  for (let m = 8; m < totalMod - 7; m += 2) {
    for (const isH of [true, false]) {
      const cx = isH ? qzPx + m * modPx + modPx / 2 : qzPx + 6 * modPx + modPx / 2;
      const cy = isH ? qzPx + 6 * modPx + modPx / 2 : qzPx + m * modPx + modPx / 2;
      const sp = mapper(cx, cy);
      const rx = Math.round(sp.x), ry = Math.round(sp.y);
      if (rx < 0 || ry < 0 || rx >= enc.img.width || ry >= enc.img.height) continue;
      const idx = (ry * enc.img.width + rx) * 4;
      const lum = 0.299 * enc.img.data[idx] + 0.587 * enc.img.data[idx + 1] + 0.114 * enc.img.data[idx + 2];
      const isDark = lum < 128;
      const shouldBeDark = (m % 2 === 0);
      if (isDark === shouldBeDark) ok++;
      tot++;
    }
  }
  const score = ok / tot;
  assert(score > 0.85, `timing score ${score.toFixed(3)} should be > 0.85`);
  console.log(`   Align-grid timing score: ${score.toFixed(3)} (${ok}/${tot})`);
});

