test("sampleAllModulesFused produces valid output with multiple mappers", () => {
  const enc = renderer.encodeAndRender("Fusion unit test payload", "fuse_unit.txt", {
    configName: "128x128-4c",
  });
  const config = format.HD_CONFIGS["128x128-4c"];
  const layout = format.computeSymbolLayout(config.grid, config.canvasPx);
  const canonPts = format.computeCanonicalFinderPoints(layout);
  const fids = finder.detectFinders(enc.img.data, enc.img.width, enc.img.height);
  assert(fids !== null, "should find finders");
  const sourcePts = [fids.TL, fids.TR, fids.BL, fids.BR];
  const Hmat = homography.computeHomography(canonPts, sourcePts);
  const palette = sampler.hdGetPalette(config.colors);
  const cap = format.hdCalcCapacity(config);
  const alignMapping = format.buildAlignmentMapping(config.grid, cap.alignInfo.mask);

  const mapGlobal = (cx, cy) => homography.applyHomography(Hmat, { x: cx, y: cy });
  const mapBilinear = decodeEngine.buildBilinearMapper(Hmat, layout, config.grid, enc.img.data, enc.img.width, enc.img.height);

  const fused = decodeEngine.sampleAllModulesFused(
    enc.img.data, enc.img.width, enc.img.height,
    [mapGlobal, mapBilinear],
    layout, config.grid, palette, config, alignMapping
  );

  assert(fused.modules.length === alignMapping.dataCount, "module count matches");
  assert(fused.moduleConfidence.length === alignMapping.dataCount, "confidence count matches");

  // On a clean image, confidence should be high (mappers agree)
  let highConf = 0;
  for (let i = 0; i < fused.moduleConfidence.length; i++) {
    if (fused.moduleConfidence[i] > 0.8) highConf++;
  }
  const highPct = highConf / fused.moduleConfidence.length;
  assert(highPct > 0.9, `${(highPct * 100).toFixed(1)}% high-confidence, expected >90%`);
  console.log(`   Fusion: ${fused.modules.length} modules, ${(highPct * 100).toFixed(1)}% high-conf`);
});

