console.log("\n--- STAGE 34: Erasure escalation ---");

test("buildReliabilityAndDecode accepts erasure threshold parameters", () => {
  const config = format.HD_CONFIGS["128x128-4c"];
  const cap = format.hdCalcCapacity(config);

  // Create clean modules — should decode regardless of erasure params
  const testData = new Uint8Array(cap.dataBytes);
  for (let i = 0; i < testData.length; i++) testData[i] = (i * 7) & 0xFF;
  const encoded = gfRs.hdRsEncode(testData, cap.rawBytes);

  // Unpack frame back to modules to simulate clean sampling
  const bpm = config.bpm;
  const gs = config.grid;
  const alignMapping = format.buildAlignmentMapping(gs, cap.alignInfo.mask);
  const numModules = alignMapping.dataCount;
  const modules = new Uint8Array(numModules);
  const moduleConf = new Float32Array(numModules).fill(1.0);
  const moduleAlt = new Uint8Array(numModules);

  // Unpack frame bytes back to module values
  for (let di = 0; di < numModules; di++) {
    const bitStart = di * bpm;
    const byteIdx = Math.floor(bitStart / 8);
    const bitOff = bitStart % 8;
    if (byteIdx < encoded.frame.length) {
      modules[di] = (encoded.frame[byteIdx] >> (8 - bpm - bitOff)) & ((1 << bpm) - 1);
    }
  }

  // Aggressive erasure params should still decode clean data
  const result = decodeEngine.buildReliabilityAndDecode(
    modules, moduleConf, moduleAlt, config, cap,
    { nsym: 32, erasureConfThreshold: 0.50, erasureMaxPct: 0.15, erasureMinCount: 3 }
  );
  assert(result.data !== null, "clean data should decode with any erasure params");
  assertEq(result.failedBlocks, 0, "no failed blocks");
});

test("erasure escalation recovers blocks that conservative threshold misses", () => {
  // Direct unit test: encode data, inject errors that are "close" to RS capacity,
  // and verify that declaring erasures at the corrupted positions helps.
  const config = format.HD_CONFIGS["128x128-4c"];
  const cap = format.hdCalcCapacity(config);
  const testData = new Uint8Array(cap.dataBytes);
  for (let i = 0; i < testData.length; i++) testData[i] = (i * 13) & 0xFF;
  const encoded = gfRs.hdRsEncode(testData, cap.rawBytes);

  // Inject 200 errors in the interleaved frame
  const corrupted = new Uint8Array(encoded.frame);
  const frameSize = cap.numBlocks * 255;
  const errCount = 200;
  const errStep = Math.floor(frameSize / errCount);
  for (let i = 0; i < errCount; i++) {
    const pos = i * errStep;
    if (pos < frameSize) corrupted[pos] ^= 0xFF;
  }

  // Conservative erasures (no positions declared) — may fail some blocks
  const conservative = gfRs.hdRsDecode(corrupted, cap.rawBytes, { nsym: 32 });

  // With known erasure positions — should do better
  const erasurePositions = [];
  for (let i = 0; i < errCount; i++) {
    const pos = i * errStep;
    if (pos < frameSize) erasurePositions.push(pos);
  }
  const withErasures = gfRs.hdRsDecode(corrupted, cap.rawBytes, { nsym: 32, erasurePositions });

  console.log(`   Conservative: ${conservative.failedBlocks}/${conservative.numBlocks} failed`);
  console.log(`   With erasures: ${withErasures.failedBlocks}/${withErasures.numBlocks} failed`);
  assert(withErasures.failedBlocks <= conservative.failedBlocks,
    "erasure declaration should not increase failures");
});

