// =========================================================================
// STAGE 37: Timing-anchor cross-interpolation mapper + Chase-K escalation
// =========================================================================
console.log("\n--- STAGE 37: Timing-cross mapper + Chase-K escalation ---");

test("timingCrossMapper returns function with unwarped image", () => {
  // Use an unwarped image where timing strips are perfectly detectable
  const testPayload = "Timing cross mapper test — building separable correction field";
  const enc = renderer.encodeAndRender(testPayload, "tcross.txt", {
    configName: "128x128-4c",
  });
  // Use the raw rendered image (no warp) for reliable anchor detection
  const config = format.HD_CONFIGS["128x128-4c"];
  const layout = format.computeSymbolLayout(config.grid, config.canvasPx);
  const canonPts = format.computeCanonicalFinderPoints(layout);
  // Identity-like H: finder centers map to themselves in the rendered image
  const fids = finder.detectFinders(enc.img.data, enc.img.width, enc.img.height);
  if (!fids) { console.log("   Skipped — finders not detected in rendered image"); assert(true); return; }
  const sourcePts = [fids.TL, fids.TR, fids.BL, fids.BR];
  const Hmat = homography.computeHomography(canonPts, sourcePts);
  const mapper = decodeEngine.buildTimingCrossMapper(Hmat, layout, enc.img.data, enc.img.width, enc.img.height);
  assert(typeof mapper === "function", "timing cross mapper should return a function");
  const center = mapper(layout.canvasPx / 2, layout.canvasPx / 2);
  assert(typeof center.x === "number" && typeof center.y === "number", "should return {x, y}");
  console.log(`   Timing-cross mapper built, center maps to (${center.x.toFixed(1)}, ${center.y.toFixed(1)})`);
});

