test("estimateBlur: sharp vs blurred image", () => {
  const testPayload = "Blur estimation test — sharp image should have high variance";
  const enc = renderer.encodeAndRender(testPayload, "blur_est.txt", {
    configName: "128x128-4c",
  });
  // Sharp image: high variance of Laplacian
  const sharpVar = decodeEngine.estimateBlur(enc.img.data, enc.img.width, enc.img.height);
  // Blur the image
  const blurred = renderer.applyGaussianBlur(enc.img, 2.0);
  const blurVar = decodeEngine.estimateBlur(blurred.data, blurred.width, blurred.height);
  assert(sharpVar > blurVar * 2, `sharp (${sharpVar.toFixed(0)}) should be >2x blurred (${blurVar.toFixed(0)})`);
  console.log(`   Sharp variance: ${sharpVar.toFixed(0)}, Blurred (σ=2): ${blurVar.toFixed(0)} (ratio: ${(sharpVar/blurVar).toFixed(1)}x)`);
});

