console.log("\n--- STAGE 43: Compression roundtrip ---");

test("deflate compression roundtrip", () => {
  // Use a longer payload that benefits from compression
  const testPayload = "Deflate compression test. ".repeat(20) +
    "This payload contains repeated text that compresses well with DEFLATE.";
  const enc = renderer.encodeAndRender(testPayload, "compressed.txt", {
    configName: "128x128-4c",
    compFlag: codec.COMPRESS_FLAG_DEFLATE,
  });
  const srcW = enc.img.width, srcH = enc.img.height;
  const warped = renderer.perspectiveWarp(enc.img, 1100, 1100,
    [{ x: 0, y: 0 }, { x: srcW, y: 0 }, { x: 0, y: srcH }, { x: srcW, y: srcH }],
    [{ x: 50, y: 50 }, { x: 1030, y: 55 }, { x: 55, y: 1025 }, { x: 1035, y: 1030 }]);
  const result = decodeEngine.decodeFrame(warped.data, warped.width, warped.height, {
    configName: "128x128-4c",
  });
  assert(result && result.decoded, "deflate roundtrip should decode");
  const decoded = new TextDecoder().decode(result.payload);
  assert(decoded === testPayload, "decoded payload should match original");
  const ratio = (enc.header.compSize / enc.header.origSize * 100).toFixed(0);
  console.log(`   Deflate: PASS — ${enc.header.origSize}→${enc.header.compSize} bytes (${ratio}% ratio)`);
});

