// =========================================================================
// STAGE 44: Binary and large payloads
// =========================================================================
console.log("\n--- STAGE 44: Binary and large payloads ---");

test("binary payload (random bytes)", () => {
  // Generate 500 random bytes
  const binPayload = new Uint8Array(500);
  let seed = 0xDEADBEEF;
  for (let i = 0; i < binPayload.length; i++) {
    seed = ((seed * 1103515245 + 12345) & 0x7FFFFFFF) >>> 0;
    binPayload[i] = seed & 0xFF;
  }
  const enc = renderer.encodeAndRender(binPayload, "binary.dat", {
    configName: "128x128-4c",
  });
  const srcW = enc.img.width, srcH = enc.img.height;
  const warped = renderer.perspectiveWarp(enc.img, 1100, 1100,
    [{ x: 0, y: 0 }, { x: srcW, y: 0 }, { x: 0, y: srcH }, { x: srcW, y: srcH }],
    [{ x: 50, y: 50 }, { x: 1030, y: 55 }, { x: 55, y: 1025 }, { x: 1035, y: 1030 }]);
  const result = decodeEngine.decodeFrame(warped.data, warped.width, warped.height, {
    configName: "128x128-4c",
  });
  assert(result && result.decoded, "binary payload should decode");
  // Compare byte-for-byte
  const decoded = result.payload;
  assert(decoded.length === binPayload.length, `length mismatch: ${decoded.length} vs ${binPayload.length}`);
  let mismatches = 0;
  for (let i = 0; i < binPayload.length; i++) {
    if (decoded[i] !== binPayload[i]) mismatches++;
  }
  assert(mismatches === 0, `${mismatches} byte mismatches in decoded payload`);
  console.log(`   Binary 500 bytes: PASS — exact match, filename="${result.filename}"`);
});

test("near-capacity payload (128x128-4c)", () => {
  const cap = format.hdCalcCapacity(format.HD_CONFIGS["128x128-4c"]);
  // Use ~80% of data capacity (after header overhead)
  const headerOverhead = 80; // approximate AHDX header
  const payloadSize = Math.floor((cap.dataBytes - headerOverhead) * 0.8);
  const bigPayload = new Uint8Array(payloadSize);
  let seed = 0x12345678;
  for (let i = 0; i < bigPayload.length; i++) {
    seed = ((seed * 1103515245 + 12345) & 0x7FFFFFFF) >>> 0;
    bigPayload[i] = seed & 0xFF;
  }
  const enc = renderer.encodeAndRender(bigPayload, "big.bin", {
    configName: "128x128-4c",
  });
  const srcW = enc.img.width, srcH = enc.img.height;
  const warped = renderer.perspectiveWarp(enc.img, 1100, 1100,
    [{ x: 0, y: 0 }, { x: srcW, y: 0 }, { x: 0, y: srcH }, { x: srcW, y: srcH }],
    [{ x: 50, y: 50 }, { x: 1030, y: 55 }, { x: 55, y: 1025 }, { x: 1035, y: 1030 }]);
  const result = decodeEngine.decodeFrame(warped.data, warped.width, warped.height, {
    configName: "128x128-4c",
  });
  assert(result && result.decoded, "near-capacity payload should decode");
  assert(result.payload.length === bigPayload.length, "payload length should match");
  console.log(`   Near-capacity ${payloadSize} bytes: PASS — RS corrected ${result.rsStats.totalCorrected}`);
});

test("compressed binary payload", () => {
  // Binary data with some structure that compresses
  const structuredPayload = new Uint8Array(1000);
  for (let i = 0; i < 1000; i++) {
    structuredPayload[i] = (i % 17) * 15; // Repeating pattern compresses well
  }
  const enc = renderer.encodeAndRender(structuredPayload, "struct.bin", {
    configName: "128x128-4c",
    compFlag: codec.COMPRESS_FLAG_DEFLATE,
  });
  const srcW = enc.img.width, srcH = enc.img.height;
  const warped = renderer.perspectiveWarp(enc.img, 1100, 1100,
    [{ x: 0, y: 0 }, { x: srcW, y: 0 }, { x: 0, y: srcH }, { x: srcW, y: srcH }],
    [{ x: 50, y: 50 }, { x: 1030, y: 55 }, { x: 55, y: 1025 }, { x: 1035, y: 1030 }]);
  const result = decodeEngine.decodeFrame(warped.data, warped.width, warped.height, {
    configName: "128x128-4c",
  });
  assert(result && result.decoded, "compressed binary payload should decode");
  assert(result.payload.length === structuredPayload.length, "payload length should match");
  let ok = true;
  for (let i = 0; i < structuredPayload.length; i++) {
    if (result.payload[i] !== structuredPayload[i]) { ok = false; break; }
  }
  assert(ok, "compressed binary payload should match exactly");
  const ratio = (enc.header.compSize / enc.header.origSize * 100).toFixed(0);
  console.log(`   Compressed binary 1KB: PASS — ${ratio}% ratio`);
});

// =========================================================================
// STAGE 45: SHA-256 payload integrity verification
// =========================================================================
console.log("\n--- STAGE 45: SHA-256 payload integrity verification ---");

test("verifySha256 returns valid for correct payload", () => {
  const crypto = require("crypto");
  const payload = new Uint8Array([1, 2, 3, 4, 5, 6, 7, 8]);
  const hash = new Uint8Array(crypto.createHash("sha256").update(payload).digest());
  const result = codec.verifySha256(payload, hash);
  assert(result.valid === true, "should be valid");
  assert(result.expected === result.actual, "hashes should match");
});

test("verifySha256 returns invalid for wrong payload", () => {
  const crypto = require("crypto");
  const payload = new Uint8Array([1, 2, 3, 4, 5, 6, 7, 8]);
  const hash = new Uint8Array(crypto.createHash("sha256").update(payload).digest());
  const badPayload = new Uint8Array([1, 2, 3, 4, 5, 6, 7, 9]); // one byte changed
  const result = codec.verifySha256(badPayload, hash);
  assert(result.valid === false, "should be invalid");
  assert(result.expected !== result.actual, "hashes should differ");
});

