test("partial decode returns blockMap on extreme warp", () => {
  // Use an extreme perspective warp that will cause some blocks to fail
  const msg = "A".repeat(2000); // fill capacity so many blocks are used
  const enc = renderer.encodeAndRender(msg, "partial_test.txt", { configName: "128x128-4c" });
  const srcW = enc.img.width, srcH = enc.img.height;
  // Extreme warp — 60° off-axis equivalent
  const warped = renderer.perspectiveWarp(enc.img, 1200, 1200,
    [{ x: 0, y: 0 }, { x: srcW, y: 0 }, { x: 0, y: srcH }, { x: srcW, y: srcH }],
    [{ x: 300, y: 50 }, { x: 900, y: 200 }, { x: 50, y: 900 }, { x: 1150, y: 1100 }]);
  const result = decodeEngine.decodeFrame(warped.data, warped.width, warped.height, {
    configName: "128x128-4c",
  });
  // Either full decode, partial, total failure, or no finders — all valid for extreme warp
  if (result && result.decoded) {
    console.log(`   Extreme warp: full decode! RS corrected=${result.rsStats.totalCorrected}`);
  } else if (result && result.partial) {
    assert(result.blockMap, "partial should have blockMap");
    assert(Array.isArray(result.blockMap), "blockMap should be array");
    const okBlocks = result.blockMap.filter(b => b.ok).length;
    console.log(`   Extreme warp: partial decode — ${okBlocks}/${result.rsStats.numBlocks} blocks OK (${result.successRate}%)`);
    assert(result.filename === "partial_test.txt", `filename should be partial_test.txt, got ${result.filename}`);
    assert(result.successRate > 0, "some blocks should succeed");
  } else if (result && result.rsStats) {
    // Total failure — no blocks decoded, still valid
    console.log(`   Extreme warp: total failure — ${result.rsStats.failedBlocks}/${result.rsStats.numBlocks} blocks failed`);
  } else {
    // No finders found — valid for extreme warp (60° off-axis)
    console.log(`   Extreme warp: finder detection failed — too extreme for recovery`);
  }
});

