test("partial result has correct blockMap structure", () => {
  // Force failure by injecting noise into data region
  const msg = "B".repeat(2000);
  const enc = renderer.encodeAndRender(msg, "struct_test.txt", { configName: "128x128-4c" });
  const imgCopy = new Uint8Array(enc.img.data);
  // Corrupt a band of the image (middle rows) to kill some blocks
  const W = enc.img.width, H = enc.img.height;
  for (let y = Math.floor(H * 0.4); y < Math.floor(H * 0.6); y++) {
    for (let x = 0; x < W; x++) {
      const idx = (y * W + x) * 4;
      imgCopy[idx] = 255 - imgCopy[idx];       // R
      imgCopy[idx + 1] = 255 - imgCopy[idx + 1]; // G
      imgCopy[idx + 2] = 255 - imgCopy[idx + 2]; // B
    }
  }
  const result = decodeEngine.decodeFrame(imgCopy, W, H, { configName: "128x128-4c" });
  if (result && result.partial) {
    assert(result.blockMap.length === result.rsStats.numBlocks, "blockMap length should match numBlocks");
    for (const bm of result.blockMap) {
      assert(typeof bm.block === "number", "blockMap entry should have block number");
      assert(typeof bm.ok === "boolean", "blockMap entry should have ok boolean");
      assert(typeof bm.corrected === "number", "blockMap entry should have corrected count");
    }
    console.log(`   BlockMap structure verified: ${result.blockMap.length} entries, ${result.successRate}% success`);
  } else if (result && result.decoded) {
    console.log(`   RS recovered everything despite corruption — robust!`);
  } else {
    console.log(`   Total failure — corruption too severe`);
  }
});

