test("kitchen sink: warp + 180° rotation + blur + noise + JPEG + lighting", () => {
  const msg = "Kitchen sink stress test " + "E".repeat(300);
  const enc = renderer.encodeAndRender(msg, "multi_sink.txt", { configName: "128x128-4c" });
  const srcW = enc.img.width, srcH = enc.img.height;
  // Step 1: Perspective warp
  let img = renderer.perspectiveWarp(enc.img, 1100, 1100,
    [{ x: 0, y: 0 }, { x: srcW, y: 0 }, { x: 0, y: srcH }, { x: srcW, y: srcH }],
    [{ x: 50, y: 50 }, { x: 1030, y: 55 }, { x: 55, y: 1025 }, { x: 1035, y: 1030 }]);
  // Step 2: 180° rotation
  const rotImg = { data: new Uint8Array(img.data.length), width: img.width, height: img.height };
  for (let y = 0; y < img.height; y++) {
    for (let x = 0; x < img.width; x++) {
      const si = (y * img.width + x) * 4;
      const dy = img.height - 1 - y, dx = img.width - 1 - x;
      const di = (dy * img.width + dx) * 4;
      rotImg.data[di] = img.data[si];
      rotImg.data[di + 1] = img.data[si + 1];
      rotImg.data[di + 2] = img.data[si + 2];
      rotImg.data[di + 3] = img.data[si + 3];
    }
  }
  img = rotImg;
  // Step 3: Brightness gradient
  img = renderer.applyBrightnessGradient(img, 1.3, 0.7, "vertical");
  // Step 4: Blur
  img = renderer.applyGaussianBlur(img, 1.0);
  // Step 5: JPEG
  img = renderer.simulateJpegCompression(img, 50);
  // Step 6: Noise
  img = renderer.addGaussianNoise(img, 15);
  const result = decodeEngine.decodeFrame(img.data, img.width, img.height, { configName: "128x128-4c" });
  assert(result && result.decoded, "kitchen sink should decode");
  assert(result.hashValid === true, "hash should be valid");
  console.log(`   Kitchen sink (6 degradations + rotation): PASS — RS=${result.rsStats.totalCorrected}, rot=${result.rotation || 0}°, ${result.diag.totalMs}ms`);
});

