console.log("\n--- STAGE 52: Edge cases and byteplane-deflate compression ---");

test("byteplane-deflate compression roundtrip", () => {
  // Structured data that benefits from byteplane separation
  const data = new Uint8Array(500);
  for (let i = 0; i < 500; i++) data[i] = (i * 7) & 0xFF;
  const enc = renderer.encodeAndRender(data, "byteplane.bin", {
    configName: "128x128-4c",
    compFlag: codec.COMPRESS_FLAG_BYTEPLANE_DEFLATE,
  });
  const result = decodeEngine.decodeFrame(enc.img.data, enc.img.width, enc.img.height, {
    configName: "128x128-4c",
  });
  assert(result && result.decoded, "should decode byteplane-deflate");
  assert(result.hashValid === true, "hash should be valid");
  assert(result.payload.length === data.length, "payload length should match");
  let ok = true;
  for (let i = 0; i < data.length; i++) {
    if (result.payload[i] !== data[i]) { ok = false; break; }
  }
  assert(ok, "byteplane payload should match exactly");
  console.log(`   Byteplane-deflate: PASS — ${data.length} bytes exact match`);
});

