console.log("\n--- STAGE 57: Barrel distortion ---");

test("barrel distortion unit: estimator on clean image returns ~0", () => {
  const enc = renderer.encodeAndRender("distortion unit test", "du.bin", { configName: "128x128-4c" });
  const layout = format.computeSymbolLayout(128, 1136);
  const H = homography.computeHomography(
    format.computeCanonicalFinderPoints(layout),
    [
      { x: enc.img.width * 0.05, y: enc.img.height * 0.05 },
      { x: enc.img.width * 0.95, y: enc.img.height * 0.05 },
      { x: enc.img.width * 0.05, y: enc.img.height * 0.95 },
      { x: enc.img.width * 0.95, y: enc.img.height * 0.95 },
    ]
  );
  const est = decodeEngine.estimateBarrelDistortion(H, layout, enc.img.data, enc.img.width, enc.img.height);
  assert(Math.abs(est.k1) < 0.01, `clean image should have ~0 k1, got ${est.k1}`);
  console.log(`   Estimator on clean: PASS — k1=${est.k1.toFixed(6)}`);
});

