test("noise estimate monotonically increases with noise level", () => {
  const enc = renderer.encodeAndRender("monotonic test", "nmono.bin", { configName: "128x128-4c" });
  const sigmas = [0, 5, 15, 40];
  const estimates = sigmas.map(s => {
    const img = s === 0 ? enc.img : renderer.addGaussianNoise(enc.img, s);
    return decodeEngine.estimateNoiseSigma(img.data, img.width, img.height);
  });
  for (let i = 1; i < estimates.length; i++) {
    assert(estimates[i] >= estimates[i - 1],
      `monotonic: σ=${sigmas[i]} est=${estimates[i]} >= σ=${sigmas[i-1]} est=${estimates[i-1]}`);
  }
  console.log(`   monotonic: ${estimates.join(" → ")} — PASS`);
});

test("noise estimate on decode result matches standalone call", () => {
  const enc = renderer.encodeAndRender("match test", "nmatch.bin", { configName: "128x128-4c" });
  const noisy = renderer.addGaussianNoise(enc.img, 15);
  const standalone = decodeEngine.estimateNoiseSigma(noisy.data, noisy.width, noisy.height);
  const result = decodeEngine.decodeFrame(noisy.data, noisy.width, noisy.height, { configName: "128x128-4c" });
  assert(result && result.decoded, "should decode");
  // After potential sharpening, the image noise might differ slightly, but the estimate
  // at decode time should be close to standalone (both run on same input before sharpening)
  assert(result.noiseSigmaEst === standalone,
    `decode noiseSigmaEst=${result.noiseSigmaEst} should equal standalone=${standalone}`);
  console.log(`   decode vs standalone: ${result.noiseSigmaEst} === ${standalone} — PASS`);
});

