// =========================================================================
// STAGE 76: Cross-config encode/decode validation sweep
// =========================================================================
console.log("\n--- STAGE 76: Cross-config validation sweep ---");

const SWEEP_CONFIGS = [
  "128x128-4c", "128x128-8c",
  "192x192-4c", "192x192-8c",
  "256x256-4c", "256x256-8c", "256x256-16c",
];

for (const cfgName of SWEEP_CONFIGS) {
  test(`cross-config roundtrip: ${cfgName}`, () => {
    const msg = `Cross-config test payload for ${cfgName} — Aurexis V2`;
    const enc = renderer.encodeAndRender(msg, "sweep.txt", { configName: cfgName });
    assert(enc && enc.img, `encode failed for ${cfgName}`);
    assert.strictEqual(enc.configName, cfgName);
    assert(enc.stats, "has stats");

    const r = decodeEngine.decodeFrame(enc.img.data, enc.img.width, enc.img.height);
    assert(r && r.decoded, `decode failed for ${cfgName}: ${r ? r.failReason || r.error : "null"}`);
    assert.strictEqual(new TextDecoder().decode(r.payload), msg);
    assert.strictEqual(r.config, cfgName);
    const corr = r.rsStats ? r.rsStats.totalCorrected : 0;
    console.log(`   ${cfgName}: ${enc.img.width}×${enc.img.height}, ${enc.stats.totalEncodedBytes}B, corr=${corr} — PASS`);
  });
}

test("cross-config auto-detect roundtrip for all sweep configs", () => {
  // Auto-detect should identify each config from the image alone
  let detected = 0;
  for (const cfgName of SWEEP_CONFIGS) {
    const enc = renderer.encodeAndRender("Auto " + cfgName, "auto.txt", { configName: cfgName });
    const r = decodeEngine.decodeFrame(enc.img.data, enc.img.width, enc.img.height); // no configName hint
    if (r && r.decoded && r.config === cfgName) detected++;
    else console.log(`     auto-detect miss: ${cfgName} → ${r ? r.config : "null"}`);
  }
  console.log(`   auto-detect: ${detected}/${SWEEP_CONFIGS.length} correct — PASS`);
  assert(detected >= SWEEP_CONFIGS.length - 1, "at most 1 miss allowed");
});

test("cross-config with auto-compression", () => {
  let ok = 0;
  for (const cfgName of SWEEP_CONFIGS.slice(0, 4)) {
    const msg = "Auto-compress " + cfgName;
    const enc = renderer.encodeAndRender(msg, "ac.txt", { configName: cfgName, compFlag: "auto" });
    const r = decodeEngine.decodeFrame(enc.img.data, enc.img.width, enc.img.height);
    if (r && r.decoded && new TextDecoder().decode(r.payload) === msg) ok++;
  }
  console.log(`   auto-compress sweep: ${ok}/4 — PASS`);
  assert.strictEqual(ok, 4);
});

