console.log("\n--- STAGE 77: Shadow/occlusion resilience ---");

test("applyShadowOcclusion produces valid darkened image", () => {
  const enc = renderer.encodeAndRender("Shadow test", "sh.txt");
  const shadowed = renderer.applyShadowOcclusion(enc.img, "horizontal", 0.5, 0.15, 0.1);
  assert.strictEqual(shadowed.width, enc.img.width);
  assert.strictEqual(shadowed.height, enc.img.height);
  // Center should be darker than edges
  const cy = Math.floor(enc.img.height / 2);
  const centerIdx = (cy * enc.img.width + Math.floor(enc.img.width / 2)) * 4;
  const edgeIdx = 0; // top-left corner
  assert(shadowed.data[centerIdx] < enc.img.data[centerIdx], "center should be darkened");
  assert.strictEqual(shadowed.data[edgeIdx], enc.img.data[edgeIdx]); // edge unchanged
  console.log("   valid shadow output — PASS");
});

