test("color temp shift produces visible change", () => {
  const enc = renderer.encodeAndRender("Visible", "v.txt");
  const warm = renderer.applyColorTemperatureShift(enc.img, 0.5);
  // Sample from the center of the image (in the data region, not quiet zone)
  const cy = Math.floor(enc.img.height / 2);
  const startIdx = (cy * enc.img.width + Math.floor(enc.img.width / 3)) * 4;
  let rDiff = 0, bDiff = 0;
  for (let i = startIdx; i < startIdx + 400; i += 4) {
    rDiff += warm.data[i] - enc.img.data[i];
    bDiff += warm.data[i + 2] - enc.img.data[i + 2];
  }
  assert(rDiff >= 0, "warm should increase or maintain red");
  assert(bDiff <= 0, "warm should decrease or maintain blue");
  // At least one channel should change for non-white pixels
  assert(rDiff > 0 || bDiff < 0, "at least one channel should shift");
  console.log("   visible warm shift — PASS");
});

