test("scenario 1: indoor desk scan (warm light, slight warp, noise)", () => {
  const msg = "Indoor desk scan — Aurexis V2 real-world test payload";
  const enc = renderer.encodeAndRender(msg, "indoor.txt");
  const W = enc.img.width, H = enc.img.height;
  // Mild perspective warp (phone at slight angle)
  const src = [{x:0,y:0},{x:W,y:0},{x:0,y:H},{x:W,y:H}];
  const dst = [{x:5,y:3},{x:W-8,y:1},{x:2,y:H-5},{x:W-4,y:H-3}];
  let img = renderer.perspectiveWarp(enc.img, W, H, src, dst);
  // Warm indoor lighting
  img = renderer.applyColorTemperatureShift(img, 0.3);
  // Slight underexposure
  img = renderer.applyGammaShift(img, 1.3);
  // Sensor noise
  img = renderer.addGaussianNoise(img, 6);
  const r = decodeEngine.decodeFrame(img.data, img.width, img.height);
  assert(r && r.decoded, "indoor scan should decode");
  assert.strictEqual(new TextDecoder().decode(r.payload), msg);
  console.log(`   indoor: corr=${r.rsStats.totalCorrected}, confidence=${r.confidence} — PASS`);
});

test("scenario 2: outdoor bright scan (overexposed, high contrast, blur)", () => {
  const msg = "Outdoor bright scan payload for Aurexis V2";
  const enc = renderer.encodeAndRender(msg, "outdoor.txt");
  // Overexposure
  let img = renderer.applyGammaShift(enc.img, 0.6);
  // High contrast from direct sunlight
  img = renderer.applyContrastShift(img, 1.4);
  // Slight motion blur from handheld
  img = renderer.applyMotionBlur(img, 3, 15);
  // Mild noise
  img = renderer.addGaussianNoise(img, 5);
  const r = decodeEngine.decodeFrame(img.data, img.width, img.height);
  assert(r && r.decoded, "outdoor scan should decode");
  assert.strictEqual(new TextDecoder().decode(r.payload), msg);
  console.log(`   outdoor: corr=${r.rsStats.totalCorrected}, confidence=${r.confidence} — PASS`);
});

test("scenario 3: printed + photographed (low sat, pad, warp, noise)", () => {
  const msg = "Printed artifact captured by phone";
  const enc = renderer.encodeAndRender(msg, "print.txt");
  const W = enc.img.width, H = enc.img.height;
  // Background padding (artifact on desk)
  let img = renderer.padImage(enc.img, 40, 40, 40, 40);
  const pW = img.width, pH = img.height;
  // Perspective from phone angle
  const src = [{x:0,y:0},{x:pW,y:0},{x:0,y:pH},{x:pW,y:pH}];
  const dst = [{x:10,y:8},{x:pW-12,y:3},{x:5,y:pH-10},{x:pW-7,y:pH-6}];
  img = renderer.perspectiveWarp(img, pW, pH, src, dst);
  // Print desaturation
  img = renderer.applySaturationShift(img, 0.7);
  // Ambient noise
  img = renderer.addGaussianNoise(img, 8);
  const r = decodeEngine.decodeFrame(img.data, img.width, img.height);
  assert(r && r.decoded, "printed scan should decode");
  assert.strictEqual(new TextDecoder().decode(r.payload), msg);
  console.log(`   print: corr=${r.rsStats.totalCorrected}, confidence=${r.confidence} — PASS`);
});

