test("scenario 6: worst-case multi-frame recovery", () => {
  const msg = "Multi-frame worst case";
  const enc = renderer.encodeAndRender(msg, "mf.txt");
  const W = enc.img.width, H = enc.img.height;

  // Frame 0: heavy noise
  const f0 = renderer.addGaussianNoise(enc.img, 20);
  // Frame 1: warp + noise
  const src = [{x:0,y:0},{x:W,y:0},{x:0,y:H},{x:W,y:H}];
  const dst = [{x:5,y:5},{x:W-8,y:2},{x:3,y:H-6},{x:W-4,y:H-3}];
  let f1 = renderer.perspectiveWarp(enc.img, W, H, src, dst);
  f1 = renderer.addGaussianNoise(f1, 10);
  // Frame 2: gamma + color shift
  let f2 = renderer.applyGammaShift(enc.img, 1.5);
  f2 = renderer.applyColorTemperatureShift(f2, 0.4);
  f2 = renderer.addGaussianNoise(f2, 8);

  const mr = decodeEngine.decodeMultiFrame([
    { imgData: f0.data, width: f0.width, height: f0.height },
    { imgData: f1.data, width: f1.width, height: f1.height },
    { imgData: f2.data, width: f2.width, height: f2.height },
  ]);
  assert(mr.successCount >= 1, "at least one frame should decode");
  assert(mr.best && mr.best.decoded);
  assert.strictEqual(new TextDecoder().decode(mr.best.payload), msg);
  console.log(`   multi-frame: ${mr.successCount}/3, best=idx${mr.best._frameIndex}, corr=${mr.best.rsStats.totalCorrected} — PASS`);
});

