test("createDecodeSession returns session object with expected API", () => {
  const session = decodeEngine.createDecodeSession();
  assert(typeof session.addFrame === "function", "addFrame");
  assert(typeof session.getBest === "function", "getBest");
  assert(typeof session.getResults === "function", "getResults");
  assert(typeof session.getStats === "function", "getStats");
  assert(typeof session.finalize === "function", "finalize");
});

test("streaming: single good frame → decoded", () => {
  const msg = "Streaming single frame";
  const enc = renderer.encodeAndRender(msg, "stream1.txt");
  const session = decodeEngine.createDecodeSession();
  const res = session.addFrame(enc.img.data, enc.img.width, enc.img.height);
  assert(res.accepted, "accepted");
  assert(res.decoded, "decoded");
  assert(res.isNewBest, "isNewBest");
  const best = session.getBest();
  assert(best && best.decoded);
  assert.strictEqual(new TextDecoder().decode(best.payload), msg);
});

test("streaming: multiple frames, best selected by lowest corrections", () => {
  const msg = "Multi-frame streaming test";
  const enc = renderer.encodeAndRender(msg, "stream2.txt");
  const session = decodeEngine.createDecodeSession();
  // Frame 0: noisy
  const noisy = renderer.addGaussianNoise(enc.img, 18);
  session.addFrame(noisy.data, noisy.width, noisy.height);
  // Frame 1: clean
  session.addFrame(enc.img.data, enc.img.width, enc.img.height);
  // Frame 2: slightly noisy
  const mild = renderer.addGaussianNoise(enc.img, 5);
  session.addFrame(mild.data, mild.width, mild.height);
  const stats = session.getStats();
  assert(stats.successCount >= 2, `successCount=${stats.successCount}`);
  const best = session.getBest();
  assert(best && best.decoded);
  assert.strictEqual(new TextDecoder().decode(best.payload), msg);
  // Best should be the clean frame (idx 1) with 0 corrections
  assert(best.rsStats.totalCorrected === 0 || best._frameIndex === 1,
    `best should be clean frame, got idx=${best._frameIndex}`);
});

test("streaming: failed frames don't crash, stats correct", () => {
  const session = decodeEngine.createDecodeSession();
  // Feed blank image
  const blank = renderer.createRGBA(100, 100);
  const r1 = session.addFrame(blank.data, blank.width, blank.height);
  assert(r1.accepted);
  assert(!r1.decoded);
  assert.strictEqual(r1.failReason, "NO_FINDERS");
  const stats = session.getStats();
  assert.strictEqual(stats.framesProcessed, 1);
  assert.strictEqual(stats.successCount, 0);
  assert.strictEqual(stats.bestFrameIndex, null);
});

test("streaming: early stop at confidence threshold", () => {
  const msg = "Early stop test";
  const enc = renderer.encodeAndRender(msg, "stop.txt");
  const session = decodeEngine.createDecodeSession({ earlyStopConfidence: 90 });
  // Clean frame should get confidence=100 → triggers early stop
  session.addFrame(enc.img.data, enc.img.width, enc.img.height);
  const stats = session.getStats();
  assert(stats.stopped, "should be stopped after high-confidence frame");
  // Further frames should be rejected
  const r2 = session.addFrame(enc.img.data, enc.img.width, enc.img.height);
  assert(!r2.accepted);
  assert.strictEqual(r2.reason, "early_stop");
});

test("streaming: maxFrames auto-finalizes", () => {
  const msg = "Max frames test";
  const enc = renderer.encodeAndRender(msg, "max.txt");
  // Disable early stop so maxFrames is what finalizes
  const session = decodeEngine.createDecodeSession({ maxFrames: 2, earlyStopConfidence: 101 });
  session.addFrame(enc.img.data, enc.img.width, enc.img.height);
  session.addFrame(enc.img.data, enc.img.width, enc.img.height);
  // Third frame should throw (finalized)
  let threw = false;
  try {
    session.addFrame(enc.img.data, enc.img.width, enc.img.height);
  } catch (e) {
    threw = true;
    assert(e.message.includes("finalized"));
  }
  assert(threw, "should throw after maxFrames");
});

test("streaming: finalize returns summary", () => {
  const msg = "Finalize test";
  const enc = renderer.encodeAndRender(msg, "fin.txt");
  const session = decodeEngine.createDecodeSession();
  session.addFrame(enc.img.data, enc.img.width, enc.img.height);
  const noisy = renderer.addGaussianNoise(enc.img, 15);
  session.addFrame(noisy.data, noisy.width, noisy.height);
  const summary = session.finalize();
  assert(summary.best && summary.best.decoded);
  assert.strictEqual(summary.results.length, 2);
  assert(summary.stats.elapsedMs >= 0);
  assert.strictEqual(summary.stats.framesProcessed, 2);
});

test("streaming: elapsedMs increases over time", () => {
  const session = decodeEngine.createDecodeSession();
  const s1 = session.getStats();
  assert(s1.elapsedMs >= 0);
  assert.strictEqual(s1.framesProcessed, 0);
});

