test("encodeBatch encodes multiple payloads", () => {
  const items = [
    { payload: "First payload", filename: "a.txt" },
    { payload: "Second payload", filename: "b.txt" },
    { payload: "Third payload", filename: "c.txt" },
  ];
  const results = renderer.encodeBatch(items);
  assert.strictEqual(results.length, 3);
  results.forEach((r, i) => {
    assert(r.ok, `item ${i} ok`);
    assert.strictEqual(r.index, i);
    assert(r.result.img);
    assert(r.result.stats);
  });
});

test("encodeBatch roundtrip — all decode correctly", () => {
  const messages = ["Alpha", "Beta", "Gamma"];
  const items = messages.map((m, i) => ({ payload: m, filename: `batch${i}.txt` }));
  const results = renderer.encodeBatch(items);
  for (let i = 0; i < results.length; i++) {
    assert(results[i].ok);
    const r = decodeEngine.decodeFrame(results[i].result.img.data, results[i].result.img.width, results[i].result.img.height);
    assert(r && r.decoded, `batch item ${i} decode`);
    assert.strictEqual(new TextDecoder().decode(r.payload), messages[i]);
  }
});

test("encodeBatch with shared opts", () => {
  const items = [
    { payload: "Shared opts test 1", filename: "s1.txt" },
    { payload: "Shared opts test 2", filename: "s2.txt" },
  ];
  const results = renderer.encodeBatch(items, { configName: "128x128-4c" });
  assert.strictEqual(results.length, 2);
  results.forEach(r => assert(r.ok));
});

test("encodeBatch per-item opts override shared", () => {
  const items = [
    { payload: "Per-item A", filename: "pi1.txt", opts: { compFlag: codec.COMPRESS_FLAG_NONE } },
    { payload: "Per-item B", filename: "pi2.txt" },
  ];
  const results = renderer.encodeBatch(items, { compFlag: "auto" });
  assert.strictEqual(results.length, 2);
  assert(results[0].ok);
  assert(results[1].ok);
  // First should use 'none' compression
  assert.strictEqual(results[0].result.stats.compressionMethod, "none");
});

test("encodeBatch handles errors gracefully", () => {
  const items = [
    { payload: "Good item", filename: "good.txt" },
    { payload: null, filename: "bad.txt" },  // will fail validation
    { payload: "Also good", filename: "ok.txt" },
  ];
  const results = renderer.encodeBatch(items);
  assert.strictEqual(results.length, 3);
  assert(results[0].ok);
  assert(!results[1].ok);
  assert(results[1].error);
  assert(results[2].ok);
});

test("encodeBatch empty array throws", () => {
  let threw = false;
  try { renderer.encodeBatch([]); } catch (e) { threw = true; }
  assert(threw, "should throw on empty array");
});

test("encodeBatch missing fields handled", () => {
  const items = [
    { payload: "OK", filename: "ok.txt" },
    { filename: "no-payload.txt" },  // missing payload
    { payload: "no filename" },       // missing filename
  ];
  const results = renderer.encodeBatch(items);
  assert(results[0].ok);
  assert(!results[1].ok);
  assert(!results[2].ok);
});

