// STAGE 86: Enhanced EC capacity reporting in decode results
// =========================================================================
console.log("\n--- STAGE 86: Enhanced EC capacity reporting ---");

test("successful decode includes maxAdditionalErrors and correctionHeadroom", () => {
  const msg = "EC headroom test payload";
  const enc = renderer.encodeAndRender(msg, "ec.txt");
  const r = decodeEngine.decodeFrame(enc.img.data, enc.img.width, enc.img.height);
  assert(r && r.decoded);
  const rs = r.rsStats;
  assert(typeof rs.maxAdditionalErrors === "number", "maxAdditionalErrors present");
  assert(typeof rs.correctionHeadroom === "number", "correctionHeadroom present");
  assert(rs.correctionHeadroom >= 0 && rs.correctionHeadroom <= 1, "headroom in [0,1]");
  // Clean image: 0 corrections → full headroom
  assert.strictEqual(rs.maxAdditionalErrors, rs.correctionCapacity);
  assert.strictEqual(rs.correctionHeadroom, 1);
});

test("noisy decode shows reduced headroom", () => {
  const msg = "Noisy EC test payload";
  const enc = renderer.encodeAndRender(msg, "nec.txt");
  const noisy = renderer.addGaussianNoise(enc.img, 18);
  const r = decodeEngine.decodeFrame(noisy.data, noisy.width, noisy.height);
  if (r && r.decoded && r.rsStats.totalCorrected > 0) {
    assert(r.rsStats.correctionHeadroom < 1, "headroom should be less than 1 when corrections used");
    assert(r.rsStats.maxAdditionalErrors < r.rsStats.correctionCapacity, "maxAdditional < capacity");
    assert.strictEqual(r.rsStats.maxAdditionalErrors, r.rsStats.correctionCapacity - r.rsStats.totalCorrected);
    console.log(`   noisy: corr=${r.rsStats.totalCorrected}/${r.rsStats.correctionCapacity}, headroom=${(r.rsStats.correctionHeadroom*100).toFixed(1)}%`);
  } else {
    console.log("   noisy: no corrections needed or decode failed — PASS (skip)");
  }
});

test("correctionCapacity matches numBlocks * nsym/2", () => {
  const msg = "Capacity formula test";
  const enc = renderer.encodeAndRender(msg, "cap.txt");
  const r = decodeEngine.decodeFrame(enc.img.data, enc.img.width, enc.img.height);
  assert(r && r.decoded);
  const expectedCap = r.rsStats.numBlocks * Math.floor(r.nsym / 2);
  assert.strictEqual(r.rsStats.correctionCapacity, expectedCap, "capacity = blocks * nsym/2");
});

test("correctionUsedPct consistent with totalCorrected / correctionCapacity", () => {
  const msg = "Pct consistency test";
  const enc = renderer.encodeAndRender(msg, "pct.txt");
  const noisy = renderer.addGaussianNoise(enc.img, 20);
  const r = decodeEngine.decodeFrame(noisy.data, noisy.width, noisy.height);
  if (r && r.decoded) {
    const expectedPct = r.rsStats.correctionCapacity > 0
      ? Math.round(r.rsStats.totalCorrected / r.rsStats.correctionCapacity * 1000) / 10
      : 0;
    assert.strictEqual(r.rsStats.correctionUsedPct, expectedPct);
  }
});

test("EC stats present with nsym=64 high-redundancy", () => {
  const msg = "High-red EC test";
  const enc = renderer.encodeAndRender(msg, "hrec.txt", { nsym: 64 });
  const r = decodeEngine.decodeFrame(enc.img.data, enc.img.width, enc.img.height);
  assert(r && r.decoded);
  // nsym=64 → each block corrects up to 32 symbols
  const cap = r.rsStats.correctionCapacity;
  assert(cap > 0, "has capacity");
  assert(typeof r.rsStats.maxAdditionalErrors === "number");
  assert(typeof r.rsStats.correctionHeadroom === "number");
});

test("maxAdditionalErrors + totalCorrected = correctionCapacity", () => {
  const msg = "Additive check";
  const enc = renderer.encodeAndRender(msg, "add.txt");
  const noisy = renderer.addGaussianNoise(enc.img, 15);
  const r = decodeEngine.decodeFrame(noisy.data, noisy.width, noisy.height);
  if (r && r.decoded) {
    assert.strictEqual(
      r.rsStats.maxAdditionalErrors + r.rsStats.totalCorrected,
      r.rsStats.correctionCapacity,
      "max + corrected = capacity"
    );
  }
});

