console.log("\n--- STAGE 89: Progressive partial result tracking ---");

test("streaming session exposes getBestPartial()", () => {
  const session = decodeEngine.createDecodeSession();
  assert(typeof session.getBestPartial === "function");
  assert.strictEqual(session.getBestPartial(), null);
});

test("streaming stats include partialCount", () => {
  const session = decodeEngine.createDecodeSession();
  const stats = session.getStats();
  assert.strictEqual(stats.partialCount, 0);
  assert.strictEqual(stats.bestPartialRate, null);
});

test("finalize includes bestPartial field", () => {
  const enc = renderer.encodeAndRender("Partial fin", "pf.txt");
  const session = decodeEngine.createDecodeSession();
  session.addFrame(enc.img.data, enc.img.width, enc.img.height);
  const summary = session.finalize();
  assert("bestPartial" in summary, "bestPartial field present");
});

test("streaming: successful decode → bestPartial stays null", () => {
  const enc = renderer.encodeAndRender("No partial needed", "npn.txt");
  const session = decodeEngine.createDecodeSession();
  session.addFrame(enc.img.data, enc.img.width, enc.img.height);
  assert(session.getBest() !== null, "best should be set");
  assert.strictEqual(session.getBestPartial(), null, "no partial for clean decode");
});

test("streaming: failed frame returns bestPartial in response", () => {
  const session = decodeEngine.createDecodeSession();
  const blank = renderer.createRGBA(100, 100);
  const r = session.addFrame(blank.data, blank.width, blank.height);
  assert(!r.decoded);
  // bestPartial may or may not be set depending on failure type
  assert("bestPartial" in r, "response includes bestPartial field");
});

test("streaming: mixed success/fail tracking", () => {
  const session = decodeEngine.createDecodeSession({ earlyStopConfidence: 101 });
  const enc = renderer.encodeAndRender("Mix track", "mt.txt");
  // Good frame
  session.addFrame(enc.img.data, enc.img.width, enc.img.height);
  // Bad frame
  const blank = renderer.createRGBA(100, 100);
  session.addFrame(blank.data, blank.width, blank.height);
  const stats = session.getStats();
  assert.strictEqual(stats.framesProcessed, 2);
  assert.strictEqual(stats.successCount, 1);
  assert(stats.bestConfidence !== null);
});

