test("128-4c vs 192-4c JPEG quality threshold comparison", () => {
  const msg128 = "JPEG threshold 128";
  const msg192 = "JPEG threshold 192";
  const enc128 = renderer.encodeAndRender(msg128, "jt128.txt", { configName: "128x128-4c" });
  const enc192 = renderer.encodeAndRender(msg192, "jt192.txt", { configName: "192x192-4c" });
  const q = 60;
  const jpg128 = renderer.simulateJpegCompression(enc128.img, q);
  const jpg192 = renderer.simulateJpegCompression(enc192.img, q);
  const r128 = decodeEngine.decodeFrame(jpg128.data, jpg128.width, jpg128.height);
  const r192 = decodeEngine.decodeFrame(jpg192.data, jpg192.width, jpg192.height);
  const d128 = r128 && r128.decoded;
  const d192 = r192 && r192.decoded;
  console.log(`   Q=${q}: 128-4c ${d128 ? "PASS corr=" + r128.rsStats.totalCorrected : "FAIL"}, 192-4c ${d192 ? "PASS corr=" + r192.rsStats.totalCorrected : "FAIL"}`);
  // At least one should decode at Q=60
  assert(d128 || d192, "at least one config should survive Q=60");
});

