console.log("\n--- STAGE 92: Payload type detection ---");

test("detectPayloadType: plain text", () => {
  const payload = new TextEncoder().encode("Hello, this is plain text content.");
  const t = decodeEngine.detectPayloadType(payload, "test.txt");
  assert.strictEqual(t.type, "text");
  assert.strictEqual(t.subtype, "text/plain");
  assert(t.confidence >= 80);
  assert(t.details.size === payload.length);
});

test("detectPayloadType: JSON content", () => {
  const payload = new TextEncoder().encode('{"key": "value", "num": 42}');
  const t = decodeEngine.detectPayloadType(payload, "data.json");
  assert.strictEqual(t.type, "text");
  assert.strictEqual(t.subtype, "text/json");
});

test("detectPayloadType: HTML content", () => {
  const payload = new TextEncoder().encode("<!DOCTYPE html><html><body>Hello</body></html>");
  const t = decodeEngine.detectPayloadType(payload);
  assert.strictEqual(t.type, "text");
  assert.strictEqual(t.subtype, "text/html");
});

test("detectPayloadType: binary with nulls", () => {
  const payload = new Uint8Array(100);
  // Fill with mix of binary data including nulls
  for (let i = 0; i < 100; i++) payload[i] = i % 3 === 0 ? 0 : (i * 7) & 0xFF;
  const t = decodeEngine.detectPayloadType(payload);
  assert.strictEqual(t.type, "binary");
});

test("detectPayloadType: PNG magic bytes", () => {
  const payload = new Uint8Array([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A, ...new Array(100).fill(0)]);
  const t = decodeEngine.detectPayloadType(payload, "image.png");
  assert.strictEqual(t.type, "binary");
  assert.strictEqual(t.subtype, "image/png");
  assert.strictEqual(t.details.format, "PNG");
  assert(t.confidence >= 95);
});

test("detectPayloadType: JPEG magic bytes", () => {
  const payload = new Uint8Array([0xFF, 0xD8, 0xFF, 0xE0, ...new Array(50).fill(0)]);
  const t = decodeEngine.detectPayloadType(payload);
  assert.strictEqual(t.subtype, "image/jpeg");
});

test("detectPayloadType: empty payload", () => {
  const t = decodeEngine.detectPayloadType(new Uint8Array(0));
  assert.strictEqual(t.type, "empty");
  assert.strictEqual(t.details.size, 0);
});

test("detectPayloadType: PDF magic bytes", () => {
  const payload = new TextEncoder().encode("%PDF-1.4 rest of pdf data here");
  const t = decodeEngine.detectPayloadType(payload);
  assert.strictEqual(t.subtype, "application/pdf");
});

test("detectPayloadType: filename extension hint", () => {
  const payload = new TextEncoder().encode("name,age\nAlice,30\nBob,25");
  const t = decodeEngine.detectPayloadType(payload, "data.csv");
  assert.strictEqual(t.type, "text");
  assert.strictEqual(t.subtype, "text/csv");
});

test("detectPayloadType: integrated with decode result", () => {
  const msg = "Payload type integration test data";
  const enc = renderer.encodeAndRender(msg, "ptype.txt");
  const r = decodeEngine.decodeFrame(enc.img.data, enc.img.width, enc.img.height);
  assert(r && r.decoded);
  const t = decodeEngine.detectPayloadType(r.payload, r.filename);
  assert.strictEqual(t.type, "text");
  assert.strictEqual(t.subtype, "text/plain");
  assert(t.details.printableRatio > 0.9);
});

