test("streaming session decodes different configs across frames", () => {
  const msg128 = "Config 128 frame";
  const msg192 = "Config 192 frame";
  const enc128 = renderer.encodeAndRender(msg128, "c128.txt", { configName: "128x128-4c" });
  const enc192 = renderer.encodeAndRender(msg192, "c192.txt", { configName: "192x192-4c" });
  const session = decodeEngine.createDecodeSession({ earlyStopConfidence: 101 });
  // Feed 128 frame
  const r1 = session.addFrame(enc128.img.data, enc128.img.width, enc128.img.height);
  assert(r1.decoded, "128 frame decoded");
  // Feed 192 frame
  const r2 = session.addFrame(enc192.img.data, enc192.img.width, enc192.img.height);
  assert(r2.decoded, "192 frame decoded");
  const stats = session.getStats();
  assert.strictEqual(stats.successCount, 2);
  assert.strictEqual(stats.framesProcessed, 2);
});

test("streaming: best across different configs picked by corrections", () => {
  const msg = "Cross config best";
  const enc128 = renderer.encodeAndRender(msg, "ccb128.txt", { configName: "128x128-4c" });
  const enc192 = renderer.encodeAndRender(msg, "ccb192.txt", { configName: "192x192-4c" });
  const session = decodeEngine.createDecodeSession({ earlyStopConfidence: 101 });
  // Feed noisy 128
  const noisy128 = renderer.addGaussianNoise(enc128.img, 15);
  session.addFrame(noisy128.data, noisy128.width, noisy128.height);
  // Feed clean 192
  session.addFrame(enc192.img.data, enc192.img.width, enc192.img.height);
  const best = session.getBest();
  assert(best && best.decoded);
  // Best should be the clean 192 frame
  assert.strictEqual(best.rsStats.totalCorrected, 0, "clean frame wins");
  assert.strictEqual(new TextDecoder().decode(best.payload), msg);
});

test("streaming: mixed config + failure frames", () => {
  const session = decodeEngine.createDecodeSession({ earlyStopConfidence: 101 });
  // Bad frame
  const blank = renderer.createRGBA(100, 100);
  session.addFrame(blank.data, blank.width, blank.height);
  // Good 128 frame
  const enc = renderer.encodeAndRender("Mixed config", "mc.txt");
  session.addFrame(enc.img.data, enc.img.width, enc.img.height);
  // Another bad frame
  session.addFrame(blank.data, blank.width, blank.height);
  const stats = session.getStats();
  assert.strictEqual(stats.framesProcessed, 3);
  assert.strictEqual(stats.successCount, 1);
  assert(session.getBest() !== null);
});

