console.log("\n--- STAGE 98: Decode diagnostics summary ---");

test("summarizeDiagnostics on successful decode", () => {
  const enc = renderer.encodeAndRender("Diag test", "diag.txt");
  const r = decodeEngine.decodeFrame(enc.img.data, enc.img.width, enc.img.height);
  const diag = decodeEngine.summarizeDiagnostics(r);
  assert(diag.summary.includes("SUCCESS"));
  assert(diag.summary.includes("128x128-4c"));
  assert(diag.stages.length > 0);
  assert(diag.quality !== null);
  assert.strictEqual(diag.quality.confidence, 100);
  assert.strictEqual(diag.decoded, true);
  assert.strictEqual(diag.failReason, null);
  console.log(`   stages: ${diag.stages.map(s => s.name).join(",")}`);
});

test("summarizeDiagnostics includes stage timings", () => {
  const enc = renderer.encodeAndRender("Timing diag", "tdiag.txt");
  const r = decodeEngine.decodeFrame(enc.img.data, enc.img.width, enc.img.height);
  const diag = decodeEngine.summarizeDiagnostics(r);
  for (const s of diag.stages) {
    assert(typeof s.ms === "number", `${s.name} has ms`);
    assert(typeof s.status === "string", `${s.name} has status`);
    assert(typeof s.detail === "string", `${s.name} has detail`);
  }
  // Must have at least blur, finder, format, rsDecode, verify
  const names = diag.stages.map(s => s.name);
  assert(names.includes("blur"), "has blur");
  assert(names.includes("finder"), "has finder");
  assert(names.includes("rsDecode"), "has rsDecode");
});

test("summarizeDiagnostics on failed decode (NO_FINDERS)", () => {
  const blank = renderer.createRGBA(100, 100);
  const r = decodeEngine.decodeFrame(blank.data, blank.width, blank.height);
  const diag = decodeEngine.summarizeDiagnostics(r);
  assert(diag.summary.includes("FAILED"));
  assert.strictEqual(diag.decoded, false);
  assert.strictEqual(diag.failReason, "NO_FINDERS");
  assert.strictEqual(diag.quality, null);
});

test("summarizeDiagnostics on null returns empty", () => {
  const diag = decodeEngine.summarizeDiagnostics(null);
  assert.strictEqual(diag.summary, "No result");
  assert.strictEqual(diag.stages.length, 0);
});

test("summarizeDiagnostics quality metrics", () => {
  const enc = renderer.encodeAndRender("Quality metrics", "qm.txt");
  const noisy = renderer.addGaussianNoise(enc.img, 15);
  const r = decodeEngine.decodeFrame(noisy.data, noisy.width, noisy.height);
  if (r && r.decoded) {
    const diag = decodeEngine.summarizeDiagnostics(r);
    assert(diag.quality !== null);
    assert(typeof diag.quality.corrections === "number");
    assert(typeof diag.quality.correctionCapacity === "number");
    assert(typeof diag.quality.headroomPct === "number");
    assert(diag.quality.headroomPct >= 0 && diag.quality.headroomPct <= 100);
    console.log(`   quality: corr=${diag.quality.corrections}, headroom=${diag.quality.headroomPct}%`);
  }
});

