test("compareDecodeResults — reversed order same magnitude", () => {
  const enc = renderer.encodeAndRender("Rev test", "rev.txt");
  const clean = decodeEngine.decodeFrame(enc.img.data, enc.img.width, enc.img.height);
  const noisy = renderer.addGaussianNoise(enc.img, 12);
  const nr = decodeEngine.decodeFrame(noisy.data, noisy.width, noisy.height);
  if (nr && nr.decoded) {
    const cmpAB = decodeEngine.compareDecodeResults(clean, nr);
    const cmpBA = decodeEngine.compareDecodeResults(nr, clean);
    if (cmpAB.winner === "a") assert.strictEqual(cmpBA.winner, "b");
    else if (cmpAB.winner === "b") assert.strictEqual(cmpBA.winner, "a");
    else assert.strictEqual(cmpBA.winner, "tie");
    console.log(`   reversed: AB=${cmpAB.winner}, BA=${cmpBA.winner}`);
  } else {
    console.log(`   reversed: noisy failed, skipping symmetry check`);
  }
});

