test("small payload — no chunking needed", () => {
  const result = renderer.chunkPayload("Hello world", { configName: "128x128-4c" });
  assert.strictEqual(result.chunked, false);
  assert.strictEqual(result.totalChunks, 1);
  assert.strictEqual(result.chunks.length, 1);
});

test("large payload — chunks created", () => {
  const cap = renderer.getCapacity("128x128-4c");
  const bigPayload = new Uint8Array(cap.usablePayloadBytes * 3);
  for (let i = 0; i < bigPayload.length; i++) bigPayload[i] = i & 0xFF;
  const result = renderer.chunkPayload(bigPayload, { configName: "128x128-4c" });
  assert(result.chunked, "should be chunked");
  assert(result.totalChunks >= 3, `totalChunks=${result.totalChunks}`);
  assert.strictEqual(result.chunks.length, result.totalChunks);
  console.log(`   ${bigPayload.length}B → ${result.totalChunks} chunks (max ${result.maxChunkData}B each)`);
});

test("chunk + reassemble roundtrip", () => {
  const cap = renderer.getCapacity("128x128-4c");
  const payload = new Uint8Array(cap.usablePayloadBytes * 2 + 100);
  for (let i = 0; i < payload.length; i++) payload[i] = (i * 7 + 13) & 0xFF;
  const chunked = renderer.chunkPayload(payload, { configName: "128x128-4c" });
  assert(chunked.chunked);
  // Reassemble from chunk data
  const chunkPayloads = chunked.chunks.map(c => c.data);
  const reassembled = renderer.reassembleChunks(chunkPayloads);
  assert.strictEqual(reassembled.totalLength, payload.length);
  assert.strictEqual(reassembled.payload.length, payload.length);
  for (let i = 0; i < payload.length; i++) {
    assert.strictEqual(reassembled.payload[i], payload[i]);
  }
  console.log(`   roundtrip: ${payload.length}B → ${chunked.totalChunks} chunks → reassembled OK`);
});

test("chunk headers have correct metadata", () => {
  const cap = renderer.getCapacity("128x128-4c");
  const payload = new Uint8Array(cap.usablePayloadBytes * 2);
  const chunked = renderer.chunkPayload(payload, { configName: "128x128-4c" });
  for (let i = 0; i < chunked.chunks.length; i++) {
    assert.strictEqual(chunked.chunks[i].header.chunkIndex, i);
    assert.strictEqual(chunked.chunks[i].header.totalChunks, chunked.totalChunks);
    assert.strictEqual(chunked.chunks[i].header.totalLength, payload.length);
    assert(chunked.chunks[i].header.seqId > 0);
  }
});

test("reassemble rejects mismatched seqIds", () => {
  const cap = renderer.getCapacity("128x128-4c");
  const payload = new Uint8Array(cap.usablePayloadBytes * 2);
  const chunked = renderer.chunkPayload(payload, { configName: "128x128-4c" });
  // Tamper with seqId in second chunk
  const chunkPayloads = chunked.chunks.map(c => new Uint8Array(c.data));
  const dv = new DataView(chunkPayloads[1].buffer, chunkPayloads[1].byteOffset, 16);
  dv.setUint32(4, 999999, true); // corrupt seqId
  let threw = false;
  try { renderer.reassembleChunks(chunkPayloads); } catch (e) { threw = true; }
  assert(threw, "should throw on mismatched seqId");
});

test("reassemble rejects missing chunks", () => {
  const cap = renderer.getCapacity("128x128-4c");
  const payload = new Uint8Array(cap.usablePayloadBytes * 3);
  const chunked = renderer.chunkPayload(payload, { configName: "128x128-4c" });
  // Only pass first 2 chunks
  const partial = chunked.chunks.slice(0, 2).map(c => c.data);
  let threw = false;
  try { renderer.reassembleChunks(partial); } catch (e) { threw = true; }
  assert(threw, "should throw on missing chunks");
});

test("chunk with string payload", () => {
  const cap = renderer.getCapacity("128x128-4c");
  const longStr = "A".repeat(cap.usablePayloadBytes * 2);
  const chunked = renderer.chunkPayload(longStr, { configName: "128x128-4c" });
  assert(chunked.chunked);
  const reassembled = renderer.reassembleChunks(chunked.chunks.map(c => c.data));
  const decoded = new TextDecoder().decode(reassembled.payload);
  assert.strictEqual(decoded, longStr);
});

