console.log("\n--- STAGE 110: Payload diff ---");

test("diffPayloads identical — no diffs", () => {
  const a = new Uint8Array([1, 2, 3, 4, 5]);
  const d = decodeEngine.diffPayloads(a, a);
  assert(d.identical);
  assert.strictEqual(d.diffCount, 0);
  assert.strictEqual(d.matchRate, 100);
});

test("diffPayloads — byte differences found", () => {
  const a = new Uint8Array([1, 2, 3, 4, 5]);
  const b = new Uint8Array([1, 9, 3, 9, 5]);
  const d = decodeEngine.diffPayloads(a, b);
  assert(!d.identical);
  assert.strictEqual(d.diffCount, 2);
  assert.strictEqual(d.diffs[0].offset, 1);
  assert.strictEqual(d.diffs[0].expected, 2);
  assert.strictEqual(d.diffs[0].actual, 9);
});

test("diffPayloads — length mismatch", () => {
  const a = new Uint8Array([1, 2, 3]);
  const b = new Uint8Array([1, 2, 3, 4, 5]);
  const d = decodeEngine.diffPayloads(a, b);
  assert(!d.lengthMatch);
  assert.strictEqual(d.expectedLength, 3);
  assert.strictEqual(d.actualLength, 5);
  assert.strictEqual(d.diffCount, 2);
});

test("diffPayloads — string inputs", () => {
  const d = decodeEngine.diffPayloads("hello", "hallo");
  assert(!d.identical);
  assert.strictEqual(d.diffCount, 1);
  assert.strictEqual(d.diffs[0].offset, 1);
});

test("diffPayloads — caps at 100 diffs", () => {
  const a = new Uint8Array(200);
  const b = new Uint8Array(200);
  for (let i = 0; i < 200; i++) { a[i] = 0; b[i] = 1; }
  const d = decodeEngine.diffPayloads(a, b);
  assert.strictEqual(d.diffs.length, 100);
  assert(d.truncated);
  assert.strictEqual(d.diffCount, 200);
});

test("diffPayloads — encode→corrupt→diff", () => {
  const msg = "Test corruption detection payload";
  const enc = renderer.encodeAndRender(msg, "diff.txt");
  const r = decodeEngine.decodeFrame(enc.img.data, enc.img.width, enc.img.height);
  assert(r && r.decoded);
  const expected = new TextEncoder().encode(msg);
  const d = decodeEngine.diffPayloads(expected, r.payload);
  assert(d.identical, "clean roundtrip should be identical");
});

