test("encodeBatch encodes a sequence with shared opts", () => {
  const items = [
    { payload: "Sequence item 1", filename: "seq1.txt" },
    { payload: "Sequence item 2", filename: "seq2.txt" },
    { payload: "Sequence item 3", filename: "seq3.txt" },
  ];
  const results = renderer.encodeBatch(items, { configName: "128x128-4c" });
  assert.strictEqual(results.length, 3);
  assert(results.every(r => r.ok));
  // Decode each
  for (let i = 0; i < results.length; i++) {
    const r = decodeEngine.decodeFrame(results[i].result.img.data, results[i].result.img.width, results[i].result.img.height);
    assert(r && r.decoded, `seq item ${i}`);
    assert.strictEqual(new TextDecoder().decode(r.payload), items[i].payload);
  }
});

test("sequence encode + stats aggregator", () => {
  const agg = decodeEngine.createDecodeStatsAggregator();
  const items = [
    { payload: "Agg A", filename: "a.txt" },
    { payload: "Agg B", filename: "b.txt" },
  ];
  const encoded = renderer.encodeBatch(items);
  for (const enc of encoded) {
    const img = enc.result.img;
    const noisy = renderer.addGaussianNoise(img, 8);
    const r = decodeEngine.decodeFrame(noisy.data, noisy.width, noisy.height);
    agg.record(r);
  }
  const s = agg.getStats();
  assert.strictEqual(s.totalFrames, 2);
  assert.strictEqual(s.successes, 2);
  console.log(`   seq+agg: rate=${s.successRate}%, avgCorr=${s.avgCorrections}`);
});

