console.log("\n--- STAGE 117: Instrumented decoder ---");

test("instrumented decoder fires all hooks on success", () => {
  let started = false, completed = false, succeeded = false;
  const decode = decodeEngine.createInstrumentedDecoder({
    onStart: () => { started = true; },
    onSuccess: () => { succeeded = true; },
    onComplete: () => { completed = true; },
  });
  const enc = renderer.encodeAndRender("Hook test", "hook.txt");
  const { result, context } = decode(enc.img.data, enc.img.width, enc.img.height);
  assert(started, "onStart fired");
  assert(succeeded, "onSuccess fired");
  assert(completed, "onComplete fired");
  assert(result && result.decoded);
  assert(context.success === true);
  assert(context.durationMs >= 0);
});

test("instrumented decoder fires onFailure on bad input", () => {
  let failFired = false, failStage = null;
  const decode = decodeEngine.createInstrumentedDecoder({
    onFailure: (r, ctx) => { failFired = true; failStage = ctx.failStage; },
  });
  const garbage = new Uint8Array(50 * 50 * 4);
  const { result, context } = decode(garbage, 50, 50);
  assert(failFired, "onFailure fired");
  assert(!context.success);
});

test("instrumented decoder context has timing", () => {
  const decode = decodeEngine.createInstrumentedDecoder({});
  const enc = renderer.encodeAndRender("Timing test", "time.txt");
  const { context } = decode(enc.img.data, enc.img.width, enc.img.height);
  assert(typeof context.startTime === "number");
  assert(typeof context.durationMs === "number");
});

