console.log("\n--- STAGE 120: Decode result cache ---");

test("cache — first decode is uncached", () => {
  const cache = decodeEngine.createDecodeCache(4);
  const enc = renderer.encodeAndRender("Cache test", "cache.txt");
  const { result, cached } = cache.decode(enc.img.data, enc.img.width, enc.img.height);
  assert(result && result.decoded);
  assert.strictEqual(cached, false);
});

test("cache — second decode is cached", () => {
  const cache = decodeEngine.createDecodeCache(4);
  const enc = renderer.encodeAndRender("Cache hit", "ch.txt");
  cache.decode(enc.img.data, enc.img.width, enc.img.height);
  const { result, cached, hits } = cache.decode(enc.img.data, enc.img.width, enc.img.height);
  assert(result && result.decoded);
  assert.strictEqual(cached, true);
  assert(hits >= 2);
});

test("cache — different images are separate entries", () => {
  const cache = decodeEngine.createDecodeCache(4);
  const enc1 = renderer.encodeAndRender("Cache A", "ca.txt");
  const enc2 = renderer.encodeAndRender("Cache B", "cb.txt");
  cache.decode(enc1.img.data, enc1.img.width, enc1.img.height);
  cache.decode(enc2.img.data, enc2.img.width, enc2.img.height);
  const stats = cache.getStats();
  assert.strictEqual(stats.size, 2);
});

test("cache — evicts oldest when full", () => {
  const cache = decodeEngine.createDecodeCache(2);
  const imgs = [];
  for (let i = 0; i < 3; i++) {
    const enc = renderer.encodeAndRender(`Evict ${i}`, `ev${i}.txt`);
    imgs.push(enc.img);
    cache.decode(enc.img.data, enc.img.width, enc.img.height);
  }
  const stats = cache.getStats();
  assert(stats.size <= 2, `cache size=${stats.size}`);
});

test("cache — clear empties cache", () => {
  const cache = decodeEngine.createDecodeCache(4);
  const enc = renderer.encodeAndRender("Clear test", "cl.txt");
  cache.decode(enc.img.data, enc.img.width, enc.img.height);
  cache.clear();
  assert.strictEqual(cache.getStats().size, 0);
});

test("cache — stats report hits", () => {
  const cache = decodeEngine.createDecodeCache(4);
  const enc = renderer.encodeAndRender("Stats test", "st.txt");
  cache.decode(enc.img.data, enc.img.width, enc.img.height);
  cache.decode(enc.img.data, enc.img.width, enc.img.height);
  cache.decode(enc.img.data, enc.img.width, enc.img.height);
  const stats = cache.getStats();
  assert.strictEqual(stats.entries[0].hits, 3);
});

