// =========================================================================
// STAGE 125: End-to-end regression suite
// =========================================================================
console.log("\n--- STAGE 125: End-to-end regression suite ---");

test("golden path: validate→recommend→encode→degrade→decode→calibrate→fingerprint→serialize", () => {
  const msg = "Aurexis V2 golden path regression test — full pipeline validation";

  // 1. Validate
  const v = decodeEngine.validatePayload(msg, { filename: "golden.txt" });
  assert(v.valid);

  // 2. Recommend
  const rec = decodeEngine.recommendConfig(v.size);
  assert(rec.recommended);

  // 3. Encode
  const enc = renderer.encodeAndRender(msg, "golden.txt", { configName: rec.recommended.configName });
  assert(enc.img);

  // 4. Degrade
  let img = renderer.applyGammaShift(enc.img, 1.15);
  img = renderer.addGaussianNoise(img, 6);

  // 5. Decode
  const r = decodeEngine.decodeFrame(img.data, img.width, img.height);
  assert(r && r.decoded);
  assert.strictEqual(new TextDecoder().decode(r.payload), msg);

  // 6. Calibrate
  const cal = decodeEngine.calibrateConfidence(r);
  assert(cal.calibrated >= 70);

  // 7. Fingerprint
  const fp = decodeEngine.fingerprintPayload(r.payload);
  const fpOrig = decodeEngine.fingerprintPayload(msg);
  assert.strictEqual(fp.fingerprint, fpOrig.fingerprint);

  // 8. Serialize + restore
  const ser = decodeEngine.serializeDecodeResult(r);
  const json = JSON.stringify(ser);
  const restored = decodeEngine.deserializeDecodeResult(JSON.parse(json));
  assert.strictEqual(new TextDecoder().decode(restored.payload), msg);

  // 9. Diagnostics
  const diag = decodeEngine.summarizeDiagnostics(r);
  assert(diag.decoded);

  // 10. Diff
  const d = decodeEngine.diffPayloads(msg, new TextDecoder().decode(r.payload));
  assert(d.identical);

  console.log(`   golden: config=${rec.recommended.configName}, cal=${cal.grade}, fp=${fp.fingerprint}, json=${json.length}B`);
});

test("golden path: batch→stream→aggregate→compare", () => {
  const msgs = ["Batch golden A", "Batch golden B", "Batch golden C"];
  const items = msgs.map((m, i) => ({ payload: m, filename: `bg${i}.txt` }));

  // 1. Batch encode
  const encoded = renderer.encodeBatch(items);
  assert(encoded.every(e => e.ok));

  // 2. Stream decode
  const session = decodeEngine.createDecodeSession({ earlyStopConfidence: 101 });
  const agg = decodeEngine.createDecodeStatsAggregator();
  for (const enc of encoded) {
    session.addFrame(enc.result.img.data, enc.result.img.width, enc.result.img.height);
  }
  const summary = session.finalize();
  assert(summary.stats.successCount === 3);

  // 3. Aggregate
  for (const r of summary.results) agg.record(r);
  const stats = agg.getStats();
  assert.strictEqual(stats.successRate, 100);

  // 4. Compare first vs last
  const cmp = decodeEngine.compareDecodeResults(summary.results[0], summary.results[2]);
  assert(cmp.winner === "tie" || cmp.winner === "a" || cmp.winner === "b");

  console.log(`   batch golden: ${stats.successRate}% success, ${stats.totalFrames} frames`);
});

test("golden path: chunk→encode→decode→reassemble", () => {
  const cap = renderer.getCapacity("128x128-4c");
  const bigPayload = new Uint8Array(cap.usablePayloadBytes * 2 + 50);
  for (let i = 0; i < bigPayload.length; i++) bigPayload[i] = (i * 13 + 7) & 0xFF;

  // 1. Chunk
  const chunked = renderer.chunkPayload(bigPayload, { configName: "128x128-4c" });
  assert(chunked.chunked);

  // 2. Encode each chunk
  const encChunks = [];
  for (const c of chunked.chunks) {
    const enc = renderer.encodeAndRender(c.data, c.filename, { configName: "128x128-4c" });
    encChunks.push(enc);
  }

  // 3. Decode each
  const decodedPayloads = [];
  for (const enc of encChunks) {
    const r = decodeEngine.decodeFrame(enc.img.data, enc.img.width, enc.img.height);
    assert(r && r.decoded);
    decodedPayloads.push(r.payload);
  }

  // 4. Reassemble
  const reassembled = renderer.reassembleChunks(decodedPayloads);
  assert.strictEqual(reassembled.totalLength, bigPayload.length);
  for (let i = 0; i < bigPayload.length; i++) {
    assert.strictEqual(reassembled.payload[i], bigPayload[i]);
  }

  console.log(`   chunk golden: ${bigPayload.length}B → ${chunked.totalChunks} chunks → reassembled OK`);
});

test("golden path: error budget prediction vs actual", () => {
  const msg = "Error budget validation";
  const degradation = { noiseSigma: 10 };

  // 1. Predict
  const eb = decodeEngine.estimateErrorBudget("128x128-4c", degradation);

  // 2. Actual encode + degrade + decode
  const enc = renderer.encodeAndRender(msg, "eb.txt", { configName: "128x128-4c" });
  const noisy = renderer.addGaussianNoise(enc.img, degradation.noiseSigma);
  const r = decodeEngine.decodeFrame(noisy.data, noisy.width, noisy.height);

  if (r && r.decoded) {
    const actual = r.rsStats.totalCorrected;
    // Prediction should be in the right order of magnitude
    console.log(`   budget: predicted=${eb.estimatedCorrections}, actual=${actual}, margin=${eb.safetyMargin}%`);
    // Both should agree the image is decodable
    if (eb.willDecode) {
      // Good — prediction matched reality
    }
  } else {
    console.log(`   budget: predicted willDecode=${eb.willDecode}, actual=failed`);
  }
  assert(typeof eb.estimatedCorrections === "number");
});

