console.log("\n--- STAGE 129: Decode with telemetry ---");

test("telemetry — clean decode has all fields", () => {
  const enc = renderer.encodeAndRender("Telemetry test", "tel.txt");
  const { result, telemetry } = decodeEngine.decodeWithTelemetry(enc.img.data, enc.img.width, enc.img.height);
  assert(result && result.decoded);
  assert(telemetry.totalMs >= 0);
  assert(telemetry.decoded);
  assert(telemetry.inputPixels === enc.img.width * enc.img.height);
  assert(telemetry.stages.length >= 3);
  const names = telemetry.stages.map(s => s.name);
  assert(names.includes("noiseEstimate"));
  assert(names.includes("blurEstimate"));
  assert(names.includes("decode"));
  console.log(`   telemetry: ${telemetry.stages.map(s => `${s.name}=${s.ms}ms`).join(", ")}, total=${telemetry.totalMs}ms`);
});

test("telemetry — noise estimate present", () => {
  const enc = renderer.encodeAndRender("Tel noise", "tn.txt");
  const noisy = renderer.addGaussianNoise(enc.img, 10);
  const { telemetry } = decodeEngine.decodeWithTelemetry(noisy.data, noisy.width, noisy.height);
  const noiseStage = telemetry.stages.find(s => s.name === "noiseEstimate");
  assert(noiseStage);
  assert(typeof noiseStage.sigma === "number");
});

test("telemetry — failed decode still has telemetry", () => {
  const garbage = new Uint8Array(50 * 50 * 4);
  const { result, telemetry } = decodeEngine.decodeWithTelemetry(garbage, 50, 50);
  assert(!telemetry.decoded);
  assert(telemetry.totalMs >= 0);
  assert(telemetry.stages.length >= 1);
});

// =========================================================================
// STAGE 130: Encode determinism
// =========================================================================
console.log("\n--- STAGE 130: Encode determinism ---");

test("same input produces identical output", () => {
  const msg = "Determinism test payload";
  const enc1 = renderer.encodeAndRender(msg, "det.txt", { configName: "128x128-4c" });
  const enc2 = renderer.encodeAndRender(msg, "det.txt", { configName: "128x128-4c" });
  assert.strictEqual(enc1.img.width, enc2.img.width);
  assert.strictEqual(enc1.img.height, enc2.img.height);
  // Compare pixel data
  let diffs = 0;
  for (let i = 0; i < enc1.img.data.length; i++) {
    if (enc1.img.data[i] !== enc2.img.data[i]) diffs++;
  }
  assert.strictEqual(diffs, 0);
  console.log(`   determinism: ${enc1.img.data.length} bytes, 0 diffs`);
});

test("different payloads produce different output", () => {
  const enc1 = renderer.encodeAndRender("Payload A", "d1.txt", { configName: "128x128-4c" });
  const enc2 = renderer.encodeAndRender("Payload B", "d2.txt", { configName: "128x128-4c" });
  let diffs = 0;
  const len = Math.min(enc1.img.data.length, enc2.img.data.length);
  for (let i = 0; i < len; i++) {
    if (enc1.img.data[i] !== enc2.img.data[i]) diffs++;
  }
  assert(diffs > 0, "different payloads should produce different images");
});

test("determinism across configs", () => {
  const msg = "Cross-config determinism";
  const enc128a = renderer.encodeAndRender(msg, "dc.txt", { configName: "128x128-4c" });
  const enc128b = renderer.encodeAndRender(msg, "dc.txt", { configName: "128x128-4c" });
  const enc192 = renderer.encodeAndRender(msg, "dc.txt", { configName: "192x192-4c" });
  // Same config = same output
  assert.strictEqual(enc128a.img.width, enc128b.img.width);
  // Different config = different dimensions
  assert(enc128a.img.width !== enc192.img.width);
});

