console.log("\n--- STAGE 131: Extreme EC stress (nsym=64 max) ---");

test("nsym=64 clean roundtrip", () => {
  const msg = "High EC test nsym=64";
  const enc = renderer.encodeAndRender(msg, "ec64.txt", { nsym: 64 });
  const r = decodeEngine.decodeFrame(enc.img.data, enc.img.width, enc.img.height);
  assert(r && r.decoded, "nsym=64 clean");
  assert.strictEqual(new TextDecoder().decode(r.payload), msg);
  console.log(`   nsym=64 clean: corr=${r.rsStats.totalCorrected}, capacity=${r.rsStats.correctionCapacity}`);
});

test("nsym=64 + heavy noise σ=20", () => {
  const msg = "EC64 noisy";
  const enc = renderer.encodeAndRender(msg, "ec64n.txt", { nsym: 64 });
  const noisy = renderer.addGaussianNoise(enc.img, 20);
  const r = decodeEngine.decodeFrame(noisy.data, noisy.width, noisy.height);
  if (r && r.decoded) {
    assert.strictEqual(new TextDecoder().decode(r.payload), msg);
    console.log(`   nsym=64 noise σ=20: corr=${r.rsStats.totalCorrected}, headroom=${(r.rsStats.correctionHeadroom*100).toFixed(1)}%`);
  } else {
    console.log(`   nsym=64 noise σ=20: failed (stretch)`);
  }
});

test("nsym=64 + JPEG Q=50", () => {
  const msg = "EC64 JPEG test";
  const enc = renderer.encodeAndRender(msg, "ec64j.txt", { nsym: 64 });
  const jpg = renderer.simulateJpegCompression(enc.img, 50);
  const r = decodeEngine.decodeFrame(jpg.data, jpg.width, jpg.height);
  if (r && r.decoded) {
    assert.strictEqual(new TextDecoder().decode(r.payload), msg);
    console.log(`   nsym=64 JPEG Q=50: corr=${r.rsStats.totalCorrected}`);
  } else {
    console.log(`   nsym=64 JPEG Q=50: failed (stretch)`);
  }
});

test("nsym=64 has higher correction capacity than nsym=32", () => {
  const eb32 = decodeEngine.estimateErrorBudget("128x128-4c", { noiseSigma: 0 });
  const eb64 = decodeEngine.estimateErrorBudget("128x128-4c", { noiseSigma: 0, nsym: 64 });
  const cap32 = renderer.getCapacity("128x128-4c", { nsym: 32 });
  const cap64 = renderer.getCapacity("128x128-4c", { nsym: 64 });
  assert(cap64.usablePayloadBytes < cap32.usablePayloadBytes, "nsym=64 less payload");
  console.log(`   nsym=32: ${cap32.usablePayloadBytes}B usable, nsym=64: ${cap64.usablePayloadBytes}B usable`);
});

test("nsym=64 + warp + noise combo", () => {
  const msg = "EC64 combo";
  const enc = renderer.encodeAndRender(msg, "ec64c.txt", { nsym: 64 });
  const W = enc.img.width, H = enc.img.height;
  const src = [{x:0,y:0},{x:W,y:0},{x:0,y:H},{x:W,y:H}];
  const dst = [{x:8,y:6},{x:W-10,y:4},{x:5,y:H-8},{x:W-7,y:H-5}];
  let img = renderer.perspectiveWarp(enc.img, W, H, src, dst);
  img = renderer.addGaussianNoise(img, 12);
  const r = decodeEngine.decodeFrame(img.data, img.width, img.height);
  if (r && r.decoded) {
    assert.strictEqual(new TextDecoder().decode(r.payload), msg);
    console.log(`   nsym=64 combo: corr=${r.rsStats.totalCorrected}, headroom=${(r.rsStats.correctionHeadroom*100).toFixed(1)}%`);
  } else {
    console.log(`   nsym=64 combo: failed (stretch)`);
  }
});

