test("encodeWithMetadata — roundtrip", () => {
  const payload = new TextEncoder().encode("metadata test");
  const { combined, metadata } = decodeEngine.encodeWithMetadata(payload, "meta.txt", {
    config: "128x128-4c",
    metadata: { author: "test" },
  });
  assert(combined.length > payload.length, "combined larger than payload");
  assert.strictEqual(metadata.author, "test");
  assert(metadata.version, "has version");
  const extracted = decodeEngine.extractMetadata(combined);
  assert(extracted.hasMetadata, "detected metadata");
  assert.strictEqual(extracted.metadata.author, "test");
  assert.strictEqual(new TextDecoder().decode(extracted.payload), "metadata test");
});

test("extractMetadata — no metadata present", () => {
  const raw = new TextEncoder().encode("no metadata here");
  const extracted = decodeEngine.extractMetadata(raw);
  assert.strictEqual(extracted.hasMetadata, false);
  assert.strictEqual(new TextDecoder().decode(extracted.payload), "no metadata here");
});

test("extractMetadata — truncated", () => {
  const tiny = new Uint8Array(3);
  const extracted = decodeEngine.extractMetadata(tiny);
  assert.strictEqual(extracted.hasMetadata, false);
});

test("encodeWithMetadata — magic constant matches", () => {
  assert.strictEqual(decodeEngine.METADATA_MAGIC, 0x41555258);
});

test("extractMetadata — corrupt metadata JSON", () => {
  // Build valid header but corrupt the JSON
  const combined = new Uint8Array(20);
  combined[0] = 0x41; combined[1] = 0x55; combined[2] = 0x52; combined[3] = 0x58;
  combined[4] = 0; combined[5] = 5; // metaLen = 5
  combined[6] = 0xFF; combined[7] = 0xFF; combined[8] = 0xFF; combined[9] = 0xFF; combined[10] = 0xFF;
  const extracted = decodeEngine.extractMetadata(combined);
  assert.strictEqual(extracted.hasMetadata, false);
  assert(extracted.error, "should have error for corrupt JSON");
});

