console.log("\n--- STAGE 144: Decode rate limiter ---");

test("rateLimiter — allows within limit", () => {
  const rl = decodeEngine.createRateLimiter({ maxPerSecond: 5 });
  const r1 = rl.tryAcquire();
  assert(r1.allowed, "first should be allowed");
  assert.strictEqual(r1.waitMs, 0);
});

test("rateLimiter — blocks when exhausted", () => {
  const rl = decodeEngine.createRateLimiter({ maxPerSecond: 2, windowMs: 1000 });
  rl.tryAcquire();
  rl.tryAcquire();
  const r3 = rl.tryAcquire();
  assert(!r3.allowed, "third should be blocked");
  assert(r3.waitMs > 0, "has wait time");
});

test("rateLimiter — reset clears state", () => {
  const rl = decodeEngine.createRateLimiter({ maxPerSecond: 1 });
  rl.tryAcquire();
  rl.reset();
  const r = rl.tryAcquire();
  assert(r.allowed, "allowed after reset");
});

test("rateLimiter — pending count", () => {
  const rl = decodeEngine.createRateLimiter({ maxPerSecond: 10 });
  rl.tryAcquire();
  rl.tryAcquire();
  assert.strictEqual(rl.pending, 2);
});

