// =========================================================================
// STAGE 147: Decode pipeline hooks
// =========================================================================
console.log("\n--- STAGE 147: Decode pipeline hooks ---");

test("pipeline hooks — preDecode fires", () => {
  const hooks = decodeEngine.createPipelineHooks();
  let preCalled = false;
  hooks.on("preDecode", () => { preCalled = true; });
  const enc = renderer.encodeAndRender("hooks", "hk.txt");
  hooks.runDecode(enc.img.data, enc.img.width, enc.img.height);
  assert(preCalled, "preDecode should fire");
});

test("pipeline hooks — postDecode has result", () => {
  const hooks = decodeEngine.createPipelineHooks();
  let postCtx = null;
  hooks.on("postDecode", (ctx) => { postCtx = ctx; });
  const enc = renderer.encodeAndRender("hooks2", "hk2.txt");
  hooks.runDecode(enc.img.data, enc.img.width, enc.img.height);
  assert(postCtx, "postDecode should fire");
  assert(postCtx.result, "has result");
  assert(postCtx.elapsed >= 0, "has elapsed");
});

test("pipeline hooks — off removes hook", () => {
  const hooks = decodeEngine.createPipelineHooks();
  let count = 0;
  const fn = () => { count++; };
  hooks.on("preDecode", fn);
  hooks.off("preDecode", fn);
  assert.strictEqual(hooks.hookCounts.preDecode, 0);
});

test("pipeline hooks — hookCounts", () => {
  const hooks = decodeEngine.createPipelineHooks();
  hooks.on("preDecode", () => {});
  hooks.on("postDecode", () => {});
  hooks.on("onError", () => {});
  const c = hooks.hookCounts;
  assert.strictEqual(c.preDecode, 1);
  assert.strictEqual(c.postDecode, 1);
  assert.strictEqual(c.onError, 1);
});

