// STAGE 150: Decode result diff stream
// =========================================================================
console.log("\n--- STAGE 150: Decode result diff stream ---");

test("diff stream — first push is always changed", () => {
  const ds = decodeEngine.createResultDiffStream();
  const enc = renderer.encodeAndRender("diff1", "df1.txt");
  const r = decodeEngine.decodeFrame(enc.img.data, enc.img.width, enc.img.height);
  const diff = ds.push(r);
  assert(diff.changed, "first push is always changed");
  assert(diff.current.decoded, "decoded");
  assert(diff.current.fingerprint, "has fingerprint");
});

test("diff stream — same result not changed", () => {
  const ds = decodeEngine.createResultDiffStream();
  const enc = renderer.encodeAndRender("diff2", "df2.txt");
  const r = decodeEngine.decodeFrame(enc.img.data, enc.img.width, enc.img.height);
  ds.push(r);
  const diff2 = ds.push(r);
  assert(!diff2.changed, "same result should not be changed");
  assert(!diff2.decodedChanged, "decoded status same");
});

test("diff stream — different payload is changed", () => {
  const ds = decodeEngine.createResultDiffStream();
  const enc1 = renderer.encodeAndRender("AAA", "df3a.txt");
  const enc2 = renderer.encodeAndRender("BBB", "df3b.txt");
  const r1 = decodeEngine.decodeFrame(enc1.img.data, enc1.img.width, enc1.img.height);
  const r2 = decodeEngine.decodeFrame(enc2.img.data, enc2.img.width, enc2.img.height);
  ds.push(r1);
  const diff = ds.push(r2);
  assert(diff.changed, "different payload should be changed");
});

test("diff stream — reset clears history", () => {
  const ds = decodeEngine.createResultDiffStream();
  ds.push({ decoded: true, payload: new Uint8Array([1]), rsStats: { totalCorrected: 0 } });
  assert(ds.hasPrevious, "has previous");
  ds.reset();
  assert(!ds.hasPrevious, "cleared after reset");
});

