console.log("\n--- STAGE 153: Decode confidence trend ---");

test("trend — empty is stable", () => {
  const t = decodeEngine.createConfidenceTrend();
  assert.strictEqual(t.trend.direction, "stable");
  assert.strictEqual(t.count, 0);
});

test("trend — improving sequence", () => {
  const t = decodeEngine.createConfidenceTrend({ windowSize: 5 });
  for (let i = 0; i < 5; i++) t.add(50 + i * 10);
  assert.strictEqual(t.trend.direction, "improving");
  assert(t.trend.slope > 0, "positive slope");
});

test("trend — degrading sequence", () => {
  const t = decodeEngine.createConfidenceTrend({ windowSize: 5 });
  for (let i = 0; i < 5; i++) t.add(100 - i * 10);
  assert.strictEqual(t.trend.direction, "degrading");
  assert(t.trend.slope < 0, "negative slope");
});

test("trend — window eviction", () => {
  const t = decodeEngine.createConfidenceTrend({ windowSize: 3 });
  t.add(10); t.add(20); t.add(30); t.add(40);
  assert.strictEqual(t.count, 3);
});

test("trend — reset", () => {
  const t = decodeEngine.createConfidenceTrend();
  t.add(50); t.add(60);
  t.reset();
  assert.strictEqual(t.count, 0);
});

