// =========================================================================
// STAGE 164: Payload entropy analyzer
// =========================================================================
console.log("\n--- STAGE 164: Payload entropy analyzer ---");

test("entropy — text is compressible", () => {
  const r = decodeEngine.analyzeEntropy("Hello World! ".repeat(100));
  assert(r.compressible, "repetitive text should be compressible");
  assert(r.entropy < 4, "low entropy for repetitive text");
  assert(r.ratio < 0.5, "low ratio");
});

test("entropy — random bytes are not compressible", () => {
  const data = new Uint8Array(1000);
  for (let i = 0; i < data.length; i++) data[i] = Math.floor(Math.random() * 256);
  const r = decodeEngine.analyzeEntropy(data);
  assert(r.entropy > 6, "high entropy for random data");
});

test("entropy — empty payload", () => {
  const r = decodeEngine.analyzeEntropy(new Uint8Array(0));
  assert.strictEqual(r.entropy, 0);
  assert(r.compressible, "empty is compressible");
});

test("entropy — single byte repeated", () => {
  const data = new Uint8Array(100).fill(42);
  const r = decodeEngine.analyzeEntropy(data);
  assert.strictEqual(r.entropy, 0);
  assert.strictEqual(r.uniqueBytes, 1);
});

