// STAGE 169: Payload splitter with overlap
// =========================================================================
console.log("\n--- STAGE 169: Payload splitter with overlap ---");

test("split — no overlap", () => {
  const payload = new TextEncoder().encode("ABCDEFGHIJ");
  const r = decodeEngine.splitPayloadWithOverlap(payload, 4, 0);
  assert.strictEqual(r.count, 3); // 4+4+2
  assert.strictEqual(r.chunks[0].length, 4);
});

test("split — with overlap", () => {
  const payload = new Uint8Array(10);
  for (let i = 0; i < 10; i++) payload[i] = i;
  const r = decodeEngine.splitPayloadWithOverlap(payload, 4, 1);
  assert(r.count >= 3, `expected >= 3 chunks, got ${r.count}`);
  assert.strictEqual(r.step, 3);
  assert(r.chunks[1].hasOverlap, "second chunk has overlap");
});

test("split — empty payload", () => {
  const r = decodeEngine.splitPayloadWithOverlap(new Uint8Array(0), 4, 0);
  assert.strictEqual(r.count, 0);
});

test("split — overlap covers full reconstruction", () => {
  const payload = new TextEncoder().encode("Hello World!");
  const r = decodeEngine.splitPayloadWithOverlap(payload, 5, 2);
  // Verify all bytes are represented
  const covered = new Set();
  for (const ch of r.chunks) {
    for (let i = ch.offset; i < ch.offset + ch.length; i++) covered.add(i);
  }
  assert.strictEqual(covered.size, payload.length);
});

