// =========================================================================
// STAGE 179: Cross-config roundtrip sweep
// =========================================================================
console.log("\n--- STAGE 179: Cross-config roundtrip sweep ---");

test("cross-config — 4 smallest configs roundtrip", () => {
  const configs = ["128x128-4c", "192x192-4c", "256x256-4c", "128x128-8c"];
  const msg = "sweep test";
  let passed = 0;
  for (const cfg of configs) {
    const enc = renderer.encodeAndRender(msg, "sweep.txt", { config: cfg });
    const r = decodeEngine.decodeFrame(enc.img.data, enc.img.width, enc.img.height);
    if (r && r.decoded) {
      const decoded = new TextDecoder().decode(r.payload);
      if (decoded === msg) passed++;
    }
  }
  assert.strictEqual(passed, configs.length);
  console.log(`   ${passed}/${configs.length} configs roundtripped`);
});

test("cross-config — dry-run all 17 configs", () => {
  const payload = new TextEncoder().encode("sweep dry-run");
  const matrix = decodeEngine.getConfigCapacityMatrix();
  let fitsCount = 0;
  for (const entry of matrix) {
    const dr = decodeEngine.encodeDryRun(payload, entry.configName);
    if (dr.ok) fitsCount++;
  }
  assert.strictEqual(fitsCount, matrix.length, "small payload should fit all configs");
  console.log(`   ${fitsCount}/${matrix.length} configs can hold ${payload.length}B`);
});

test("cross-config — validate all 17 configs", () => {
  const payload = new TextEncoder().encode("validate all");
  const matrix = decodeEngine.getConfigCapacityMatrix();
  let validCount = 0;
  for (const entry of matrix) {
    const v = decodeEngine.validateEncode(payload, entry.configName);
    if (v.valid) validCount++;
  }
  assert.strictEqual(validCount, matrix.length);
});

