// STAGE 180: Payload compression ratio estimator
// =========================================================================
console.log("\n--- STAGE 180: Payload compression ratio estimator ---");

test("compressionRatio — highly compressible payload", () => {
  const payload = Buffer.alloc(1000, 0x41); // all 'A'
  const r = decodeEngine.estimateCompressionRatio(payload);
  assert(r.ratio > 1.5, `expected high ratio, got ${r.ratio}`);
  assert(r.savedBytes > 0, "should save bytes");
  assert(r.recommendation !== 'none', `expected recommendation, got ${r.recommendation}`);
  assert.strictEqual(r.originalSize, 1000);
  assert(r.compressedSize < 1000, "compressed should be smaller");
});

test("compressionRatio — random/incompressible payload", () => {
  const payload = Buffer.alloc(500);
  for (let i = 0; i < 500; i++) payload[i] = (i * 7 + 13) & 0xFF;
  const r = decodeEngine.estimateCompressionRatio(payload);
  assert(r.ratio >= 0.5, `ratio should be reasonable, got ${r.ratio}`);
  assert.strictEqual(r.originalSize, 500);
});

test("compressionRatio — empty payload", () => {
  const r = decodeEngine.estimateCompressionRatio(Buffer.alloc(0));
  assert.strictEqual(r.ratio, 1.0);
  assert.strictEqual(r.savedBytes, 0);
  assert.strictEqual(r.recommendation, 'none');
});

test("compressionRatio — string input", () => {
  const r = decodeEngine.estimateCompressionRatio("hello hello hello hello hello hello hello hello");
  assert(r.ratio >= 1.0, "repeated text should compress");
  assert.strictEqual(typeof r.recommendation, 'string');
});

