console.log("\n--- STAGE 181: Decode result comparator ---");

test("diffDecodeResults — identical results", () => {
  const a = { success: true, config: "256x256-4c", confidence: 0.95, corrections: 2, payload: "hello" };
  const b = { success: true, config: "256x256-4c", confidence: 0.95, corrections: 2, payload: "hello" };
  const d = decodeEngine.diffDecodeResults(a, b);
  assert(d.identical, "should be identical");
  assert.strictEqual(d.diffs.length, 0);
});

test("diffDecodeResults — different config and confidence", () => {
  const a = { success: true, config: "256x256-4c", confidence: 0.95 };
  const b = { success: true, config: "384x384-4c", confidence: 0.80 };
  const d = decodeEngine.diffDecodeResults(a, b);
  assert(!d.identical, "should not be identical");
  assert(d.diffs.length >= 2, "at least config and confidence differ");
  const configDiff = d.diffs.find(x => x.field === 'config');
  assert(configDiff, "should have config diff");
  assert.strictEqual(configDiff.from, "256x256-4c");
});

test("diffDecodeResults — null input", () => {
  const d = decodeEngine.diffDecodeResults(null, { success: true });
  assert(!d.identical);
  assert(d.diffs.length > 0);
});

test("diffDecodeResults — payload difference", () => {
  const a = { success: true, payload: "abc" };
  const b = { success: true, payload: "xyz" };
  const d = decodeEngine.diffDecodeResults(a, b);
  assert(!d.identical);
  const payDiff = d.diffs.find(x => x.field === 'payload');
  assert(payDiff, "should detect payload difference");
});

