// =========================================================================
// STAGE 183: Encode/decode timing budget
// =========================================================================
console.log("\n--- STAGE 183: Encode/decode timing budget ---");

test("timingBudget — basic stage tracking", () => {
  const tb = decodeEngine.createTimingBudget({ maxMs: 1000 });
  tb.start("finder");
  tb.end("finder");
  tb.start("decode");
  tb.end("decode");
  const report = tb.report();
  assert.strictEqual(report.maxMs, 1000);
  assert(report.stages.length === 2, "should have 2 stages");
  assert(typeof report.totalElapsed === 'number');
  assert(!report.overBudget, "should not be over budget");
});

test("timingBudget — remaining and overBudget", () => {
  const tb = decodeEngine.createTimingBudget({ maxMs: 0 }); // zero budget
  tb.start("a");
  // burn a tiny bit of time
  for (let i = 0; i < 100; i++) Math.random();
  tb.end("a");
  // With 0 budget, any elapsed > 0 is over budget
  assert(tb.remaining() === 0, "remaining should be 0");
});

test("timingBudget — report pct sums roughly to 100", () => {
  const tb = decodeEngine.createTimingBudget({ maxMs: 5000 });
  tb.start("a"); tb.end("a");
  tb.start("b"); tb.end("b");
  const report = tb.report();
  const totalPct = report.stages.reduce((s, st) => s + st.pct, 0);
  // may not be exactly 100 due to rounding, but should be close or zero
  assert(totalPct >= 0 && totalPct <= 200, `pct total reasonable: ${totalPct}`);
});

