console.log("\n--- STAGE 184: Payload deduplication detector ---");

test("detectDuplicatePayloads — no duplicates", () => {
  const payloads = [Buffer.from("aaa"), Buffer.from("bbb"), Buffer.from("ccc")];
  const r = decodeEngine.detectDuplicatePayloads(payloads);
  assert(!r.hasDuplicates, "should have no duplicates");
  assert.strictEqual(r.uniquePayloads, 3);
  assert.strictEqual(r.duplicateCount, 0);
  assert.strictEqual(r.groups.length, 0);
});

test("detectDuplicatePayloads — with duplicates", () => {
  const payloads = [Buffer.from("aaa"), Buffer.from("bbb"), Buffer.from("aaa"), Buffer.from("ccc"), Buffer.from("bbb")];
  const r = decodeEngine.detectDuplicatePayloads(payloads);
  assert(r.hasDuplicates, "should detect duplicates");
  assert.strictEqual(r.uniquePayloads, 3);
  assert.strictEqual(r.duplicateGroups, 2);
  assert.strictEqual(r.duplicateCount, 2);
  // check that indices are correct for "aaa"
  const aaaGroup = r.groups.find(g => g.indices.includes(0) && g.indices.includes(2));
  assert(aaaGroup, "should find aaa group at indices 0 and 2");
});

test("detectDuplicatePayloads — string inputs", () => {
  const r = decodeEngine.detectDuplicatePayloads(["hello", "hello", "world"]);
  assert(r.hasDuplicates);
  assert.strictEqual(r.uniquePayloads, 2);
});

test("detectDuplicatePayloads — single payload", () => {
  const r = decodeEngine.detectDuplicatePayloads([Buffer.from("only")]);
  assert(!r.hasDuplicates);
  assert.strictEqual(r.totalPayloads, 1);
  assert.strictEqual(r.uniquePayloads, 1);
});

