console.log("\n--- STAGE 186: Decode attempt logger ---");

test("decodeLogger — log and retrieve entries", () => {
  const logger = decodeEngine.createDecodeLogger();
  logger.log("img1", { success: true, config: "256x256-4c", confidence: 0.95, corrections: 1 }, { elapsed: 50 });
  logger.log("img2", { success: false, confidence: 0.3 }, { elapsed: 200, error: "RS fail" });
  const entries = logger.getEntries();
  assert.strictEqual(entries.length, 2);
  assert(entries[0].success);
  assert(!entries[1].success);
  assert.strictEqual(entries[1].error, "RS fail");
});

test("decodeLogger — stats computation", () => {
  const logger = decodeEngine.createDecodeLogger();
  logger.log("a", { success: true, confidence: 0.9 }, { elapsed: 10 });
  logger.log("b", { success: true, confidence: 0.8 }, { elapsed: 20 });
  logger.log("c", { success: false, confidence: 0.2 }, { elapsed: 100 });
  const stats = logger.getStats();
  assert.strictEqual(stats.total, 3);
  assert.strictEqual(stats.successes, 2);
  assert.strictEqual(stats.failures, 1);
  assert(stats.successRate > 60 && stats.successRate < 70, `rate ~66.67, got ${stats.successRate}`);
  assert(stats.avgConfidence > 0.5);
});

test("decodeLogger — clear and toJSON", () => {
  const logger = decodeEngine.createDecodeLogger();
  logger.log("x", { success: true, confidence: 0.5 });
  assert.strictEqual(logger.getEntries().length, 1);
  const json = logger.toJSON();
  assert(json.entries.length === 1);
  assert(json.stats.total === 1);
  logger.clear();
  assert.strictEqual(logger.getEntries().length, 0);
});

test("decodeLogger — max entries cap", () => {
  const logger = decodeEngine.createDecodeLogger({ maxEntries: 3 });
  for (let i = 0; i < 5; i++) logger.log(`img${i}`, { success: true, confidence: 0.5 });
  assert.strictEqual(logger.getEntries().length, 3);
});

