// STAGE 188: Payload chunker with CRC
// =========================================================================
console.log("\n--- STAGE 188: Payload chunker with CRC ---");

test("chunkPayloadWithCRC — basic chunking", () => {
  const payload = Buffer.from("Hello World!! This is a test payload for chunking.");
  const chunks = decodeEngine.chunkPayloadWithCRC(payload, 10);
  assert(chunks.length >= 5, `expected >=5 chunks, got ${chunks.length}`);
  assert.strictEqual(chunks[0].index, 0);
  assert.strictEqual(chunks[0].offset, 0);
  assert.strictEqual(chunks[0].length, 10);
  assert(typeof chunks[0].crc === 'number', "crc should be a number");
});

test("chunkPayloadWithCRC — verify valid chunks pass", () => {
  const payload = Buffer.from("integrity check payload");
  const chunks = decodeEngine.chunkPayloadWithCRC(payload, 8);
  const v = decodeEngine.verifyChunkedPayload(chunks);
  assert(v.valid, "unmodified chunks should verify");
  assert.strictEqual(v.errors.length, 0);
  assert.strictEqual(v.totalLength, payload.length);
});

test("chunkPayloadWithCRC — tampered chunk detected", () => {
  const payload = Buffer.from("tamper detection test data here");
  const chunks = decodeEngine.chunkPayloadWithCRC(payload, 10);
  // tamper with first chunk
  chunks[0].data[0] = 0xFF;
  const v = decodeEngine.verifyChunkedPayload(chunks);
  assert(!v.valid, "tampered chunk should fail");
  assert.strictEqual(v.errors.length, 1);
  assert.strictEqual(v.errors[0].index, 0);
});

test("chunkPayloadWithCRC — single chunk for small payload", () => {
  const chunks = decodeEngine.chunkPayloadWithCRC(Buffer.from("hi"), 100);
  assert.strictEqual(chunks.length, 1);
  assert.strictEqual(chunks[0].length, 2);
});

