console.log("\n--- STAGE 189: Confidence calibrator histogram ---");

test("calibrateConfidenceHistogram — basic distribution", () => {
  const results = [
    { confidence: 0.95 }, { confidence: 0.90 }, { confidence: 0.85 },
    { confidence: 0.70 }, { confidence: 0.60 }, { confidence: 0.50 },
    { confidence: 0.30 }, { confidence: 0.20 }, { confidence: 0.10 },
    { confidence: 0.05 },
  ];
  const h = decodeEngine.calibrateConfidenceHistogram(results);
  assert.strictEqual(h.count, 10);
  assert.strictEqual(h.buckets.length, 10);
  assert(h.median > 0.4 && h.median < 0.7, `median ~0.55, got ${h.median}`);
  assert(h.mean > 0.4 && h.mean < 0.6, `mean ~0.515, got ${h.mean}`);
  assert(h.p10 >= 0, "p10 defined");
  assert(h.p90 > 0, "p90 defined");
});

test("calibrateConfidenceHistogram — empty returns defaults", () => {
  const h = decodeEngine.calibrateConfidenceHistogram([]);
  assert.strictEqual(h.median, 0);
  assert.strictEqual(h.mean, 0);
  assert.strictEqual(h.buckets.length, 0);
});

test("calibrateConfidenceHistogram — single result", () => {
  const h = decodeEngine.calibrateConfidenceHistogram([{ confidence: 0.75 }]);
  assert.strictEqual(h.count, 1);
  assert.strictEqual(h.median, 0.75);
  assert.strictEqual(h.mean, 0.75);
});

