test("encodeParamSnapshot — save and restore", () => {
  const snap = decodeEngine.createEncodeParamSnapshot();
  snap.save("preset1", { configName: "256x256-4c", nsym: 16, quality: "balanced" });
  const restored = snap.restore("preset1");
  assert(restored);
  assert.strictEqual(restored.configName, "256x256-4c");
  assert.strictEqual(restored.nsym, 16);
  assert.strictEqual(restored.quality, "balanced");
  assert(!restored._savedAt, "_savedAt should be stripped");
});

test("encodeParamSnapshot — list and has", () => {
  const snap = decodeEngine.createEncodeParamSnapshot();
  snap.save("a", { configName: "128x128-4c", nsym: 8 });
  snap.save("b", { configName: "384x384-8c", nsym: 32 });
  assert(snap.has("a"));
  assert(!snap.has("c"));
  const list = snap.list();
  assert.strictEqual(list.length, 2);
  assert(list[0].savedAt > 0);
});

test("encodeParamSnapshot — remove", () => {
  const snap = decodeEngine.createEncodeParamSnapshot();
  snap.save("x", { nsym: 8 });
  assert(snap.has("x"));
  snap.remove("x");
  assert(!snap.has("x"));
  assert.strictEqual(snap.restore("x"), null);
});

test("encodeParamSnapshot — toJSON", () => {
  const snap = decodeEngine.createEncodeParamSnapshot();
  snap.save("p", { configName: "256x256-4c" });
  const j = snap.toJSON();
  assert(j.p, "should have key 'p'");
  assert.strictEqual(j.p.configName, "256x256-4c");
});

