console.log("\n--- STAGE 195: Result cache with TTL ---");

test("resultCache — set and get", () => {
  const cache = decodeEngine.createResultCache({ ttlMs: 10000 });
  cache.set("img1", { success: true, config: "256x256-4c" });
  const r = cache.get("img1");
  assert(r, "should retrieve cached result");
  assert.strictEqual(r.success, true);
  assert.strictEqual(r.config, "256x256-4c");
  assert.strictEqual(cache.size(), 1);
});

test("resultCache — has and keys", () => {
  const cache = decodeEngine.createResultCache();
  cache.set("a", { success: true });
  cache.set("b", { success: false });
  assert(cache.has("a"));
  assert(!cache.has("c"));
  const keys = cache.keys();
  assert.strictEqual(keys.length, 2);
  assert(keys.includes("a"));
});

test("resultCache — clear", () => {
  const cache = decodeEngine.createResultCache();
  cache.set("x", { success: true });
  assert.strictEqual(cache.size(), 1);
  cache.clear();
  assert.strictEqual(cache.size(), 0);
});

test("resultCache — maxSize eviction", () => {
  const cache = decodeEngine.createResultCache({ maxSize: 3, ttlMs: 60000 });
  for (let i = 0; i < 5; i++) cache.set(`k${i}`, { i });
  assert(cache.size() <= 3, `size should be <= 3, got ${cache.size()}`);
});

