// STAGE 196: Payload padding/alignment
// =========================================================================
console.log("\n--- STAGE 196: Payload padding/alignment ---");

test("padPayload — aligns to boundary", () => {
  const r = decodeEngine.padPayload(Buffer.from("hello"), 8);
  assert(r.padded, "should be padded");
  assert.strictEqual(r.data.length % 8, 0);
  assert.strictEqual(r.originalLength, 5);
  assert.strictEqual(r.paddingBytes, 3);
  assert.strictEqual(r.data[0], 0x68); // 'h'
});

test("padPayload — no padding needed if aligned", () => {
  const r = decodeEngine.padPayload(Buffer.alloc(16), 8);
  assert(!r.padded, "should not need padding");
  assert.strictEqual(r.paddingBytes, 0);
});

test("padPayload — custom pad byte", () => {
  const r = decodeEngine.padPayload(Buffer.from("ab"), 4, 0xFF);
  assert.strictEqual(r.data.length, 4);
  assert.strictEqual(r.data[2], 0xFF);
  assert.strictEqual(r.data[3], 0xFF);
});

test("stripPadding — recovers original", () => {
  const original = Buffer.from("hello world");
  const padded = decodeEngine.padPayload(original, 16);
  const stripped = decodeEngine.stripPadding(padded.data, padded.originalLength);
  assert.strictEqual(stripped.length, original.length);
  assert.strictEqual(stripped.toString(), "hello world");
});

// =========================================================================
// STAGE 197: Decode event bus
// =========================================================================
console.log("\n--- STAGE 197: Decode event bus ---");

test("eventBus — on and emit", () => {
  const bus = decodeEngine.createDecodeEventBus();
  let received = null;
  bus.on("decode", (data) => { received = data; });
  bus.emit("decode", { config: "256x256-4c" });
  assert(received, "should receive event");
  assert.strictEqual(received.config, "256x256-4c");
});

test("eventBus — multiple listeners", () => {
  const bus = decodeEngine.createDecodeEventBus();
  let count = 0;
  bus.on("done", () => count++);
  bus.on("done", () => count++);
  const fired = bus.emit("done", {});
  assert.strictEqual(fired, 2);
  assert.strictEqual(count, 2);
});

test("eventBus — off removes listener", () => {
  const bus = decodeEngine.createDecodeEventBus();
  let count = 0;
  const fn = () => count++;
  bus.on("test", fn);
  bus.emit("test", {});
  assert.strictEqual(count, 1);
  bus.off("test", fn);
  bus.emit("test", {});
  assert.strictEqual(count, 1, "should not fire after off");
});

test("eventBus — once fires only once", () => {
  const bus = decodeEngine.createDecodeEventBus();
  let count = 0;
  bus.once("init", () => count++);
  bus.emit("init", {});
  bus.emit("init", {});
  assert.strictEqual(count, 1, "once should fire exactly once");
});

test("eventBus — listenerCount and clear", () => {
  const bus = decodeEngine.createDecodeEventBus();
  bus.on("a", () => {});
  bus.on("a", () => {});
  bus.on("b", () => {});
  assert.strictEqual(bus.listenerCount("a"), 2);
  assert.strictEqual(bus.listenerCount("b"), 1);
  assert.strictEqual(bus.listenerCount("c"), 0);
  bus.clear();
  assert.strictEqual(bus.listenerCount("a"), 0);
});

test("eventBus — unsubscribe via return value", () => {
  const bus = decodeEngine.createDecodeEventBus();
  let count = 0;
  const unsub = bus.on("x", () => count++);
  bus.emit("x", {});
  assert.strictEqual(count, 1);
  unsub(); // unsubscribe
  bus.emit("x", {});
  assert.strictEqual(count, 1);
});

