// =========================================================================
// STAGE 200: Payload header builder/parser
// =========================================================================
console.log("\n--- STAGE 200: Payload header builder/parser ---");

test("payloadHeader — build and parse roundtrip", () => {
  const payload = Buffer.from("Hello Aurexis Header!");
  const built = decodeEngine.buildPayloadHeader(payload);
  assert.strictEqual(built.header.length, 14);
  assert.strictEqual(built.payloadLength, payload.length);
  assert(built.combined.length === 14 + payload.length);
  const parsed = decodeEngine.parsePayloadHeader(built.combined);
  assert(parsed.valid, "roundtrip should be valid");
  assert(parsed.integrityOk, "CRC should match");
  assert.strictEqual(parsed.length, payload.length);
  assert.strictEqual(parsed.payload.toString(), "Hello Aurexis Header!");
});

test("payloadHeader — bad magic rejected", () => {
  const buf = Buffer.alloc(20);
  buf.writeUInt32BE(0x00000000, 0);
  const parsed = decodeEngine.parsePayloadHeader(buf);
  assert(!parsed.valid);
  assert.strictEqual(parsed.error, "bad magic");
});

test("payloadHeader — truncated data detected", () => {
  const payload = Buffer.from("test");
  const built = decodeEngine.buildPayloadHeader(payload);
  // Truncate: only include header + 2 bytes instead of 4
  const truncated = built.combined.slice(0, 16);
  const parsed = decodeEngine.parsePayloadHeader(truncated);
  assert(!parsed.valid);
  assert.strictEqual(parsed.error, "truncated");
});

test("payloadHeader — tampered payload detected", () => {
  const payload = Buffer.from("integrity test");
  const built = decodeEngine.buildPayloadHeader(payload);
  // Tamper with payload portion
  built.combined[14] = 0xFF;
  const parsed = decodeEngine.parsePayloadHeader(built.combined);
  assert(!parsed.integrityOk, "tampered payload should fail CRC");
});

