// =========================================================================
// STAGE 203: Pipeline builder (fluent API)
// =========================================================================
console.log("\n--- STAGE 203: Pipeline builder ---");

test("pipelineBuilder — fluent step execution", () => {
  const pb = decodeEngine.createPipelineBuilder();
  pb.addStep("double", x => x * 2)
    .addStep("add10", x => x + 10);
  const r = pb.execute(5);
  assert(r.success, "should succeed");
  assert.strictEqual(r.data, 20); // (5*2)+10
  assert.strictEqual(r.log.length, 2);
  assert(r.log[0].success);
  assert(r.log[1].success);
});

test("pipelineBuilder — disable/enable step", () => {
  const pb = decodeEngine.createPipelineBuilder();
  pb.addStep("a", x => x + 1)
    .addStep("b", x => x * 10)
    .addStep("c", x => x + 5);
  pb.disableStep("b");
  const r = pb.execute(1);
  assert.strictEqual(r.data, 7); // (1+1)+5=7 (b skipped)
  assert.strictEqual(r.log[1].skipped, true);
  pb.enableStep("b");
  const r2 = pb.execute(1);
  assert.strictEqual(r2.data, 25); // (1+1)*10+5=25
});

test("pipelineBuilder — error handling", () => {
  const pb = decodeEngine.createPipelineBuilder();
  pb.addStep("ok", x => x + 1)
    .addStep("fail", () => { throw new Error("boom"); })
    .addStep("never", x => x + 100);
  const r = pb.execute(0);
  assert(!r.success, "should fail");
  assert.strictEqual(r.failedStep, "fail");
  assert.strictEqual(r.data, 1); // data from last successful step
});

test("pipelineBuilder — getSteps and count", () => {
  const pb = decodeEngine.createPipelineBuilder();
  pb.addStep("x", x => x).addStep("y", x => x);
  assert.strictEqual(pb.count(), 2);
  const steps = pb.getSteps();
  assert.strictEqual(steps.length, 2);
  assert.strictEqual(steps[0].name, "x");
  assert(steps[0].enabled);
});

