console.log("\n--- STAGE 214: Decode quality scorer ---");

test("scoreDecodeQuality — perfect result", () => {
  const r = decodeEngine.scoreDecodeQuality({ success: true, confidence: 0.99, corrections: 0, maxCorrections: 32 });
  assert(r.score >= 0.95, `score should be >= 0.95, got ${r.score}`);
  assert(r.grade === 'A+' || r.grade === 'A', `grade should be A+/A, got ${r.grade}`);
});

test("scoreDecodeQuality — marginal result", () => {
  const r = decodeEngine.scoreDecodeQuality({ success: true, confidence: 0.5, corrections: 20, maxCorrections: 32 });
  assert(r.score < 0.8, `score should be < 0.8, got ${r.score}`);
  assert(r.factors.confidence === 0.5);
});

test("scoreDecodeQuality — failed result", () => {
  const r = decodeEngine.scoreDecodeQuality({ success: false });
  assert.strictEqual(r.score, 0);
  assert.strictEqual(r.grade, 'F');
});

test("scoreDecodeQuality — null input", () => {
  const r = decodeEngine.scoreDecodeQuality(null);
  assert.strictEqual(r.score, 0);
  assert.strictEqual(r.grade, 'F');
});

// =========================================================================
// STAGE 215: Config selector by payload content
// =========================================================================
console.log("\n--- STAGE 215: Config selector by content ---");

test("selectConfigByContent — text payload", () => {
  const r = decodeEngine.selectConfigByContent(Buffer.from("Hello World, this is a text payload for Aurexis!"));
  assert(r.isTextLike, "should detect text");
  assert(r.recommended, "should recommend a config");
  assert(r.candidates.length > 0);
  assert(typeof r.entropy === 'number');
});

test("selectConfigByContent — binary payload", () => {
  const buf = Buffer.alloc(100);
  for (let i = 0; i < 100; i++) buf[i] = i & 0xFF;
  const r = decodeEngine.selectConfigByContent(buf);
  assert(!r.isTextLike, "should detect binary");
  assert(r.nsym >= 16, "binary should get higher nsym");
  assert(r.recommended);
});

test("selectConfigByContent — custom nsym", () => {
  const r = decodeEngine.selectConfigByContent(Buffer.from("test"), { nsym: 32 });
  assert(r.nsym >= 32, "should respect minimum nsym");
});

test("selectConfigByContent — large payload", () => {
  const big = Buffer.alloc(50000);
  for (let i = 0; i < 50000; i++) big[i] = i & 0xFF; // includes control chars => binary
  const r = decodeEngine.selectConfigByContent(big);
  assert(!r.isTextLike, "mixed bytes should be binary");
  if (r.recommended) {
    assert(r.candidates[0].dataBytes >= 50000);
  }
});

