console.log("\n--- STAGE 218: Config negotiation ---");

test("negotiateConfig — basic negotiation", () => {
  const r = decodeEngine.negotiateConfig(
    { maxGrid: 512, maxColors: 4, minBytes: 100 },
    { supportedConfigs: Object.keys(format.HD_CONFIGS), maxNsym: 16 }
  );
  assert(r.compatible, "should find compatible config");
  assert(r.negotiated, "should have negotiated config");
  // Verify constraints respected
  const cfg = format.HD_CONFIGS[r.negotiated];
  assert(cfg.grid <= 512, "grid should be <= 512");
});

test("negotiateConfig — preferSpeed picks small grid", () => {
  const r = decodeEngine.negotiateConfig(
    { minBytes: 10, preferSpeed: true },
    { supportedConfigs: Object.keys(format.HD_CONFIGS), maxNsym: 16 }
  );
  assert(r.negotiated);
  // First candidate should be smallest grid
  assert(r.candidates[0].grid <= r.candidates[r.candidates.length - 1].grid);
});

test("negotiateConfig — impossible constraints", () => {
  const r = decodeEngine.negotiateConfig(
    { maxGrid: 64, minBytes: 999999 },
    { supportedConfigs: Object.keys(format.HD_CONFIGS), maxNsym: 16 }
  );
  assert(!r.compatible);
  assert.strictEqual(r.negotiated, null);
});

test("negotiateConfig — restricted server configs", () => {
  const r = decodeEngine.negotiateConfig(
    { minBytes: 10 },
    { supportedConfigs: ["256x256-4c", "384x384-4c"], maxNsym: 16 }
  );
  assert(r.compatible);
  assert(r.candidates.length <= 2);
});

