test("blockProgress — mark complete", () => {
  const bt = decodeEngine.createBlockProgressTracker(10);
  bt.markComplete(0); bt.markComplete(1); bt.markComplete(2);
  const p = bt.getProgress();
  assert.strictEqual(p.completed, 3);
  assert.strictEqual(p.pending, 7);
  assert.strictEqual(p.pct, 30);
  assert(!p.done);
});

test("blockProgress — mark failed", () => {
  const bt = decodeEngine.createBlockProgressTracker(5);
  bt.markComplete(0); bt.markComplete(1);
  bt.markFailed(2); bt.markFailed(3);
  bt.markComplete(4);
  const p = bt.getProgress();
  assert.strictEqual(p.completed, 3);
  assert.strictEqual(p.failed, 2);
  assert(p.done);
  assert(!p.allSuccess);
  const fb = bt.getFailedBlocks();
  assert.deepStrictEqual(fb, [2, 3]);
});

test("blockProgress — getStatus", () => {
  const bt = decodeEngine.createBlockProgressTracker(3);
  assert.strictEqual(bt.getStatus(0), "pending");
  bt.markComplete(0);
  assert.strictEqual(bt.getStatus(0), "complete");
  bt.markFailed(1);
  assert.strictEqual(bt.getStatus(1), "failed");
});

test("blockProgress — all success", () => {
  const bt = decodeEngine.createBlockProgressTracker(3);
  bt.markComplete(0); bt.markComplete(1); bt.markComplete(2);
  assert(bt.getProgress().allSuccess);
});

// =========================================================================
// STAGE 223: Checksum chain
// =========================================================================
console.log("\n--- STAGE 223: Checksum chain ---");

test("checksumChain — build and verify roundtrip", () => {
  const payload = Buffer.from("Linked integrity checksum chain test payload data here!");
  const built = decodeEngine.buildChecksumChain(payload, 10);
  assert(built.chain.length > 0);
  assert(built.finalHash > 0 || built.finalHash === 0);
  const v = decodeEngine.verifyChecksumChain(payload, built.chain);
  assert(v.valid, "unmodified payload should verify");
  assert.strictEqual(v.errors.length, 0);
});

test("checksumChain — tamper detected", () => {
  const payload = Buffer.from("tamper chain detection test");
  const built = decodeEngine.buildChecksumChain(payload, 8);
  const tampered = Buffer.from(payload);
  tampered[0] = 0xFF;
  const v = decodeEngine.verifyChecksumChain(tampered, built.chain);
  assert(!v.valid, "tampered payload should fail chain verify");
  assert(v.errors.length > 0);
});

test("checksumChain — linked hashes cascade", () => {
  const payload = Buffer.from("cascade test data");
  const built = decodeEngine.buildChecksumChain(payload, 5);
  // Each link's prevHash should match previous link's linked value
  for (let i = 1; i < built.chain.length; i++) {
    assert.strictEqual(built.chain[i].prevHash, built.chain[i - 1].linked);
  }
});

