console.log("\n--- STAGE 234: Payload wrapper V2 ---");

test("wrapV2 — roundtrip", () => {
  const payload = Buffer.from("V2 wrapper test!");
  const w = decodeEngine.wrapPayloadV2(payload);
  assert.strictEqual(w.version, 2);
  assert(w.wrapped.length === payload.length + 8);
  const u = decodeEngine.unwrapPayloadV2(w.wrapped);
  assert(u.valid, "roundtrip should be valid");
  assert(u.crcOk, "CRC should match");
  assert.strictEqual(u.payload.toString(), "V2 wrapper test!");
});

test("wrapV2 — tamper detected", () => {
  const w = decodeEngine.wrapPayloadV2(Buffer.from("integrity"));
  w.wrapped[10] = 0xFF;
  const u = decodeEngine.unwrapPayloadV2(w.wrapped);
  assert(!u.crcOk, "tampered data should fail CRC");
});

test("wrapV2 — too short rejected", () => {
  const u = decodeEngine.unwrapPayloadV2(Buffer.alloc(2));
  assert(!u.valid);
});

test("wrapV2 — custom flags", () => {
  const w = decodeEngine.wrapPayloadV2(Buffer.from("flags"), { flags: 0x42 });
  const u = decodeEngine.unwrapPayloadV2(w.wrapped);
  assert.strictEqual(u.flags, 0x42);
});

