test("encrypt — roundtrip with passphrase", () => {
  const payload = Buffer.from("Secret Aurexis payload!");
  const encrypted = decodeEngine.encryptPayload(payload, "mypassword", "salt123");
  assert(!encrypted.equals(payload), "encrypted should differ");
  const decrypted = decodeEngine.decryptPayload(encrypted, "mypassword", "salt123");
  assert.strictEqual(decrypted.toString(), "Secret Aurexis payload!");
});

test("encrypt — wrong passphrase fails", () => {
  const payload = Buffer.from("classified data");
  const encrypted = decodeEngine.encryptPayload(payload, "correct", "salt");
  const decrypted = decodeEngine.decryptPayload(encrypted, "wrong", "salt");
  assert(decrypted.toString() !== "classified data", "wrong key should not decrypt");
});

test("encrypt — key derivation deterministic", () => {
  const k1 = decodeEngine.derivePayloadKey("pass", "salt");
  const k2 = decodeEngine.derivePayloadKey("pass", "salt");
  assert(k1.equals(k2), "same inputs should produce same key");
  assert.strictEqual(k1.length, 16);
});

test("encrypt — different salt gives different key", () => {
  const k1 = decodeEngine.derivePayloadKey("pass", "salt1");
  const k2 = decodeEngine.derivePayloadKey("pass", "salt2");
  assert(!k1.equals(k2), "different salt should produce different key");
});

