// STAGE 239: Compression level estimator
// =========================================================================
console.log("\n--- STAGE 239: Compression levels ---");

test("compressedSizes — compressible payload", () => {
  const payload = Buffer.alloc(1000, 0x41);
  const r = decodeEngine.estimateCompressedSizes(payload);
  assert.strictEqual(r.original, 1000);
  assert(r.levels.length === 4);
  assert(r.bestLevel.ratio > 1, "compressible payload should compress");
  assert(r.bestLevel.savings > 50, "should save > 50%");
  // Higher levels should compress at least as well
  assert(r.levels[3].size <= r.levels[0].size, "level 9 should be <= level 1");
});

test("compressedSizes — incompressible payload", () => {
  const buf = Buffer.alloc(500);
  for (let i = 0; i < 500; i++) buf[i] = (i * 131 + 17) & 0xFF;
  const r = decodeEngine.estimateCompressedSizes(buf);
  assert(r.levels.length === 4);
  // May not compress well, but should not error
  assert(r.bestLevel.size > 0);
});

test("compressedSizes — empty payload", () => {
  const r = decodeEngine.estimateCompressedSizes(Buffer.alloc(0));
  assert.strictEqual(r.original, 0);
  assert.strictEqual(r.levels.length, 0);
});

