// STAGE 242: Auto-tune nsym
// =========================================================================
console.log("\n--- STAGE 242: Auto-tune nsym ---");

test("autoTuneNsym — no history returns default", () => {
  const r = decodeEngine.autoTuneNsym([]);
  assert.strictEqual(r.nsym, 8);
  assert.strictEqual(r.reason, "no-history");
});

test("autoTuneNsym — high fail rate increases nsym", () => {
  const history = Array(10).fill(null).map(() => ({ success: false, corrections: 10 }));
  const r = decodeEngine.autoTuneNsym(history);
  assert(r.nsym >= 32, `nsym should be >= 32 for high fail rate, got ${r.nsym}`);
  assert(r.failRate > 0.3, "fail rate should be reported");
});

test("autoTuneNsym — low corrections decreases nsym", () => {
  const history = Array(10).fill(null).map(() => ({ success: true, corrections: 0 }));
  const r = decodeEngine.autoTuneNsym(history);
  assert(r.nsym <= 8, `nsym should be <= 8 for zero corrections, got ${r.nsym}`);
  assert.strictEqual(r.reason, "low-corrections");
});

test("autoTuneNsym — respects min/max bounds", () => {
  const history = Array(10).fill(null).map(() => ({ success: false, corrections: 50 }));
  const r = decodeEngine.autoTuneNsym(history, { minNsym: 10, maxNsym: 20 });
  assert(r.nsym >= 10, "should respect minNsym");
  assert(r.nsym <= 20, "should respect maxNsym");
  assert(r.nsym % 2 === 0, "must be even");
});

