test("createDecodeSessionStats — record and retrieve", () => {
  const stats = decodeEngine.createDecodeSessionStats();
  stats.record({ confidence: 0.9, corrections: 2, success: true, config: "256x256-4c", durationMs: 50 });
  stats.record({ confidence: 0.8, corrections: 5, success: true, config: "256x256-4c", durationMs: 80 });
  stats.record({ confidence: 0.3, corrections: 10, success: false, config: "384x384-4c", durationMs: 200 });
  const s = stats.getStats();
  assert.strictEqual(s.count, 3);
  assert(s.successRate > 0.6, "2/3 success rate");
  assert(s.avgConfidence > 0.6, "avg confidence");
  assert(s.configBreakdown["256x256-4c"] === 2, "config breakdown");
});

test("createDecodeSessionStats — percentiles", () => {
  const stats = decodeEngine.createDecodeSessionStats();
  for (let i = 0; i < 20; i++) {
    stats.record({ confidence: i / 20, corrections: i, success: true, durationMs: i * 10 });
  }
  const s = stats.getStats();
  assert(s.p50Confidence > 0, "p50 should be > 0");
  assert(s.p95Confidence > s.p50Confidence, "p95 > p50");
});

test("createDecodeSessionStats — clear", () => {
  const stats = decodeEngine.createDecodeSessionStats();
  stats.record({ confidence: 0.9, corrections: 0, success: true });
  stats.clear();
  assert.strictEqual(stats.getEntryCount(), 0);
  assert.strictEqual(stats.getStats().count, 0);
});

