console.log("\n--- STAGE 250: Payload streamer ---");

test("createPayloadStreamer — iterates all chunks", () => {
  const payload = Buffer.alloc(250, 0x42);
  const streamer = decodeEngine.createPayloadStreamer(payload, 100);
  assert.strictEqual(streamer.totalChunks, 3);
  let total = 0;
  let chunk;
  while (!(chunk = streamer.next()).done) {
    total += chunk.value.size;
  }
  assert.strictEqual(total, 250);
});

test("createPayloadStreamer — progress tracking", () => {
  const streamer = decodeEngine.createPayloadStreamer(Buffer.alloc(200), 100);
  assert.strictEqual(streamer.progress(), 0);
  streamer.next();
  assert(streamer.progress() > 0.4, "should show progress");
  streamer.next();
  assert.strictEqual(streamer.progress(), 1);
});

test("createPayloadStreamer — reset works", () => {
  const streamer = decodeEngine.createPayloadStreamer(Buffer.alloc(100), 50);
  streamer.next();
  streamer.next();
  assert(streamer.next().done, "should be done");
  streamer.reset();
  assert(!streamer.next().done, "should restart after reset");
});

test("createPayloadStreamer — remaining bytes", () => {
  const streamer = decodeEngine.createPayloadStreamer(Buffer.alloc(300), 100);
  assert.strictEqual(streamer.remaining(), 300);
  streamer.next();
  assert.strictEqual(streamer.remaining(), 200);
});

