console.log("\n--- STAGE 262: Decode retry tracker ---");

test("createDecodeRetryTracker — track retries", () => {
  const tracker = decodeEngine.createDecodeRetryTracker({ maxRetries: 3 });
  const id = tracker.startSession();
  assert(tracker.shouldRetry(id), "should retry initially");
  tracker.recordAttempt(id, { success: false });
  tracker.recordAttempt(id, { success: false });
  tracker.recordAttempt(id, { success: false });
  assert(!tracker.shouldRetry(id), "exhausted after 3");
  const session = tracker.getSession(id);
  assert.strictEqual(session.retries, 3);
  assert(session.exhausted, "should be exhausted");
});

test("createDecodeRetryTracker — unknown session", () => {
  const tracker = decodeEngine.createDecodeRetryTracker();
  assert(!tracker.shouldRetry(999), "unknown = no retry");
  assert.strictEqual(tracker.getSession(999), null);
});

test("createDecodeRetryTracker — active count", () => {
  const tracker = decodeEngine.createDecodeRetryTracker();
  tracker.startSession();
  tracker.startSession();
  assert.strictEqual(tracker.activeCount(), 2);
});

