console.log("\n--- STAGE 263: Payload entropy ---");

test("estimatePayloadEntropy — random data is high entropy", () => {
  const buf = Buffer.alloc(1000);
  for (let i = 0; i < buf.length; i++) buf[i] = i & 0xFF;
  const r = decodeEngine.estimatePayloadEntropy(buf);
  assert(r.entropy > 7, `expected high entropy, got ${r.entropy}`);
  assert.strictEqual(r.classification, "random");
  assert.strictEqual(r.uniqueBytes, 256);
});

test("estimatePayloadEntropy — uniform data is zero entropy", () => {
  const r = decodeEngine.estimatePayloadEntropy(Buffer.alloc(100, 0x42));
  assert.strictEqual(r.entropy, 0);
  assert.strictEqual(r.uniqueBytes, 1);
  assert.strictEqual(r.classification, "structured");
});

test("estimatePayloadEntropy — empty payload", () => {
  const r = decodeEngine.estimatePayloadEntropy(Buffer.alloc(0));
  assert.strictEqual(r.entropy, 0);
  assert.strictEqual(r.size, 0);
});

test("estimatePayloadEntropy — text is medium entropy", () => {
  const r = decodeEngine.estimatePayloadEntropy(Buffer.from("The quick brown fox jumps over the lazy dog repeatedly many times"));
  assert(r.entropy > 3 && r.entropy < 7, `expected medium entropy, got ${r.entropy}`);
});

