// =========================================================================
// STAGE 274: Chunked encoder
// =========================================================================
console.log("\n--- STAGE 274: Chunked encoder ---");

test("createPayloadChunkedEncoder — encode and decode roundtrip", () => {
  const encoder = decodeEngine.createPayloadChunkedEncoder(100);
  const original = Buffer.alloc(350, 0);
  for (let i = 0; i < original.length; i++) original[i] = i & 0xFF;
  const encoded = encoder.encode(original);
  assert.strictEqual(encoded.totalChunks, 4);
  assert.strictEqual(encoded.chunks[0].seq, 0);
  const decoded = encoder.decode(encoded.chunks);
  assert.deepStrictEqual(decoded, original);
});

test("createPayloadChunkedEncoder — chunks have headers", () => {
  const encoder = decodeEngine.createPayloadChunkedEncoder(50);
  const encoded = encoder.encode(Buffer.alloc(120));
  for (const chunk of encoded.chunks) {
    assert(chunk.encoded.length > chunk.data.length, "encoded includes header");
    assert.strictEqual(chunk.encoded.readUInt16BE(2), encoded.totalChunks);
  }
});

test("createPayloadChunkedEncoder — out-of-order decode", () => {
  const encoder = decodeEngine.createPayloadChunkedEncoder(50);
  const original = Buffer.from("ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789abcdefghijklmnopqrstuvwxyz");
  const encoded = encoder.encode(original);
  // Shuffle chunks
  const shuffled = [...encoded.chunks].reverse();
  const decoded = encoder.decode(shuffled);
  assert.deepStrictEqual(decoded, original);
});

