console.log("\n--- STAGE 275: Hamming distance ---");

test("computeHammingDistance — identical payloads", () => {
  const a = Buffer.from([0xFF, 0x00, 0xAA]);
  const r = decodeEngine.computeHammingDistance(a, a);
  assert.strictEqual(r.distance, 0);
  assert(r.identical, "should be identical");
  assert.strictEqual(r.rate, 0);
});

test("computeHammingDistance — single bit flip", () => {
  const a = Buffer.from([0b10000000]);
  const b = Buffer.from([0b00000000]);
  const r = decodeEngine.computeHammingDistance(a, b);
  assert.strictEqual(r.distance, 1);
  assert.strictEqual(r.totalBits, 8);
});

test("computeHammingDistance — all bits different", () => {
  const a = Buffer.from([0xFF]);
  const b = Buffer.from([0x00]);
  const r = decodeEngine.computeHammingDistance(a, b);
  assert.strictEqual(r.distance, 8);
  assert.strictEqual(r.rate, 1);
});

test("computeHammingDistance — different lengths", () => {
  const a = Buffer.from([0x00, 0x00]);
  const b = Buffer.from([0x00]);
  const r = decodeEngine.computeHammingDistance(a, b);
  assert.strictEqual(r.distance, 8); // extra byte = 8 bits different
  assert.strictEqual(r.lengthA, 2);
  assert.strictEqual(r.lengthB, 1);
});

