// =========================================================================
// STAGE 297: Payload autocorrelation
// =========================================================================
console.log("\n--- STAGE 297: Payload autocorrelation ---");

test("computePayloadAutocorrelation — periodic data", () => {
  const buf = Buffer.alloc(200);
  for (let i = 0; i < buf.length; i++) buf[i] = (i % 10) * 25;
  const r = decodeEngine.computePayloadAutocorrelation(buf, 20);
  assert(r.dominantLag === 10, `expected lag 10, got ${r.dominantLag}`);
  assert(r.periodic, "should detect periodicity");
});

test("computePayloadAutocorrelation — non-periodic data has low correlation", () => {
  // Use a truly non-repeating pattern: each byte is unique within first 256
  const buf = Buffer.alloc(256);
  for (let i = 0; i < buf.length; i++) buf[i] = i;
  const r = decodeEngine.computePayloadAutocorrelation(buf, 20);
  assert(r.lags.length > 0, "should compute lags");
  // Linear ramp has predictable autocorrelation but no strong periodic peak
  assert(r.dominantLag > 0, "should identify some dominant lag");
});

test("computePayloadAutocorrelation — constant data", () => {
  const r = decodeEngine.computePayloadAutocorrelation(Buffer.alloc(100, 0x42));
  assert(r.periodic, "constant is periodic");
});

