// STAGE 325: Config load balancer
// =========================================================================
console.log("\n--- STAGE 325: Config load balancer ---");

test("createConfigLoadBalancer — round-robin acquire", () => {
  const lb = decodeEngine.createConfigLoadBalancer(["a", "b", "c"]);
  const first = lb.acquire();
  assert(["a", "b", "c"].includes(first));
  lb.release(first);
  const second = lb.acquire();
  assert(["a", "b", "c"].includes(second));
});

test("createConfigLoadBalancer — least loaded selection", () => {
  const lb = decodeEngine.createConfigLoadBalancer(["x", "y"]);
  lb.acquire(); // x gets loaded (active=1)
  const next = lb.acquire(); // should pick y (active=0)
  assert.strictEqual(next, "y");
});

test("createConfigLoadBalancer — release tracking", () => {
  const lb = decodeEngine.createConfigLoadBalancer(["m", "n"]);
  lb.acquire(); // m
  lb.release("m", { time: 100 });
  const stats = lb.getLoad("m");
  assert.strictEqual(stats.completed, 1);
  assert.strictEqual(stats.active, 0);
  assert.strictEqual(stats.totalTime, 100);
});

test("createConfigLoadBalancer — failed release", () => {
  const lb = decodeEngine.createConfigLoadBalancer(["p"]);
  lb.acquire();
  lb.release("p", { failed: true });
  assert.strictEqual(lb.getLoad("p").failed, 1);
  assert.strictEqual(lb.getLoad("p").completed, 0);
});

