// STAGE 333: Payload XOR mask
// =========================================================================
console.log("\n--- STAGE 333: Payload XOR mask ---");

test("applyPayloadXorMask — apply and reverse", () => {
  const payload = Buffer.from([0x41, 0x42, 0x43]);
  const mask = Buffer.from([0xFF]);
  const masked = decodeEngine.applyPayloadXorMask(payload, mask);
  assert.deepStrictEqual(Array.from(masked.payload), [0xBE, 0xBD, 0xBC]);
  assert(masked.isReversible);
  const unmasked = decodeEngine.applyPayloadXorMask(masked.payload, mask);
  assert.deepStrictEqual(Array.from(unmasked.payload), Array.from(payload));
});

test("applyPayloadXorMask — multi-byte mask wraps", () => {
  const payload = Buffer.from([1, 2, 3, 4]);
  const mask = Buffer.from([0x10, 0x20]);
  const r = decodeEngine.applyPayloadXorMask(payload, mask);
  assert.strictEqual(r.payload[0], 1 ^ 0x10);
  assert.strictEqual(r.payload[1], 2 ^ 0x20);
  assert.strictEqual(r.payload[2], 3 ^ 0x10);
  assert.strictEqual(r.payload[3], 4 ^ 0x20);
});

