console.log("\n--- STAGE 349: Decode semaphore ---");

test("createDecodeSemaphore — basic acquire/release", () => {
  const sem = decodeEngine.createDecodeSemaphore(2);
  assert(sem.tryAcquire());
  assert(sem.tryAcquire());
  assert(!sem.tryAcquire()); // exhausted
  sem.release();
  assert(sem.tryAcquire()); // freed up
});

test("createDecodeSemaphore — stats", () => {
  const sem = decodeEngine.createDecodeSemaphore(3);
  sem.tryAcquire(); sem.tryAcquire();
  sem.release();
  const s = sem.getStats();
  assert.strictEqual(s.maxPermits, 3);
  assert.strictEqual(s.totalAcquired, 2);
  assert.strictEqual(s.totalReleased, 1);
  assert.strictEqual(s.available, 2);
});

test("createDecodeSemaphore — enqueue callback", () => {
  const sem = decodeEngine.createDecodeSemaphore(1);
  sem.tryAcquire();
  let called = false;
  sem.enqueue(() => { called = true; });
  assert.strictEqual(sem.waiting(), 1);
  sem.release(); // should trigger callback
  assert(called);
});

