// =========================================================================
// STAGE 353: Decode resource pool
// =========================================================================
console.log("\n--- STAGE 353: Decode resource pool ---");

test("createDecodeResourcePool — acquire and release", () => {
  let id = 0;
  const pool = decodeEngine.createDecodeResourcePool(() => ({ id: id++ }), { maxSize: 3 });
  const r1 = pool.acquire();
  const r2 = pool.acquire();
  assert.strictEqual(r1.id, 0);
  assert.strictEqual(r2.id, 1);
  pool.release(r1);
  const r3 = pool.acquire(); // should reuse r1
  assert.strictEqual(r3.id, 0);
});

test("createDecodeResourcePool — max size limit", () => {
  const pool = decodeEngine.createDecodeResourcePool(() => ({}), { maxSize: 2 });
  pool.acquire(); pool.acquire();
  assert.strictEqual(pool.acquire(), null); // at capacity
  assert.strictEqual(pool.size(), 2);
});

test("createDecodeResourcePool — drain", () => {
  const pool = decodeEngine.createDecodeResourcePool(() => ({}), { maxSize: 5 });
  const r1 = pool.acquire();
  const r2 = pool.acquire();
  pool.release(r1); pool.release(r2);
  assert.strictEqual(pool.available(), 2);
  const drained = pool.drain();
  assert.strictEqual(drained, 2);
  assert.strictEqual(pool.available(), 0);
});

