console.log("\n--- STAGE 359: Decode health monitor ---");

test("createDecodeHealthMonitor — track success rate", () => {
  const hm = decodeEngine.createDecodeHealthMonitor({ windowSize: 10 });
  for (let i = 0; i < 8; i++) hm.recordSuccess();
  for (let i = 0; i < 2; i++) hm.recordFailure();
  assertNear(hm.getSuccessRate(), 0.8, 0.01);
  assert(hm.isHealthy(0.5));
  assert(!hm.isHealthy(0.9));
});

test("createDecodeHealthMonitor — window eviction", () => {
  const hm = decodeEngine.createDecodeHealthMonitor({ windowSize: 5 });
  for (let i = 0; i < 5; i++) hm.recordFailure();
  assertNear(hm.getSuccessRate(), 0.0, 0.01);
  for (let i = 0; i < 5; i++) hm.recordSuccess();
  // window should now be all successes
  assertNear(hm.getSuccessRate(), 1.0, 0.01);
});

test("createDecodeHealthMonitor — reset", () => {
  const hm = decodeEngine.createDecodeHealthMonitor();
  hm.recordFailure(); hm.recordFailure();
  hm.reset();
  assert.strictEqual(hm.getStats().recentTotal, 0);
  assertNear(hm.getSuccessRate(), 1.0, 0.01); // empty = healthy
});

