test("createDecodeBackpressureController — pause on high water", () => {
  const bp = decodeEngine.createDecodeBackpressureController({ highWaterMark: 10, lowWaterMark: 3 });
  assert(!bp.isPaused());
  bp.produce(10);
  assert(bp.isPaused());
  bp.consume(5); // still above low water
  assert(bp.isPaused());
  bp.consume(3); // at 2, below low water
  assert(!bp.isPaused());
});

test("createDecodeBackpressureController — stats", () => {
  const bp = decodeEngine.createDecodeBackpressureController({ highWaterMark: 5, lowWaterMark: 1 });
  bp.produce(5);
  bp.consume(5);
  bp.produce(5);
  const s = bp.getStats();
  assert.strictEqual(s.totalPauses, 2);
});

