console.log("\n--- STAGE 376: Payload split into N parts ---");

test("splitPayloadIntoNParts — even split", () => {
  const buf = Buffer.from([1, 2, 3, 4, 5, 6]);
  const r = decodeEngine.splitPayloadIntoNParts(buf, 3);
  assert.strictEqual(r.partCount, 3);
  assert.strictEqual(r.parts[0].length, 2);
  assert.strictEqual(r.parts[1].length, 2);
  assert.strictEqual(r.parts[2].length, 2);
});

test("splitPayloadIntoNParts — uneven split", () => {
  const buf = Buffer.from([1, 2, 3, 4, 5]);
  const r = decodeEngine.splitPayloadIntoNParts(buf, 3);
  assert.strictEqual(r.partCount, 3);
  // 5/3 = 1r2, so first 2 parts get 2 bytes, last gets 1
  assert.strictEqual(r.parts[0].length, 2);
  assert.strictEqual(r.parts[1].length, 2);
  assert.strictEqual(r.parts[2].length, 1);
  const total = r.parts.reduce((s, p) => s + p.length, 0);
  assert.strictEqual(total, 5);
});

