console.log("\n--- STAGE 381: Decode orchestrator ---");

test("createDecodeOrchestrator — step through phases", () => {
  const orch = decodeEngine.createDecodeOrchestrator(["detect", "sample", "decode", "verify"]);
  assert.strictEqual(orch.currentPhase(), "detect");
  orch.advance({ found: true });
  assert.strictEqual(orch.currentPhase(), "sample");
  orch.advance({ sampled: 100 });
  orch.advance({ decoded: true });
  orch.advance({ verified: true });
  assert(orch.isComplete());
  const results = orch.getResults();
  assert(results.detect.found);
  assert.strictEqual(results.sample.sampled, 100);
});

test("createDecodeOrchestrator — fail and status", () => {
  const orch = decodeEngine.createDecodeOrchestrator(["a", "b"]);
  orch.advance("ok");
  orch.fail("boom");
  const status = orch.getStatus();
  assert.strictEqual(status[0].status, "complete");
  assert.strictEqual(status[1].status, "failed");
});

test("createDecodeOrchestrator — reset", () => {
  const orch = decodeEngine.createDecodeOrchestrator(["x", "y"]);
  orch.advance("done");
  orch.reset();
  assert.strictEqual(orch.currentPhase(), "x");
  assert(!orch.isComplete());
});

