// =========================================================================
// STAGE 385: Decode retry strategy
// =========================================================================
console.log("\n--- STAGE 385: Decode retry strategy ---");

test("createDecodeRetryStrategy — basic retry with backoff", () => {
  const rs = decodeEngine.createDecodeRetryStrategy({ maxRetries: 3, baseDelayMs: 100, backoffFactor: 2 });
  assert(rs.shouldRetry());
  assert.strictEqual(rs.nextDelay(), 100);
  rs.recordAttempt(false);
  assert.strictEqual(rs.nextDelay(), 200);
  rs.recordAttempt(false);
  assert.strictEqual(rs.nextDelay(), 400);
  rs.recordAttempt(false);
  assert(!rs.shouldRetry()); // exhausted
});

test("createDecodeRetryStrategy — reset", () => {
  const rs = decodeEngine.createDecodeRetryStrategy({ maxRetries: 1 });
  rs.recordAttempt(false);
  assert(!rs.shouldRetry());
  rs.reset();
  assert(rs.shouldRetry());
});

test("createDecodeRetryStrategy — max delay cap", () => {
  const rs = decodeEngine.createDecodeRetryStrategy({ maxRetries: 10, baseDelayMs: 1000, backoffFactor: 10, maxDelayMs: 5000 });
  rs.recordAttempt(false); rs.recordAttempt(false); rs.recordAttempt(false);
  assert(rs.nextDelay() <= 5000);
});

