// STAGE 397: Decode deadline scheduler
// =========================================================================
console.log("\n--- STAGE 397: Decode deadline scheduler ---");

test("createDecodeDeadlineScheduler — schedule and execute", () => {
  const sched = decodeEngine.createDecodeDeadlineScheduler();
  sched.schedule("urgent", 1000);
  sched.schedule("relaxed", 60000);
  const first = sched.next();
  assert.strictEqual(first.task, "urgent"); // earliest deadline first
  sched.complete(first.id);
  const stats = sched.getStats();
  assert.strictEqual(stats.completed, 1);
  assert.strictEqual(stats.pending, 1);
});

test("createDecodeDeadlineScheduler — overdue detection", () => {
  const sched = decodeEngine.createDecodeDeadlineScheduler();
  sched.schedule("past", -1000); // already past deadline
  assert.strictEqual(sched.getOverdue(), 1);
});

