// =========================================================================
// STAGE 400: Payload whitener
// =========================================================================
console.log("\n--- STAGE 400: Payload whitener ---");

test("whitenPayload — zero mean unit variance", () => {
  const buf = Buffer.from([10, 20, 30, 40, 50]);
  const r = decodeEngine.whitenPayload(buf);
  assert.strictEqual(r.length, 5);
  // mean of whitened should be ~0
  let sum = 0;
  for (let i = 0; i < r.whitened.length; i++) sum += r.whitened[i];
  assertNear(sum / r.length, 0, 0.01);
  // variance should be ~1
  let var_ = 0;
  for (let i = 0; i < r.whitened.length; i++) var_ += r.whitened[i] * r.whitened[i];
  assertNear(var_ / r.length, 1.0, 0.01);
});

test("whitenPayload — constant data zeros out", () => {
  const buf = Buffer.from([128, 128, 128]);
  const r = decodeEngine.whitenPayload(buf);
  for (let i = 0; i < r.whitened.length; i++) assert.strictEqual(r.whitened[i], 0);
});

// =========================================================================
// STAGE 401: Decode result cache with TTL
// =========================================================================
console.log("\n--- STAGE 401: Decode result cache with TTL ---");

test("createDecodeResultCacheWithTtl — set and get", () => {
  const cache = decodeEngine.createDecodeResultCacheWithTtl({ ttlMs: 60000 });
  cache.set("key1", { data: "hello" });
  assert(cache.has("key1"));
  assert.strictEqual(cache.get("key1").data, "hello");
  assert.strictEqual(cache.size(), 1);
});

test("createDecodeResultCacheWithTtl — expired entries", () => {
  const cache = decodeEngine.createDecodeResultCacheWithTtl({ ttlMs: 60000 });
  cache.set("key1", "val1");
  // manually verify it exists before "expiry"
  assert(cache.has("key1"));
  // prune should not remove non-expired
  const pruned = cache.prune();
  assert.strictEqual(pruned, 0);
  assert(cache.has("key1"));
});

test("createDecodeResultCacheWithTtl — max size eviction", () => {
  const cache = decodeEngine.createDecodeResultCacheWithTtl({ maxSize: 2, ttlMs: 60000 });
  cache.set("a", 1); cache.set("b", 2); cache.set("c", 3);
  assert.strictEqual(cache.size(), 2);
  assert(!cache.has("a")); // evicted (oldest)
  assert(cache.has("b"));
  assert(cache.has("c"));
});

