// =========================================================================
// STAGE 410: Payload parity profile
// =========================================================================
console.log("\n--- STAGE 410: Payload parity profile ---");

test("computePayloadParityProfile — known parities", () => {
  // 0x00=0 bits (even), 0x01=1 bit (odd), 0x03=2 bits (even), 0x07=3 bits (odd)
  const buf = Buffer.from([0x00, 0x01, 0x03, 0x07]);
  const r = decodeEngine.computePayloadParityProfile(buf);
  assert.strictEqual(r.totalBytes, 4);
  assert.strictEqual(r.parities[0], 0); // 0 bits = even
  assert.strictEqual(r.parities[1], 1); // 1 bit = odd
  assert.strictEqual(r.parities[2], 0); // 2 bits = even
  assert.strictEqual(r.parities[3], 1); // 3 bits = odd
  assert.strictEqual(r.evenCount, 2);
  assert.strictEqual(r.oddCount, 2);
  assert.strictEqual(r.evenRatio, 0.5);
});

test("computePayloadParityProfile — all zeros", () => {
  const buf = Buffer.from([0, 0, 0]);
  const r = decodeEngine.computePayloadParityProfile(buf);
  assert.strictEqual(r.evenCount, 3);
  assert.strictEqual(r.oddCount, 0);
  assert.strictEqual(r.evenRatio, 1);
});

test("computePayloadParityProfile — 0xFF is even parity (8 bits)", () => {
  const buf = Buffer.from([0xFF]);
  const r = decodeEngine.computePayloadParityProfile(buf);
  assert.strictEqual(r.parities[0], 0); // 8 bits = even
  assert.strictEqual(r.evenCount, 1);
});

test("computePayloadParityProfile — empty buffer", () => {
  const r = decodeEngine.computePayloadParityProfile(Buffer.alloc(0));
  assert.strictEqual(r.totalBytes, 0);
  assert.strictEqual(r.evenCount, 0);
  assert.strictEqual(r.oddCount, 0);
  assert.strictEqual(r.evenRatio, 0);
});

test("computePayloadParityProfile — throws on non-Buffer", () => {
  let threw = false;
  try { decodeEngine.computePayloadParityProfile("hello"); } catch(e) { threw = true; }
  assert(threw);
});

