console.log("\n--- STAGE 413: Config suitability scorer ---");

test("scoreConfigSuitability — baseline score for valid config", () => {
  const r = decodeEngine.scoreConfigSuitability("256x256-4c", {});
  assert(r.valid);
  assert.strictEqual(r.score, 50);
  assert.strictEqual(r.configName, "256x256-4c");
  assert.strictEqual(r.colors, 4);
});

test("scoreConfigSuitability — invalid config returns score 0", () => {
  const r = decodeEngine.scoreConfigSuitability("999x999-4c", {});
  assert(!r.valid);
  assert.strictEqual(r.score, 0);
});

test("scoreConfigSuitability — lowLight favors 4c", () => {
  const r4c = decodeEngine.scoreConfigSuitability("256x256-4c", { lowLight: true });
  const r8c = decodeEngine.scoreConfigSuitability("256x256-8c", { lowLight: true });
  assert(r4c.score > r8c.score, "4-color should score higher in low light than 8-color");
});

test("scoreConfigSuitability — farDistance favors large grid", () => {
  const rSmall = decodeEngine.scoreConfigSuitability("128x128-4c", { farDistance: true });
  const rLarge = decodeEngine.scoreConfigSuitability("512x512-4c", { farDistance: true });
  assert(rLarge.score > rSmall.score, "larger grid should score higher at far distance");
});

test("scoreConfigSuitability — fastDecode favors small grid", () => {
  const rSmall = decodeEngine.scoreConfigSuitability("128x128-4c", { fastDecode: true });
  const rLarge = decodeEngine.scoreConfigSuitability("512x512-4c", { fastDecode: true });
  assert(rSmall.score > rLarge.score, "smaller grid should score higher for fast decode");
});

test("scoreConfigSuitability — score clamped 0-100", () => {
  // Stack multiple penalties to push score below 0
  const r = decodeEngine.scoreConfigSuitability("128x128-4c", { farDistance: true, minCapacity: 999999 });
  assert(r.score >= 0);
  assert(r.score <= 100);
});

