console.log("\n--- STAGE 415: Config decode history ---");

test("createConfigDecodeHistory — track successes and failures", () => {
  const dh = decodeEngine.createConfigDecodeHistory();
  dh.record("128x128-4c", true, 50);
  dh.record("128x128-4c", true, 60);
  dh.record("128x128-4c", false, 200);
  const s = dh.getStats("128x128-4c");
  assert.strictEqual(s.successes, 2);
  assert.strictEqual(s.failures, 1);
  assert.strictEqual(s.total, 3);
  assertNear(s.successRate, 0.6667, 0.001);
});

test("createConfigDecodeHistory — unknown config returns zero stats", () => {
  const dh = decodeEngine.createConfigDecodeHistory();
  const s = dh.getStats("nonexistent");
  assert.strictEqual(s.successes, 0);
  assert.strictEqual(s.total, 0);
  assert.strictEqual(s.successRate, 0);
});

test("createConfigDecodeHistory — getBestConfig", () => {
  const dh = decodeEngine.createConfigDecodeHistory();
  dh.record("128x128-4c", true); dh.record("128x128-4c", false);
  dh.record("256x256-4c", true); dh.record("256x256-4c", true);
  assert.strictEqual(dh.getBestConfig(), "256x256-4c");
});

test("createConfigDecodeHistory — reset single config", () => {
  const dh = decodeEngine.createConfigDecodeHistory();
  dh.record("128x128-4c", true);
  dh.reset("128x128-4c");
  assert.strictEqual(dh.getStats("128x128-4c").total, 0);
});

test("createConfigDecodeHistory — maxEntries limits history", () => {
  const dh = decodeEngine.createConfigDecodeHistory({ maxEntries: 3 });
  for (let i = 0; i < 5; i++) dh.record("128x128-4c", true, i * 10);
  // successes count is still 5, but entries trimmed to 3
  assert.strictEqual(dh.getStats("128x128-4c").successes, 5);
});

