console.log("\n--- STAGE 416: Payload byte transition matrix ---");

test("buildPayloadTransitionMatrix — basic transitions", () => {
  const buf = Buffer.from([0x00, 0xF0, 0x00, 0xF0]);
  const r = decodeEngine.buildPayloadTransitionMatrix(buf, 4);
  assert.strictEqual(r.buckets, 16);
  assert.strictEqual(r.totalTransitions, 3);
  // 0x00>>4=0, 0xF0>>4=15, so transitions: 0->15, 15->0, 0->15
  assert.strictEqual(r.matrix[0][15], 2);
  assert.strictEqual(r.matrix[15][0], 1);
});

test("buildPayloadTransitionMatrix — mostCommon", () => {
  const buf = Buffer.from([10, 20, 10, 20, 10]); // 10>>4=0, 20>>4=1, alternating
  const r = decodeEngine.buildPayloadTransitionMatrix(buf, 4);
  assert(r.mostCommon.count >= 2);
});

test("buildPayloadTransitionMatrix — default bucketBits 4", () => {
  const buf = Buffer.from([0, 128, 255]);
  const r = decodeEngine.buildPayloadTransitionMatrix(buf);
  assert.strictEqual(r.bucketBits, 4);
  assert.strictEqual(r.buckets, 16);
});

