console.log("\n--- STAGE 417: Decode session timer ---");

test("createDecodeSessionTimer — start and stop phase", () => {
  const t = decodeEngine.createDecodeSessionTimer();
  t.start("detect");
  t.stop();
  const p = t.getPhase("detect");
  assert.strictEqual(p.count, 1);
  assert(typeof p.totalMs === "number");
  assert(typeof p.avgMs === "number");
});

test("createDecodeSessionTimer — multiple phases", () => {
  const t = decodeEngine.createDecodeSessionTimer();
  t.start("find");
  t.stop();
  t.start("decode");
  t.stop();
  const r = t.getReport();
  assert(r.find);
  assert(r.decode);
  assert(typeof r._totalMs === "number");
});

test("createDecodeSessionTimer — unknown phase returns zero", () => {
  const t = decodeEngine.createDecodeSessionTimer();
  const p = t.getPhase("nonexistent");
  assert.strictEqual(p.totalMs, 0);
  assert.strictEqual(p.count, 0);
  assert.strictEqual(p.avgMs, 0);
});

test("createDecodeSessionTimer — auto-stop on new start", () => {
  const t = decodeEngine.createDecodeSessionTimer();
  t.start("a");
  t.start("b"); // should auto-stop "a"
  t.stop();
  assert.strictEqual(t.getPhase("a").count, 1);
  assert.strictEqual(t.getPhase("b").count, 1);
});

test("createDecodeSessionTimer — reset clears all", () => {
  const t = decodeEngine.createDecodeSessionTimer();
  t.start("x"); t.stop();
  t.reset();
  assert.strictEqual(t.getPhase("x").count, 0);
  assert.strictEqual(t.getTotalMs(), 0);
});

