console.log("\n--- STAGE 450: Payload byte skewness ---");

test("computePayloadSkewness — symmetric data near zero skew", () => {
  const buf = Buffer.from(Array.from({length: 256}, (_, i) => i));
  const r = decodeEngine.computePayloadSkewness(buf);
  assertNear(r.skewness, 0, 0.2);
});

test("computePayloadSkewness — right-skewed data", () => {
  // mostly low values with a few high
  const arr = Array(50).fill(10).concat([200, 210, 220, 230, 240]);
  const r = decodeEngine.computePayloadSkewness(Buffer.from(arr));
  assert(r.skewness > 0, "should be positively skewed");
});

test("computePayloadSkewness — constant data zero skew", () => {
  const r = decodeEngine.computePayloadSkewness(Buffer.alloc(20, 100));
  assert.strictEqual(r.skewness, 0);
  assert.strictEqual(r.stddev, 0);
});

test("computePayloadSkewness — short buffer returns zero", () => {
  const r = decodeEngine.computePayloadSkewness(Buffer.from([1, 2]));
  assert.strictEqual(r.skewness, 0);
});

test("computePayloadSkewness — throws on non-Buffer", () => {
  let threw = false;
  try { decodeEngine.computePayloadSkewness([1,2,3]); } catch(e) { threw = true; }
  assert(threw);
});

