test("createDecodePlan — valid config returns steps", () => {
  const r = decodeEngine.createDecodePlan("256x256-4c");
  assert(r.valid);
  assert(r.steps.length >= 5);
  assert.strictEqual(r.steps[0].phase, "detect");
  assert(r.totalEstimatedMs > 0);
});

test("createDecodePlan — multiPass adds feedback step", () => {
  const base = decodeEngine.createDecodePlan("256x256-4c");
  const multi = decodeEngine.createDecodePlan("256x256-4c", { multiPass: true });
  assert(multi.steps.length > base.steps.length);
  assert(multi.steps.some(s => s.phase === "feedback"));
});

test("createDecodePlan — verify adds verify step", () => {
  const r = decodeEngine.createDecodePlan("256x256-4c", { verify: true });
  assert(r.steps.some(s => s.phase === "verify"));
});

test("createDecodePlan — invalid config", () => {
  const r = decodeEngine.createDecodePlan("fake");
  assert(!r.valid);
  assert.strictEqual(r.steps.length, 0);
});

