// =========================================================================
// STAGE 453: Config decode queue manager
// =========================================================================
console.log("\n--- STAGE 453: Config decode queue manager ---");

test("createConfigDecodeQueue — iterates through configs", () => {
  const q = decodeEngine.createConfigDecodeQueue(["128x128-4c", "256x256-4c", "512x512-4c"]);
  assert.strictEqual(q.next(), "128x128-4c");
  assert.strictEqual(q.next(), "256x256-4c");
  assert.strictEqual(q.next(), "512x512-4c");
  assert.strictEqual(q.next(), null);
});

test("createConfigDecodeQueue — remaining count", () => {
  const q = decodeEngine.createConfigDecodeQueue(["a", "b", "c"]);
  assert.strictEqual(q.remaining(), 3);
  q.next();
  assert.strictEqual(q.remaining(), 2);
});

test("createConfigDecodeQueue — recordResult and getResults", () => {
  const q = decodeEngine.createConfigDecodeQueue(["128x128-4c"]);
  q.next();
  q.recordResult("128x128-4c", true);
  const r = q.getResults();
  assert(r["128x128-4c"].success);
});

test("createConfigDecodeQueue — prioritize moves to front", () => {
  const q = decodeEngine.createConfigDecodeQueue(["a", "b", "c"]);
  q.prioritize("c");
  assert.strictEqual(q.next(), "c");
});

test("createConfigDecodeQueue — reset restores queue", () => {
  const q = decodeEngine.createConfigDecodeQueue(["a", "b"]);
  q.next(); q.next();
  assert.strictEqual(q.next(), null);
  q.reset();
  assert.strictEqual(q.next(), "a");
});

test("createConfigDecodeQueue — getTried returns tried configs", () => {
  const q = decodeEngine.createConfigDecodeQueue(["a", "b"]);
  q.next();
  assert.deepStrictEqual(q.getTried(), ["a"]);
});

