test("resolveDecodePriority — sorts by priority", () => {
  const scores = { "128x128-4c": 80, "256x256-4c": 50 };
  const rates = { "256x256-4c": 0.9 };
  const r = decodeEngine.resolveDecodePriority(scores, rates, {});
  assert.strictEqual(r.length, 2);
  assert(r[0].priority >= r[1].priority);
});

test("resolveDecodePriority — failures reduce priority", () => {
  const scores = { a: 50, b: 50 };
  const failures = { b: 5 };
  const r = decodeEngine.resolveDecodePriority(scores, {}, failures);
  const aEntry = r.find(x => x.configName === "a");
  const bEntry = r.find(x => x.configName === "b");
  assert(aEntry.priority > bEntry.priority);
});

test("resolveDecodePriority — empty inputs", () => {
  const r = decodeEngine.resolveDecodePriority();
  assert.strictEqual(r.length, 0);
});

test("resolveDecodePriority — priority clamped 0-100", () => {
  const r = decodeEngine.resolveDecodePriority({ a: 200 }, { a: 1.0 }, {});
  assert(r[0].priority <= 100);
  assert(r[0].priority >= 0);
});

