// STAGE 459: Decode session context
// =========================================================================
console.log("\n--- STAGE 459: Decode session context ---");

test("createDecodeSessionContext — tracks attempts", () => {
  const ctx = decodeEngine.createDecodeSessionContext({ maxAttempts: 3 });
  ctx.addAttempt("128x128-4c", { success: false });
  ctx.addAttempt("256x256-4c", { success: true, confidence: 0.9 });
  assert.strictEqual(ctx.getAttemptCount(), 2);
  assert(ctx.canRetry());
  assert(ctx.getBestResult().configName === "256x256-4c");
});

test("createDecodeSessionContext — canRetry respects maxAttempts", () => {
  const ctx = decodeEngine.createDecodeSessionContext({ maxAttempts: 2 });
  ctx.addAttempt("a", { success: false });
  ctx.addAttempt("b", { success: false });
  assert(!ctx.canRetry());
});

test("createDecodeSessionContext — getSuccessRate", () => {
  const ctx = decodeEngine.createDecodeSessionContext();
  ctx.addAttempt("a", { success: true });
  ctx.addAttempt("b", { success: false });
  assert.strictEqual(ctx.getSuccessRate(), 0.5);
});

test("createDecodeSessionContext — reset clears all", () => {
  const ctx = decodeEngine.createDecodeSessionContext();
  ctx.addAttempt("a", { success: true, confidence: 0.8 });
  ctx.reset();
  assert.strictEqual(ctx.getAttemptCount(), 0);
  assert.strictEqual(ctx.getBestResult(), null);
});

test("createDecodeSessionContext — getAttemptHistory", () => {
  const ctx = decodeEngine.createDecodeSessionContext();
  ctx.addAttempt("128x128-4c", { success: true });
  const h = ctx.getAttemptHistory();
  assert.strictEqual(h.length, 1);
  assert.strictEqual(h[0].config, "128x128-4c");
  assert.strictEqual(h[0].attempt, 1);
});

// =========================================================================
// STAGE 460: Payload autocorrelation profile
// =========================================================================
console.log("\n--- STAGE 460: Payload autocorrelation profile ---");

test("computePayloadAutocorrelationProfile — periodic data shows peak", () => {
  // period-4 pattern
  const arr = [];
  for (let i = 0; i < 64; i++) arr.push([0, 100, 200, 50][i % 4]);
  const buf = Buffer.from(arr);
  const r = decodeEngine.computePayloadAutocorrelationProfile(buf, 8);
  assert(r.lags.length > 0);
  // lag 4 should have high correlation
  const lag4 = r.lags.find(l => l.lag === 4);
  assert(lag4 && lag4.correlation > 0.5, "lag-4 should show strong correlation for period-4 data");
});

test("computePayloadAutocorrelationProfile — constant data zero correlation", () => {
  const buf = Buffer.alloc(32, 50);
  const r = decodeEngine.computePayloadAutocorrelationProfile(buf, 4);
  for (const l of r.lags) assert.strictEqual(l.correlation, 0);
});

test("computePayloadAutocorrelationProfile — default maxLag 16", () => {
  const buf = Buffer.alloc(32, 0);
  buf[0] = 1; // avoid all-same
  const r = decodeEngine.computePayloadAutocorrelationProfile(buf);
  assert(r.lags.length <= 16);
});

test("computePayloadAutocorrelationProfile — throws on non-Buffer", () => {
  let threw = false;
  try { decodeEngine.computePayloadAutocorrelationProfile([1,2]); } catch(e) { threw = true; }
  assert(threw);
});

