// =========================================================================
// STAGE 486: Payload transition entropy
// =========================================================================

test("computePayloadTransitionEntropy — random data has high entropy", () => {
  const buf = Buffer.alloc(1000);
  for (let i = 0; i < buf.length; i++) buf[i] = Math.floor(Math.random() * 256);
  const r = decodeEngine.computePayloadTransitionEntropy(buf);
  assert(r.entropy > 9, "random data should have high transition entropy");
  assert.strictEqual(r.transitionCount, 999);
  assert(r.uniqueTransitions > 500, "should have many unique transitions");
});

test("computePayloadTransitionEntropy — constant data has zero entropy", () => {
  const buf = Buffer.alloc(100, 0x42);
  const r = decodeEngine.computePayloadTransitionEntropy(buf);
  assert.strictEqual(r.entropy, 0);
  assert.strictEqual(r.uniqueTransitions, 1);
});

test("computePayloadTransitionEntropy — short buffer returns zeros", () => {
  const r = decodeEngine.computePayloadTransitionEntropy(Buffer.alloc(1));
  assert.strictEqual(r.entropy, 0);
  assert.strictEqual(r.transitionCount, 0);
});

test("computePayloadTransitionEntropy — alternating pattern", () => {
  const buf = Buffer.alloc(100);
  for (let i = 0; i < 100; i++) buf[i] = i % 2 === 0 ? 0xAA : 0x55;
  const r = decodeEngine.computePayloadTransitionEntropy(buf);
  assert.strictEqual(r.uniqueTransitions, 2);
  assert(r.entropy > 0.9 && r.entropy < 1.1, "two transitions => ~1 bit entropy");
});

