test("computePayloadByteBalance — balanced random data", () => {
  const buf = Buffer.alloc(1000);
  for (let i = 0; i < 1000; i++) buf[i] = Math.floor(Math.random() * 256);
  const r = decodeEngine.computePayloadByteBalance(buf);
  assert(r.ratio > 0.35 && r.ratio < 0.65, "random data should be roughly balanced");
  assert.strictEqual(r.highCount + r.lowCount, 1000);
  assert.strictEqual(r.isBalanced, r.ratio >= 0.4 && r.ratio <= 0.6);
});

test("computePayloadByteBalance — all high bytes", () => {
  const buf = Buffer.alloc(50, 0xFF);
  const r = decodeEngine.computePayloadByteBalance(buf);
  assert.strictEqual(r.highCount, 50);
  assert.strictEqual(r.lowCount, 0);
  assert.strictEqual(r.ratio, 1);
  assert.strictEqual(r.isBalanced, false);
});

test("computePayloadByteBalance — all low bytes", () => {
  const buf = Buffer.alloc(50, 0x00);
  const r = decodeEngine.computePayloadByteBalance(buf);
  assert.strictEqual(r.highCount, 0);
  assert.strictEqual(r.lowCount, 50);
  assert.strictEqual(r.ratio, 0);
  assert.strictEqual(r.isBalanced, false);
});

test("computePayloadByteBalance — empty buffer", () => {
  const r = decodeEngine.computePayloadByteBalance(Buffer.alloc(0));
  assert.strictEqual(r.ratio, 0);
  assert.strictEqual(r.isBalanced, true);
});

