// =========================================================================
// STAGE 528: Payload byte CDF
// =========================================================================

test("computePayloadByteCDF — uniform data CDF is linear", () => {
  const buf = Buffer.alloc(256);
  for (let i = 0; i < 256; i++) buf[i] = i;
  const r = decodeEngine.computePayloadByteCDF(buf);
  assert(Math.abs(r.cdf[127] - 128/256) < 0.01, "CDF at 127 should be ~0.5");
  assert(Math.abs(r.cdf[255] - 1) < 0.001, "CDF at 255 should be 1");
});

test("computePayloadByteCDF — constant data step function", () => {
  const buf = Buffer.alloc(100, 50);
  const r = decodeEngine.computePayloadByteCDF(buf);
  assert.strictEqual(r.cdf[50], 1);
  assert.strictEqual(r.cdf[49], 0);
  assert.strictEqual(r.median, 50);
});

test("computePayloadByteCDF — empty buffer", () => {
  const r = decodeEngine.computePayloadByteCDF(Buffer.alloc(0));
  assert.strictEqual(r.median, 0);
});

test("computePayloadByteCDF — CDF is monotonically increasing", () => {
  const buf = Buffer.alloc(500);
  for (let i = 0; i < 500; i++) buf[i] = Math.floor(Math.random() * 256);
  const r = decodeEngine.computePayloadByteCDF(buf);
  for (let i = 1; i < 256; i++) assert(r.cdf[i] >= r.cdf[i-1], "CDF must be monotonic");
});

