test("createConfigRoundRobinScheduler — cycles through configs", () => {
  const sched = decodeEngine.createConfigRoundRobinScheduler(["a", "b", "c"]);
  assert.strictEqual(sched.next().configName, "a");
  assert.strictEqual(sched.next().configName, "b");
  assert.strictEqual(sched.next().configName, "c");
  assert.strictEqual(sched.next().configName, "a");
  assert.strictEqual(sched.totalDispatched(), 4);
});

test("createConfigRoundRobinScheduler — getCounts tracks usage", () => {
  const sched = decodeEngine.createConfigRoundRobinScheduler(["x", "y"]);
  sched.next(); sched.next(); sched.next();
  const counts = sched.getCounts();
  assert.strictEqual(counts["x"], 2);
  assert.strictEqual(counts["y"], 1);
});

test("createConfigRoundRobinScheduler — reset works", () => {
  const sched = decodeEngine.createConfigRoundRobinScheduler(["a"]);
  sched.next(); sched.next();
  sched.reset();
  assert.strictEqual(sched.totalDispatched(), 0);
  assert.strictEqual(sched.getCounts()["a"], 0);
});

