test("createDecodeResultLruCache — basic get/put", () => {
  const cache = decodeEngine.createDecodeResultLruCache(5);
  cache.put("a", { data: 1 });
  assert.strictEqual(cache.size(), 1);
  assert(cache.has("a"));
  assert.deepStrictEqual(cache.get("a"), { data: 1 });
});

test("createDecodeResultLruCache — evicts oldest", () => {
  const cache = decodeEngine.createDecodeResultLruCache(3);
  cache.put("a", 1); cache.put("b", 2); cache.put("c", 3);
  cache.put("d", 4); // should evict "a"
  assert.strictEqual(cache.has("a"), false);
  assert.strictEqual(cache.size(), 3);
});

test("createDecodeResultLruCache — get refreshes order", () => {
  const cache = decodeEngine.createDecodeResultLruCache(3);
  cache.put("a", 1); cache.put("b", 2); cache.put("c", 3);
  cache.get("a"); // refresh "a"
  cache.put("d", 4); // should evict "b" not "a"
  assert.strictEqual(cache.has("a"), true);
  assert.strictEqual(cache.has("b"), false);
});

test("createDecodeResultLruCache — clear empties cache", () => {
  const cache = decodeEngine.createDecodeResultLruCache(5);
  cache.put("x", 1); cache.put("y", 2);
  cache.clear();
  assert.strictEqual(cache.size(), 0);
});

test("createDecodeResultLruCache — miss returns null", () => {
  const cache = decodeEngine.createDecodeResultLruCache(5);
  assert.strictEqual(cache.get("missing"), null);
});

