test("createConfigDecodeRetryPolicy — default max retries 3", () => {
  const p = decodeEngine.createConfigDecodeRetryPolicy();
  assertEq(p.maxRetries, 3);
  assertEq(p.attempt(), 0);
  assert(p.shouldRetry());
});

test("createConfigDecodeRetryPolicy — exhausts retries", () => {
  const p = decodeEngine.createConfigDecodeRetryPolicy({ maxRetries: 2 });
  p.nextDelay(); p.nextDelay();
  assert(!p.shouldRetry());
});

test("createConfigDecodeRetryPolicy — delays increase", () => {
  const p = decodeEngine.createConfigDecodeRetryPolicy({ maxRetries: 5, baseDelayMs: 100, maxDelayMs: 10000 });
  const d1 = p.nextDelay(); const d2 = p.nextDelay();
  // d2 should generally be larger (exponential), but jitter means we check base relationship
  assert(d1 >= 100, "first delay >= base");
  assert(d2 >= 100, "second delay >= base");
});

test("createConfigDecodeRetryPolicy — reset restores attempts", () => {
  const p = decodeEngine.createConfigDecodeRetryPolicy({ maxRetries: 1 });
  p.nextDelay();
  assert(!p.shouldRetry());
  p.reset();
  assert(p.shouldRetry());
  assertEq(p.attempt(), 0);
});

