// STAGE 548: Payload frequency rank correlation
// =========================================================================

test("computePayloadFrequencyRankCorrelation — identical payloads = 1", () => {
  const p = new Uint8Array(200);
  for (let i = 0; i < 200; i++) p[i] = i % 50;
  const r = decodeEngine.computePayloadFrequencyRankCorrelation(p, p);
  assertNear(r, 1.0, 0.001);
});

test("computePayloadFrequencyRankCorrelation — inversely ranked distributions", () => {
  // a: bytes 0..255 with freq proportional to i (low bytes rare, high bytes common)
  const aBuf = [];
  for (let i = 0; i < 256; i++) for (let j = 0; j <= i; j++) aBuf.push(i);
  const a = new Uint8Array(aBuf);
  // b: inverse — byte 0 most common, byte 255 rarest
  const bBuf = [];
  for (let i = 0; i < 256; i++) for (let j = 0; j <= (255 - i); j++) bBuf.push(i);
  const b = new Uint8Array(bBuf);
  const r = decodeEngine.computePayloadFrequencyRankCorrelation(a, b);
  assert(r < -0.9, "inversely ranked should have strong negative correlation, got " + r);
});

test("computePayloadFrequencyRankCorrelation — empty returns 0", () => {
  assertEq(decodeEngine.computePayloadFrequencyRankCorrelation(new Uint8Array([]), new Uint8Array([1])), 0);
});

