// =========================================================================
// STAGE 559: Config decode watchdog
// =========================================================================

test("createConfigDecodeWatchdog — not expired initially", () => {
  const w = decodeEngine.createConfigDecodeWatchdog(5000);
  w.start();
  assert(!w.isExpired());
  assertEq(w.timeout(), 5000);
});

test("createConfigDecodeWatchdog — check triggers once", () => {
  const w = decodeEngine.createConfigDecodeWatchdog(1); // 1ms timeout
  w.start();
  // Spin briefly to ensure timeout
  const end = Date.now() + 5;
  while (Date.now() < end) {}
  assert(w.check() === true, "first check should trigger");
  assert(w.check() === false, "second check should not re-trigger");
  assert(w.wasTriggered());
});

test("createConfigDecodeWatchdog — reset clears state", () => {
  const w = decodeEngine.createConfigDecodeWatchdog(5000);
  w.start();
  w.reset();
  assertEq(w.elapsed(), 0);
  assert(!w.wasTriggered());
});

