test("computePayloadByteConditionalEntropy — constant payload has 0 conditional entropy", () => {
  const p = new Uint8Array(100).fill(7);
  assertNear(decodeEngine.computePayloadByteConditionalEntropy(p), 0, 0.001);
});

test("computePayloadByteConditionalEntropy — varied data has positive conditional entropy", () => {
  // Use a non-bijective pattern so conditional entropy is nonzero
  const p = new Uint8Array(2000);
  let s = 1;
  for (let i = 0; i < 2000; i++) { s = (s * 1103515245 + 12345) & 0x7fffffff; p[i] = (s >> 16) & 0xFF; }
  const h = decodeEngine.computePayloadByteConditionalEntropy(p);
  assert(h > 3, "LCG-generated data should have positive conditional entropy, got " + h);
});

test("computePayloadByteConditionalEntropy — empty returns 0", () => {
  assertEq(decodeEngine.computePayloadByteConditionalEntropy(new Uint8Array([])), 0);
});

