test("createDecodeResultFingerprintIndex — add and lookup", () => {
  const idx = decodeEngine.createDecodeResultFingerprintIndex();
  const r1 = { payload: new Uint8Array([1, 2, 3, 4, 5]) };
  idx.add(r1);
  const found = idx.lookup(r1);
  assertEq(found.length, 1);
  assert.deepStrictEqual(found[0], r1);
});

test("createDecodeResultFingerprintIndex — different payloads have different fingerprints", () => {
  const idx = decodeEngine.createDecodeResultFingerprintIndex();
  const r1 = { payload: new Uint8Array([1, 2, 3]) };
  const r2 = { payload: new Uint8Array([4, 5, 6]) };
  const fp1 = idx.add(r1);
  const fp2 = idx.add(r2);
  assert(fp1 !== fp2, "fingerprints should differ");
  assertEq(idx.count(), 2);
  assertEq(idx.totalResults(), 2);
});

test("createDecodeResultFingerprintIndex — same fingerprint groups together", () => {
  const idx = decodeEngine.createDecodeResultFingerprintIndex();
  const r1 = { payload: new Uint8Array([1, 2, 3]), confidence: 0.5 };
  const r2 = { payload: new Uint8Array([1, 2, 3]), confidence: 0.9 };
  idx.add(r1); idx.add(r2);
  assertEq(idx.count(), 1); // same fingerprint bucket
  assertEq(idx.totalResults(), 2);
});

test("createDecodeResultFingerprintIndex — clear resets", () => {
  const idx = decodeEngine.createDecodeResultFingerprintIndex();
  idx.add({ payload: new Uint8Array([1]) });
  idx.clear();
  assertEq(idx.count(), 0);
});

