// =========================================================================
// STAGE 600: Payload byte burstiness
// =========================================================================

test("computePayloadByteBurstiness — evenly spaced has low burstiness", () => {
  const p = new Uint8Array(40);
  for (let i = 0; i < 40; i++) p[i] = i % 4 === 0 ? 1 : 0;
  const r = decodeEngine.computePayloadByteBurstiness(p, 1);
  assertNear(r.meanGap, 4, 0.1);
  assert(r.burstiness <= 0.1, "regular spacing should have low burstiness, got " + r.burstiness);
});

test("computePayloadByteBurstiness — clustered has high burstiness", () => {
  // Byte 1 appears in a burst then long gap
  const p = new Uint8Array(100).fill(0);
  p[0] = 1; p[1] = 1; p[2] = 1; p[3] = 1; p[90] = 1;
  const r = decodeEngine.computePayloadByteBurstiness(p, 1);
  assert(r.burstiness > 0.1, "bursty pattern should have positive burstiness, got " + r.burstiness);
});

test("computePayloadByteBurstiness — empty returns zeros", () => {
  const r = decodeEngine.computePayloadByteBurstiness(new Uint8Array([]), 0);
  assertEq(r.burstiness, 0);
});

