// =========================================================================

test("buildDecodeResultDiffReport — identical results", () => {
  const r = { confidence: 0.9, payload: new Uint8Array([1, 2, 3]) };
  const d = decodeEngine.buildDecodeResultDiffReport(r, r);
  assert(d.identical);
  assertEq(d.byteDiffs, 0);
  assertNear(d.confidenceDelta, 0, 0.001);
});

test("buildDecodeResultDiffReport — different payloads", () => {
  const a = { confidence: 0.8, payload: new Uint8Array([1, 2, 3]) };
  const b = { confidence: 0.9, payload: new Uint8Array([1, 9, 3]) };
  const d = decodeEngine.buildDecodeResultDiffReport(a, b);
  assert(!d.identical);
  assertEq(d.byteDiffs, 1);
  assertNear(d.confidenceDelta, 0.1, 0.001);
});

test("buildDecodeResultDiffReport — different lengths", () => {
  const a = { payload: new Uint8Array([1, 2]) };
  const b = { payload: new Uint8Array([1, 2, 3, 4]) };
  const d = decodeEngine.buildDecodeResultDiffReport(a, b);
  assertEq(d.payloadLengthDelta, 2);
});

