// =========================================================================
// STAGE 603: Config decode backoff strategy
// =========================================================================

test("createConfigDecodeBackoffStrategy — exponential doubles", () => {
  const bo = decodeEngine.createConfigDecodeBackoffStrategy("exponential", 100);
  assertEq(bo.next(), 100);  // 100*2^0
  assertEq(bo.next(), 200);  // 100*2^1
  assertEq(bo.next(), 400);  // 100*2^2
});

test("createConfigDecodeBackoffStrategy — linear increments", () => {
  const bo = decodeEngine.createConfigDecodeBackoffStrategy("linear", 50);
  assertEq(bo.next(), 50);   // 50*1
  assertEq(bo.next(), 100);  // 50*2
  assertEq(bo.next(), 150);  // 50*3
});

test("createConfigDecodeBackoffStrategy — fibonacci grows", () => {
  const bo = decodeEngine.createConfigDecodeBackoffStrategy("fibonacci", 10);
  assertEq(bo.next(), 10);   // fib(1)*10
  assertEq(bo.next(), 10);   // fib(1)*10
  assertEq(bo.next(), 20);   // fib(2)*10
  assertEq(bo.next(), 30);   // fib(3)*10
});

test("createConfigDecodeBackoffStrategy — reset restarts", () => {
  const bo = decodeEngine.createConfigDecodeBackoffStrategy("exponential", 100);
  bo.next(); bo.next();
  bo.reset();
  assertEq(bo.next(), 100);
  assertEq(bo.attempt(), 1);
});

