test("createDecodeResultStreamProcessor — feed and count", () => {
  const sp = decodeEngine.createDecodeResultStreamProcessor();
  sp.feed({ confidence: 0.5 }); sp.feed({ confidence: 0.9 });
  assertEq(sp.count(), 2);
});

test("createDecodeResultStreamProcessor — filter and map chain", () => {
  const sp = decodeEngine.createDecodeResultStreamProcessor();
  sp.feedMany([{ confidence: 0.3 }, { confidence: 0.8 }, { confidence: 0.6 }]);
  sp.filter(r => r.confidence >= 0.5).map(r => ({ ...r, quality: "high" }));
  assertEq(sp.count(), 2);
  assert(sp.toArray()[0].quality === "high");
});

test("createDecodeResultStreamProcessor — reduce", () => {
  const sp = decodeEngine.createDecodeResultStreamProcessor();
  sp.feedMany([{ confidence: 0.2 }, { confidence: 0.4 }, { confidence: 0.6 }]);
  const sum = sp.reduce((acc, r) => acc + r.confidence, 0);
  assertNear(sum, 1.2, 0.001);
});

test("createDecodeResultStreamProcessor — clear", () => {
  const sp = decodeEngine.createDecodeResultStreamProcessor();
  sp.feed({}); sp.clear();
  assertEq(sp.count(), 0);
});

