test("computePayloadByteEntropyRate — longer payload has lower rate", () => {
  const short = new Uint8Array(10); for (let i = 0; i < 10; i++) short[i] = i;
  const long = new Uint8Array(100); for (let i = 0; i < 100; i++) long[i] = i % 10;
  const rShort = decodeEngine.computePayloadByteEntropyRate(short);
  const rLong = decodeEngine.computePayloadByteEntropyRate(long);
  assert(rShort > rLong, "shorter payload should have higher entropy rate");
});

