// =========================================================================
// STAGE 607: Config decode quorum
// =========================================================================

test("createConfigDecodeQuorum — reaches quorum on agreement", () => {
  const q = decodeEngine.createConfigDecodeQuorum(3);
  const r = { payload: new Uint8Array([1, 2, 3]) };
  assert(!q.submit(r)); assert(!q.submit(r));
  assert(q.submit(r)); // 3rd vote reaches quorum
  assert(q.hasQuorum());
});

test("createConfigDecodeQuorum — different results don't reach quorum", () => {
  const q = decodeEngine.createConfigDecodeQuorum(2);
  q.submit({ payload: new Uint8Array([1]) });
  q.submit({ payload: new Uint8Array([2]) });
  q.submit({ payload: new Uint8Array([3]) });
  assert(!q.hasQuorum());
  assertEq(q.distinctResults(), 3);
});

test("createConfigDecodeQuorum — reset clears", () => {
  const q = decodeEngine.createConfigDecodeQuorum(1);
  q.submit({ payload: new Uint8Array([1]) });
  q.reset();
  assertEq(q.maxVotes(), 0);
});

