test("computePayloadByteGlobalAutocorrelation — constant is zero", () => {
  assertNear(decodeEngine.computePayloadByteGlobalAutocorrelation(new Uint8Array(50).fill(7), 5), 0, 0.001);
});

test("computePayloadByteGlobalAutocorrelation — smooth signal has positive AC", () => {
  // Slowly varying signal — adjacent values are correlated
  const p = new Uint8Array(200);
  for (let i = 0; i < 200; i++) p[i] = Math.round(128 + 100 * Math.sin(i * 0.1));
  const ac = decodeEngine.computePayloadByteGlobalAutocorrelation(p, 5);
  assert(ac > 0, "smooth signal should have positive avg autocorrelation, got " + ac);
});

test("computePayloadByteGlobalAutocorrelation — empty returns 0", () => {
  assertEq(decodeEngine.computePayloadByteGlobalAutocorrelation(new Uint8Array([]), 5), 0);
});

