// =========================================================================
// STAGE 623: Config decode garbage collector
// =========================================================================

test("createConfigDecodeGarbageCollector — registers and collects stale", () => {
  const gc = decodeEngine.createConfigDecodeGarbageCollector(1); // 1ms stale
  gc.register("s1"); gc.register("s2");
  assertEq(gc.activeCount(), 2);
  // Spin briefly
  const end = Date.now() + 5;
  while (Date.now() < end) {}
  const stale = gc.collectStale();
  assertEq(stale.length, 2);
  assertEq(gc.activeCount(), 0);
});

test("createConfigDecodeGarbageCollector — touch keeps alive", () => {
  const gc = decodeEngine.createConfigDecodeGarbageCollector(100000);
  gc.register("s1");
  gc.touch("s1");
  assert(!gc.isStale("s1"));
});

test("createConfigDecodeGarbageCollector — clear", () => {
  const gc = decodeEngine.createConfigDecodeGarbageCollector(1000);
  gc.register("x"); gc.clear();
  assertEq(gc.activeCount(), 0);
});

