// =========================================================================
// STAGE 631: Config decode permit system
// =========================================================================

test("createConfigDecodePermitSystem — acquire and release", () => {
  const ps = decodeEngine.createConfigDecodePermitSystem(3);
  assert(ps.acquire("a")); assert(ps.acquire("b")); assert(ps.acquire("c"));
  assert(!ps.acquire("d")); // exhausted
  assertEq(ps.available(), 0);
  ps.release("a");
  assertEq(ps.available(), 1);
  assert(ps.acquire("d"));
});

test("createConfigDecodePermitSystem — isHolder", () => {
  const ps = decodeEngine.createConfigDecodePermitSystem(5);
  ps.acquire("x");
  assert(ps.isHolder("x"));
  ps.release("x");
  assert(!ps.isHolder("x"));
});

test("createConfigDecodePermitSystem — reset", () => {
  const ps = decodeEngine.createConfigDecodePermitSystem(2);
  ps.acquire("a"); ps.acquire("b");
  ps.reset();
  assertEq(ps.issued(), 0);
  assertEq(ps.available(), 2);
});

