test("computePayloadByteSignalToNoiseEstimate — high mean low variance = high SNR", () => {
  const p = new Uint8Array(100).fill(200);
  p[50] = 201; // tiny noise
  const r = decodeEngine.computePayloadByteSignalToNoiseEstimate(p);
  assert(r.snr > 30, "constant-ish high signal should have high SNR, got " + r.snr);
});

test("computePayloadByteSignalToNoiseEstimate — noisy has lower SNR", () => {
  const p = new Uint8Array(200);
  for (let i = 0; i < 200; i++) p[i] = i % 2 === 0 ? 200 : 50;
  const r = decodeEngine.computePayloadByteSignalToNoiseEstimate(p);
  assert(r.snr < 20, "alternating signal should have moderate SNR");
});

test("computePayloadByteSignalToNoiseEstimate — empty", () => {
  assertEq(decodeEngine.computePayloadByteSignalToNoiseEstimate(new Uint8Array([])).snr, 0);
});

