// =========================================================================
// STAGE 654 — computePayloadByteKurtosis
// =========================================================================
test("computePayloadByteKurtosis — uniform distribution is platykurtic", () => {
  const p = Buffer.alloc(256);
  for (let i = 0; i < 256; i++) p[i] = i;
  const r = decodeEngine.computePayloadByteKurtosis(p);
  assert(r.kurtosis < 0, "uniform should have negative excess kurtosis");
  assertEq(r.interpretation, "platykurtic");
});

test("computePayloadByteKurtosis — spike distribution is leptokurtic", () => {
  const p = Buffer.alloc(200);
  p.fill(128);
  p[0] = 0; p[1] = 255;
  const r = decodeEngine.computePayloadByteKurtosis(p);
  assert(r.kurtosis > 1, "spike should be leptokurtic, got " + r.kurtosis);
  assertEq(r.interpretation, "leptokurtic");
});

test("computePayloadByteKurtosis — insufficient data", () => {
  const r = decodeEngine.computePayloadByteKurtosis(Buffer.from([1, 2]));
  assertEq(r.interpretation, "insufficient_data");
});

