test("computePayloadByteSkewness — symmetric distribution", () => {
  const p = Buffer.alloc(256);
  for (let i = 0; i < 256; i++) p[i] = i;
  const r = decodeEngine.computePayloadByteSkewness(p);
  assertNear(r.skewness, 0, 0.1);
  assertEq(r.interpretation, "approximately_symmetric");
});

test("computePayloadByteSkewness — right-skewed distribution", () => {
  // Mostly small values with a few large outliers
  const p = Buffer.alloc(200);
  for (let i = 0; i < 180; i++) p[i] = Math.floor(Math.random() * 30);
  for (let i = 180; i < 200; i++) p[i] = 200 + Math.floor(Math.random() * 55);
  const r = decodeEngine.computePayloadByteSkewness(p);
  assert(r.skewness > 0.5, "should be right-skewed, got " + r.skewness);
  assertEq(r.interpretation, "right_skewed");
});

test("computePayloadByteSkewness — insufficient data", () => {
  const r = decodeEngine.computePayloadByteSkewness(Buffer.from([5]));
  assertEq(r.interpretation, "insufficient_data");
});

