// STAGE 659 — createConfigDecodePriorityScheduler
// =========================================================================
test("createConfigDecodePriorityScheduler — highest priority dequeues first", () => {
  const sched = decodeEngine.createConfigDecodePriorityScheduler();
  sched.enqueue("low", 1, { action: "low" });
  sched.enqueue("high", 10, { action: "high" });
  sched.enqueue("mid", 5, { action: "mid" });
  const first = sched.dequeue();
  assertEq(first.priority, 10);
  assertEq(first.configName, "high");
});

test("createConfigDecodePriorityScheduler — size and pending", () => {
  const sched = decodeEngine.createConfigDecodePriorityScheduler();
  sched.enqueue("a", 1, {}); sched.enqueue("a", 2, {}); sched.enqueue("b", 3, {});
  assertEq(sched.size(), 3);
  assertEq(sched.pending("a"), 2);
  assertEq(sched.pending("b"), 1);
});

test("createConfigDecodePriorityScheduler — drain empties queue", () => {
  const sched = decodeEngine.createConfigDecodePriorityScheduler();
  sched.enqueue("x", 1, {}); sched.enqueue("y", 2, {});
  const all = sched.drain();
  assertEq(all.length, 2);
  assertEq(sched.size(), 0);
});

