test("createDecodeResultReplayBuffer — push and latest", () => {
  const rb = decodeEngine.createDecodeResultReplayBuffer(5);
  rb.push({ id: 1 }); rb.push({ id: 2 }); rb.push({ id: 3 });
  const latest = rb.latest(2);
  assertEq(latest.length, 2);
  assertEq(latest[0].result.id, 3);
  assertEq(latest[1].result.id, 2);
});

test("createDecodeResultReplayBuffer — circular overwrite", () => {
  const rb = decodeEngine.createDecodeResultReplayBuffer(3);
  for (let i = 0; i < 5; i++) rb.push({ id: i });
  assertEq(rb.size(), 3);
  assertEq(rb.isFull(), true);
  assertEq(rb.totalAdded(), 5);
  const latest = rb.latest(1);
  assertEq(latest[0].result.id, 4);
});

test("createDecodeResultReplayBuffer — toArray preserves order", () => {
  const rb = decodeEngine.createDecodeResultReplayBuffer(4);
  rb.push({ id: "a" }); rb.push({ id: "b" }); rb.push({ id: "c" });
  const arr = rb.toArray();
  assertEq(arr.length, 3);
  assertEq(arr[0].result.id, "a");
});

