// STAGE 663 — createConfigDecodeCircuitBreaker
// =========================================================================
test("createConfigDecodeCircuitBreaker — opens after threshold failures", () => {
  const cb = decodeEngine.createConfigDecodeCircuitBreaker(3, 100000);
  assertEq(cb.state("cfg1"), "closed");
  cb.recordFailure("cfg1"); cb.recordFailure("cfg1"); cb.recordFailure("cfg1");
  assertEq(cb.state("cfg1"), "open");
  assertEq(cb.canAttempt("cfg1"), false);
});

test("createConfigDecodeCircuitBreaker — success resets failures", () => {
  const cb = decodeEngine.createConfigDecodeCircuitBreaker(3, 100000);
  cb.recordFailure("cfg1"); cb.recordFailure("cfg1");
  cb.recordSuccess("cfg1");
  assertEq(cb.failures("cfg1"), 0);
  assertEq(cb.state("cfg1"), "closed");
});

test("createConfigDecodeCircuitBreaker — reset clears state", () => {
  const cb = decodeEngine.createConfigDecodeCircuitBreaker(2, 100000);
  cb.recordFailure("a"); cb.recordFailure("a");
  assertEq(cb.state("a"), "open");
  cb.reset("a");
  assertEq(cb.state("a"), "closed");
  assert(cb.canAttempt("a"), "should be able to attempt after reset");
});

