test("computePayloadByteTransitionMatrix — simple sequence", () => {
  const p = Buffer.from([0, 1, 2, 3, 0, 1]);
  const r = decodeEngine.computePayloadByteTransitionMatrix(p);
  assert(r.transitions === 5, "should have 5 transitions");
  assert(r.buckets > 0, "should have buckets");
  // 0 -> 1 happens twice out of two 0-outgoing transitions
  assertEq(r.matrix["0"]["1"], 1.0);
});

test("computePayloadByteTransitionMatrix — bucketed", () => {
  const p = Buffer.from([0, 128, 255, 64]);
  const r = decodeEngine.computePayloadByteTransitionMatrix(p, 128);
  // bucket 0->1, 1->1, 0->0 (64 is bucket 0)
  assert(r.buckets <= 3, "should have few buckets");
  assert(r.transitions === 3);
});

test("computePayloadByteTransitionMatrix — single byte", () => {
  const r = decodeEngine.computePayloadByteTransitionMatrix(Buffer.from([42]));
  assertEq(r.transitions, 0);
});

