// =========================================================================
// STAGE 670 — computePayloadByteAutocorrelationSpectrum
// =========================================================================
test("computePayloadByteAutocorrelationSpectrum — periodic signal", () => {
  // Square wave with period 20 — sharp transitions reduce lag-1 correlation
  const p = Buffer.alloc(200);
  for (let i = 0; i < 200; i++) p[i] = (Math.floor(i / 10) % 2 === 0) ? 200 : 50;
  const r = decodeEngine.computePayloadByteAutocorrelationSpectrum(p, 30);
  // Lag 20 should be the peak (full period)
  assert(r.lags.length >= 20, "should have enough lags");
  // The AC at lag 20 (index 19) should be strongly positive
  assert(r.lags[19] > 0.5, "lag-20 AC should be strong, got " + r.lags[19]);
});

test("computePayloadByteAutocorrelationSpectrum — random signal low AC", () => {
  const p = Buffer.alloc(200);
  let s = 42;
  for (let i = 0; i < 200; i++) { s = (s * 1103515245 + 12345) & 0x7fffffff; p[i] = (s >> 16) & 0xFF; }
  const r = decodeEngine.computePayloadByteAutocorrelationSpectrum(p, 20);
  assert(Math.abs(r.peakAC) < 0.3, "random should have low AC, got " + r.peakAC);
});

test("computePayloadByteAutocorrelationSpectrum — constant gives zero", () => {
  const p = Buffer.alloc(50); p.fill(42);
  const r = decodeEngine.computePayloadByteAutocorrelationSpectrum(p, 10);
  assertEq(r.peakAC, 0);
});

