test("createDecodeResultMerger — union strategy", () => {
  const m = decodeEngine.createDecodeResultMerger("union");
  m.addPartial({ a: 1, b: 2 });
  m.addPartial({ c: 3, a: 999 }); // a should keep first value in union
  const merged = m.merge();
  assertEq(merged.a, 1);
  assertEq(merged.c, 3);
  assertEq(merged._partialCount, 2);
});

test("createDecodeResultMerger — latest strategy overwrites", () => {
  const m = decodeEngine.createDecodeResultMerger("latest");
  m.addPartial({ a: 1, b: 2 });
  m.addPartial({ a: 999 });
  const merged = m.merge();
  assertEq(merged.a, 999);
  assertEq(merged.b, 2);
});

test("createDecodeResultMerger — single partial returns copy", () => {
  const m = decodeEngine.createDecodeResultMerger();
  m.addPartial({ x: 42 });
  const merged = m.merge();
  assertEq(merged.x, 42);
});

