// STAGE 674 — computePayloadByteEntropyRate
// =========================================================================
test("computePayloadByteEntropyRate — pseudorandom has positive rate", () => {
  const p = Buffer.alloc(1000);
  let s = 12345;
  for (let i = 0; i < 1000; i++) { s = (s * 1103515245 + 12345) & 0x7fffffff; p[i] = (s >> 16) & 0xFF; }
  const r = decodeEngine.computePayloadByteEntropyRate(p);
  assert(r.entropyRate > 0, "should have positive entropy rate, got " + r.entropyRate);
  assert(r.marginalEntropy > 5, "marginal entropy should be high for spread values");
});

test("computePayloadByteEntropyRate — repeating pattern has redundancy", () => {
  const p = Buffer.alloc(500);
  for (let i = 0; i < 500; i++) p[i] = i % 4; // 0,1,2,3,0,1,2,3...
  const r = decodeEngine.computePayloadByteEntropyRate(p);
  assert(r.redundancy > 0, "repeating should have some redundancy");
  assert(r.marginalEntropy > 0, "should have positive marginal entropy");
});

test("computePayloadByteEntropyRate — constant has zero rate", () => {
  const p = Buffer.alloc(100); p.fill(42);
  const r = decodeEngine.computePayloadByteEntropyRate(p);
  assertEq(r.entropyRate, 0);
  assertEq(r.marginalEntropy, 0);
});

