test("computePayloadByteDifferentialEntropy — constant payload zero entropy", () => {
  const p = Buffer.alloc(100); p.fill(42);
  const r = decodeEngine.computePayloadByteDifferentialEntropy(p);
  assertEq(r.entropy, 0);
  assertEq(r.meanDiff, 0);
  assertEq(r.uniqueDiffs, 1);
});

test("computePayloadByteDifferentialEntropy — varying payload positive entropy", () => {
  const p = Buffer.alloc(200);
  let s = 99;
  for (let i = 0; i < 200; i++) { s = (s * 1103515245 + 12345) & 0x7fffffff; p[i] = (s >> 16) & 0xFF; }
  const r = decodeEngine.computePayloadByteDifferentialEntropy(p);
  assert(r.entropy > 2, "should have positive entropy, got " + r.entropy);
  assert(r.uniqueDiffs > 10, "should have many unique diffs");
});

test("computePayloadByteDifferentialEntropy — single byte", () => {
  const r = decodeEngine.computePayloadByteDifferentialEntropy(Buffer.from([5]));
  assertEq(r.entropy, 0);
});

