// =========================================================================
// STAGE 691 — createConfigDecodeRetryPolicy
// =========================================================================
test("createConfigDecodeRetryPolicy — retries with backoff", () => {
  const rp = decodeEngine.createConfigDecodeRetryPolicy(3, 100);
  assert(rp.shouldRetry("cfg1"), "should allow retry initially");
  rp.recordAttempt("cfg1");
  assertEq(rp.backoff("cfg1"), 200); // 100 * 2^1
  rp.recordAttempt("cfg1"); rp.recordAttempt("cfg1");
  assertEq(rp.shouldRetry("cfg1"), false);
  assertEq(rp.isExhausted("cfg1"), true);
});

test("createConfigDecodeRetryPolicy — reset allows retries again", () => {
  const rp = decodeEngine.createConfigDecodeRetryPolicy(1, 50);
  rp.recordAttempt("x");
  assertEq(rp.shouldRetry("x"), false);
  rp.reset("x");
  assert(rp.shouldRetry("x"), "should allow after reset");
});

test("createConfigDecodeRetryPolicy — independent per config", () => {
  const rp = decodeEngine.createConfigDecodeRetryPolicy(2, 100);
  rp.recordAttempt("a"); rp.recordAttempt("a");
  assertEq(rp.shouldRetry("a"), false);
  assert(rp.shouldRetry("b"), "b should be independent");
});

