// =========================================================================
// STAGE 699 — createConfigDecodeWarmupScheduler
// =========================================================================
test("createConfigDecodeWarmupScheduler — ramps up capacity", () => {
  const ws = decodeEngine.createConfigDecodeWarmupScheduler(5);
  assertEq(ws.capacity("cfg1"), 0); // step 0/5 = 0
  ws.advance("cfg1"); // step 1/5 = 0.2
  assertNear(ws.capacity("cfg1"), 0.2, 0.01);
  ws.advance("cfg1"); ws.advance("cfg1"); ws.advance("cfg1"); ws.advance("cfg1");
  assertEq(ws.isWarmedUp("cfg1"), true);
  assertEq(ws.capacity("cfg1"), 1.0);
});

test("createConfigDecodeWarmupScheduler — reset restarts warmup", () => {
  const ws = decodeEngine.createConfigDecodeWarmupScheduler(3);
  ws.advance("x"); ws.advance("x"); ws.advance("x");
  assert(ws.isWarmedUp("x"));
  ws.reset("x");
  assertEq(ws.isWarmedUp("x"), false);
});

test("createConfigDecodeWarmupScheduler — step tracking", () => {
  const ws = decodeEngine.createConfigDecodeWarmupScheduler(10);
  assertEq(ws.step("new"), 0);
  ws.advance("new");
  assertEq(ws.step("new"), 1);
});

