// =========================================================================
// STAGE 713 — createDecodeResultStreamProcessor
// =========================================================================
test("createDecodeResultStreamProcessor — windowed aggregation", () => {
  const sp = decodeEngine.createDecodeResultStreamProcessor(5);
  sp.addAggregator("avgConf", (win) => {
    let sum = 0;
    for (const r of win) sum += r.confidence;
    return win.length > 0 ? sum / win.length : 0;
  });
  for (let i = 0; i < 5; i++) sp.push({ confidence: 0.8 });
  const agg = sp.aggregate();
  assertNear(agg.avgConf, 0.8, 0.01);
  assert(sp.isFull());
});

test("createDecodeResultStreamProcessor — window slides", () => {
  const sp = decodeEngine.createDecodeResultStreamProcessor(3);
  sp.push({ v: 1 }); sp.push({ v: 2 }); sp.push({ v: 3 }); sp.push({ v: 4 });
  const win = sp.currentWindow();
  assertEq(win.length, 3);
  assertEq(win[0].v, 2);
  assertEq(sp.totalProcessed(), 4);
});

test("createDecodeResultStreamProcessor — clear resets", () => {
  const sp = decodeEngine.createDecodeResultStreamProcessor(5);
  sp.push({}); sp.push({});
  sp.clear();
  assertEq(sp.totalProcessed(), 0);
  assertEq(sp.currentWindow().length, 0);
});

