// =========================================================================
// STAGE 715 — createConfigDecodeGarbageCollector
// =========================================================================
test("createConfigDecodeGarbageCollector — tracks and collects", () => {
  const gc = decodeEngine.createConfigDecodeGarbageCollector(1); // 1ms TTL
  gc.track("old", { data: "stale" });
  // Force some time to pass by synchronous busy-wait
  const start = Date.now(); while (Date.now() - start < 5) {}
  gc.track("new", { data: "fresh" });
  const result = gc.collect();
  assertEq(result.collected, 1);
  assertEq(result.remaining, 1);
});

test("createConfigDecodeGarbageCollector — nothing to collect", () => {
  const gc = decodeEngine.createConfigDecodeGarbageCollector(60000);
  gc.track("a", {}); gc.track("b", {});
  const result = gc.collect();
  assertEq(result.collected, 0);
  assertEq(result.remaining, 2);
});

test("createConfigDecodeGarbageCollector — clear empties all", () => {
  const gc = decodeEngine.createConfigDecodeGarbageCollector(60000);
  gc.track("x", {}); gc.track("y", {});
  gc.clear();
  assertEq(gc.size(), 0);
});

