// =========================================================================
// STAGE 723 — createConfigDecodeBackpressureController
// =========================================================================
test("createConfigDecodeBackpressureController — pauses at high watermark", () => {
  const bp = decodeEngine.createConfigDecodeBackpressureController(5, 2);
  for (let i = 0; i < 5; i++) bp.enqueue();
  assertEq(bp.isPaused(), true);
  assertEq(bp.canAccept(), false);
});

test("createConfigDecodeBackpressureController — resumes at low watermark", () => {
  const bp = decodeEngine.createConfigDecodeBackpressureController(5, 2);
  for (let i = 0; i < 5; i++) bp.enqueue();
  assertEq(bp.isPaused(), true);
  bp.drain(3); // 5-3=2, at low watermark
  assertEq(bp.isPaused(), false);
  assertEq(bp.canAccept(), true);
});

test("createConfigDecodeBackpressureController — reset clears state", () => {
  const bp = decodeEngine.createConfigDecodeBackpressureController(5, 2);
  bp.enqueue(10);
  bp.reset();
  assertEq(bp.queued(), 0);
  assertEq(bp.isPaused(), false);
});

