// =========================================================================
// STAGE 734 — computePayloadByteDistributionFit
// =========================================================================
test("computePayloadByteDistributionFit — uniform payload fits uniform", () => {
  const p = Buffer.alloc(2560);
  for (let i = 0; i < 2560; i++) p[i] = i % 256;
  const r = decodeEngine.computePayloadByteDistributionFit(p);
  assert(r.uniformFit > r.normalFit, "uniform data should fit uniform better");
  assertEq(r.bestFit, "uniform");
});

test("computePayloadByteDistributionFit — clustered fits normal better", () => {
  const p = Buffer.alloc(1000);
  // Approximate normal: cluster around 128
  let s = 42;
  for (let i = 0; i < 1000; i++) {
    s = (s * 1103515245 + 12345) & 0x7fffffff;
    const u1 = ((s >> 16) & 0xFFFF) / 65536;
    s = (s * 1103515245 + 12345) & 0x7fffffff;
    const u2 = ((s >> 16) & 0xFFFF) / 65536;
    const z = Math.sqrt(-2 * Math.log(u1 + 0.0001)) * Math.cos(2 * Math.PI * u2);
    p[i] = Math.max(0, Math.min(255, Math.round(128 + z * 30)));
  }
  const r = decodeEngine.computePayloadByteDistributionFit(p);
  assert(r.normalFit > 0, "should have positive normal fit");
  assert(r.stddev > 0, "should have stddev > 0");
});

test("computePayloadByteDistributionFit — empty", () => {
  const r = decodeEngine.computePayloadByteDistributionFit(Buffer.alloc(0));
  assertEq(r.bestFit, "empty");
});

