test("computePayloadByteWeightedMean — custom weight function", () => {
  const buf = Buffer.from([100, 200]);
  const r = decodeEngine.computePayloadByteWeightedMean(buf, (i, n) => i === 0 ? 1 : 3);
  // weighted mean = (100*1 + 200*3) / (1+3) = 700/4 = 175
  assertNear(r.mean, 175, 0.001);
  assertEq(r.totalWeight, 4);
});

