test("computePayloadByteHistogramDistance — completely different", () => {
  const a = Buffer.alloc(100, 0);
  const b = Buffer.alloc(100, 255);
  const r = decodeEngine.computePayloadByteHistogramDistance(a, b);
  assertNear(r.l1Distance, 2.0, 0.001);
  assertNear(r.normalized, 1.0, 0.001);
});

test("computePayloadByteHistogramDistance — partial overlap", () => {
  const a = Buffer.alloc(100, 0);
  const b = Buffer.alloc(100); for (let i = 0; i < 50; i++) b[i] = 0; for (let i = 50; i < 100; i++) b[i] = 1;
  const r = decodeEngine.computePayloadByteHistogramDistance(a, b);
  assert(r.l1Distance > 0 && r.l1Distance < 2);
});

