// STAGE 849 — createDecodeResultPriorityHeap
// =========================================================================
test("createDecodeResultPriorityHeap — min heap", () => {
  const h = decodeEngine.createDecodeResultPriorityHeap((a, b) => a.priority - b.priority);
  h.push({ priority: 5 }); h.push({ priority: 1 }); h.push({ priority: 3 });
  assertEq(h.peek().priority, 1);
  assertEq(h.pop().priority, 1);
  assertEq(h.pop().priority, 3);
});

test("createDecodeResultPriorityHeap — max heap", () => {
  const h = decodeEngine.createDecodeResultPriorityHeap((a, b) => b.priority - a.priority);
  h.push({ priority: 2 }); h.push({ priority: 8 }); h.push({ priority: 5 });
  assertEq(h.pop().priority, 8);
});

test("createDecodeResultPriorityHeap — empty pop", () => {
  const h = decodeEngine.createDecodeResultPriorityHeap();
  assertEq(h.pop(), null);
  assertEq(h.size(), 0);
});

