test("createConfigDecodeBackoffPolicy — exponential growth", () => {
  const bp = decodeEngine.createConfigDecodeBackoffPolicy(100, 10000, 2);
  assertEq(bp.nextDelay("cfg1"), 100);   // 100*2^0
  assertEq(bp.nextDelay("cfg1"), 200);   // 100*2^1
  assertEq(bp.nextDelay("cfg1"), 400);   // 100*2^2
  assertEq(bp.attempt("cfg1"), 3);
});

test("createConfigDecodeBackoffPolicy — caps at max", () => {
  const bp = decodeEngine.createConfigDecodeBackoffPolicy(100, 500, 2);
  bp.nextDelay("x"); bp.nextDelay("x"); bp.nextDelay("x"); // 100, 200, 400
  assertEq(bp.nextDelay("x"), 500); // 800 capped to 500
});

test("createConfigDecodeBackoffPolicy — reset", () => {
  const bp = decodeEngine.createConfigDecodeBackoffPolicy(100, 10000, 2);
  bp.nextDelay("a"); bp.nextDelay("a");
  bp.resetConfig("a");
  assertEq(bp.attempt("a"), 0);
});

