test("computePayloadByteSortedness — fully ascending", () => {
  const buf = Buffer.from([1, 2, 3, 4, 5]);
  const r = decodeEngine.computePayloadByteSortedness(buf);
  assertEq(r.ascending, 1);
  assertEq(r.sorted, true);
});

test("computePayloadByteSortedness ��� fully descending", () => {
  const buf = Buffer.from([5, 4, 3, 2, 1]);
  const r = decodeEngine.computePayloadByteSortedness(buf);
  assertEq(r.descending, 1);
  assertEq(r.sorted, true);
});

test("computePayloadByteSortedness — random order", () => {
  const buf = Buffer.from([3, 1, 4, 1, 5]);
  const r = decodeEngine.computePayloadByteSortedness(buf);
  assert(r.ascending < 1 && r.ascending > 0);
  assertEq(r.sorted, false);
});

