// STAGE 877 — createDecodeResultLRUCache
// =========================================================================
test("createDecodeResultLRUCache — get promotes entry", () => {
  const lru = decodeEngine.createDecodeResultLRUCache(3);
  lru.set("a", 1); lru.set("b", 2); lru.set("c", 3);
  lru.get("a"); // promote a
  lru.set("d", 4); // should evict b (oldest after a promotion)
  assertEq(lru.has("a"), true);
  assertEq(lru.has("b"), false);
});

test("createDecodeResultLRUCache — capacity limit", () => {
  const lru = decodeEngine.createDecodeResultLRUCache(2);
  lru.set("x", 1); lru.set("y", 2); lru.set("z", 3);
  assertEq(lru.size(), 2);
  assertEq(lru.has("x"), false);
});

test("createDecodeResultLRUCache — clear", () => {
  const lru = decodeEngine.createDecodeResultLRUCache(10);
  lru.set("a", 1); lru.clear();
  assertEq(lru.size(), 0);
});

