// =========================================================================
// STAGE 881 — createDecodeResultObservable
// =========================================================================
test("createDecodeResultObservable — subscribe and next", () => {
  const obs = decodeEngine.createDecodeResultObservable();
  const received = [];
  obs.subscribe(v => received.push(v));
  obs.next(1); obs.next(2); obs.next(3);
  assertEq(received.length, 3);
  assertEq(received[1], 2);
});

test("createDecodeResultObservable — complete stops delivery", () => {
  const obs = decodeEngine.createDecodeResultObservable();
  let completed = false;
  obs.subscribe(null, () => { completed = true; });
  obs.complete();
  assert(completed);
  assert(obs.isCompleted());
});

test("createDecodeResultObservable — unsubscribe", () => {
  const obs = decodeEngine.createDecodeResultObservable();
  let count = 0;
  const sub = obs.subscribe(() => count++);
  obs.next(1);
  sub.unsubscribe();
  obs.next(2);
  assertEq(count, 1);
  assertEq(obs.subscriberCount(), 0);
});

