// STAGE 885 — createDecodeResultStateMachine
// =========================================================================
test("createDecodeResultStateMachine — transitions", () => {
  const sm = decodeEngine.createDecodeResultStateMachine({
    init: { start: "running" },
    running: { done: "finished", error: "failed" }
  });
  assert(sm.transition("start"));
  assertEq(sm.state(), "running");
  assert(sm.canTransition("done"));
  sm.transition("done");
  assertEq(sm.state(), "finished");
});

test("createDecodeResultStateMachine — invalid transition", () => {
  const sm = decodeEngine.createDecodeResultStateMachine({ init: { go: "end" } });
  assertEq(sm.transition("invalid"), false);
  assertEq(sm.state(), "init");
});

test("createDecodeResultStateMachine — reset", () => {
  const sm = decodeEngine.createDecodeResultStateMachine({ init: { go: "end" } });
  sm.transition("go");
  sm.reset();
  assertEq(sm.state(), "init");
  assertEq(sm.history().length, 0);
});

