// STAGE 927 — createConfigDecodeResourcePool
// =========================================================================
test("createConfigDecodeResourcePool — acquire and release", () => {
  let counter = 0;
  const pool = decodeEngine.createConfigDecodeResourcePool(() => ({ id: counter++ }), 3);
  const r1 = pool.acquire();
  const r2 = pool.acquire();
  assertEq(pool.inUseCount(), 2);
  pool.release(r1);
  assertEq(pool.availableCount(), 1);
  const r3 = pool.acquire();
  assertEq(r3.id, r1.id, "should reuse released resource");
});

test("createConfigDecodeResourcePool — exhaustion", () => {
  const pool = decodeEngine.createConfigDecodeResourcePool(() => ({}), 2);
  pool.acquire(); pool.acquire();
  const r = pool.acquire();
  assertEq(r, null, "should return null when exhausted");
});

test("createConfigDecodeResourcePool — drain", () => {
  const pool = decodeEngine.createConfigDecodeResourcePool(() => ({}), 5);
  pool.acquire(); pool.acquire();
  pool.drain();
  assertEq(pool.totalCreated(), 0);
  assertEq(pool.inUseCount(), 0);
});

