test("createDecodeResultSemaphore — release grants to waiting", () => {
  const sem = decodeEngine.createDecodeResultSemaphore(1);
  sem.acquire();
  let called = false;
  sem.acquire(() => { called = true; });
  assertEq(sem.waitingCount(), 1);
  sem.release();
  assert(called);
});

test("createDecodeResultSemaphore — reset", () => {
  const sem = decodeEngine.createDecodeResultSemaphore(3);
  sem.acquire(); sem.acquire();
  sem.reset();
  assertEq(sem.available(), 3);
});

