// STAGE 1025 — createDecodeResultObservable
// =========================================================================
test("createDecodeResultObservable — next delivers values", () => {
  const obs = decodeEngine.createDecodeResultObservable();
  let received = null;
  obs.subscribe({ next: v => { received = v; } });
  obs.next({ id: 42 });
  assertEq(received.id, 42);
});

test("createDecodeResultObservable — complete stops delivery", () => {
  const obs = decodeEngine.createDecodeResultObservable();
  let count = 0;
  obs.subscribe({ next: () => { count++; } });
  obs.next(1);
  obs.complete();
  obs.next(2);
  assertEq(count, 1);
  assert(obs.isCompleted());
});

test("createDecodeResultObservable — unsubscribe", () => {
  const obs = decodeEngine.createDecodeResultObservable();
  let count = 0;
  const sub = obs.subscribe({ next: () => { count++; } });
  obs.next(1);
  sub.unsubscribe();
  obs.next(2);
  assertEq(count, 1);
  assertEq(obs.observerCount(), 0);
});

