// STAGE 1039 — createConfigDecodeRateLimiterWindow
test("createConfigDecodeRateLimiterWindow — basic limiting", () => {
  const rl = decodeEngine.createConfigDecodeRateLimiterWindow({ windowMs: 1000, maxRequests: 3 });
  assert(rl.tryAcquire(100), "first should pass");
  assert(rl.tryAcquire(200), "second should pass");
  assert(rl.tryAcquire(300), "third should pass");
  assert(!rl.tryAcquire(400), "fourth should fail");
  assertEq(rl.remaining(400), 0);
});
test("createConfigDecodeRateLimiterWindow — window expiry", () => {
  const rl = decodeEngine.createConfigDecodeRateLimiterWindow({ windowMs: 100, maxRequests: 2 });
  assert(rl.tryAcquire(0));
  assert(rl.tryAcquire(50));
  assert(!rl.tryAcquire(80));
  // After window expires
  assert(rl.tryAcquire(200), "after window should pass");
});
test("createConfigDecodeRateLimiterWindow — reset", () => {
  const rl = decodeEngine.createConfigDecodeRateLimiterWindow({ windowMs: 1000, maxRequests: 1 });
  rl.tryAcquire(0);
  assert(!rl.tryAcquire(1));
  rl.reset();
  assert(rl.tryAcquire(2), "after reset should pass");
});

