// STAGE 1043 — createConfigDecodeAdaptiveTimeout
test("createConfigDecodeAdaptiveTimeout — adapts to samples", () => {
  const at = decodeEngine.createConfigDecodeAdaptiveTimeout({ baseMs: 1000, minMs: 100, maxMs: 5000 });
  at.recordDuration(200);
  at.recordDuration(200);
  at.recordDuration(200);
  const t = at.getTimeout();
  // EWMA should converge toward 200, timeout = 200*2.5 = 500
  assert(t >= 100 && t <= 5000, "should be within bounds");
  assert(t < 2000, "should adapt down from base");
});
test("createConfigDecodeAdaptiveTimeout — respects max", () => {
  const at = decodeEngine.createConfigDecodeAdaptiveTimeout({ baseMs: 100, maxMs: 500 });
  at.recordDuration(5000);
  assert(at.getTimeout() <= 500, "should not exceed max");
});
test("createConfigDecodeAdaptiveTimeout — reset", () => {
  const at = decodeEngine.createConfigDecodeAdaptiveTimeout({ baseMs: 1000 });
  at.recordDuration(50);
  at.reset();
  assertEq(at.sampleCount(), 0);
  assertNear(at.currentEstimate(), 1000, 0.01);
});

