// STAGE 1049 — createDecodeResultEventSourceAdapter
test("createDecodeResultEventSourceAdapter — emit and listen", () => {
  const es = decodeEngine.createDecodeResultEventSourceAdapter();
  let received = null;
  es.on("decode", (e) => { received = e; });
  const id = es.emit("decode", { result: "ok" });
  assert(received !== null);
  assertEq(received.type, "decode");
  assertEq(received.data.result, "ok");
  assertEq(id, 1);
});
test("createDecodeResultEventSourceAdapter — wildcard and replay", () => {
  const es = decodeEngine.createDecodeResultEventSourceAdapter();
  const all = [];
  es.on("*", (e) => { all.push(e); });
  es.emit("a", 1); es.emit("b", 2); es.emit("c", 3);
  assertEq(all.length, 3);
  const replayed = [];
  es.replay(1, (e) => { replayed.push(e); });
  assertEq(replayed.length, 2); // events 2 and 3
});
test("createDecodeResultEventSourceAdapter — off and clear", () => {
  const es = decodeEngine.createDecodeResultEventSourceAdapter();
  let count = 0;
  const fn = () => { count++; };
  es.on("x", fn);
  es.emit("x", null);
  es.off("x", fn);
  es.emit("x", null);
  assertEq(count, 1);
  es.clear();
  assertEq(es.lastEventId(), 0);
});

