// STAGE 1059 — createConfigDecodeResourcePool
test("createConfigDecodeResourcePool — acquire and release", () => {
  let id = 0;
  const pool = decodeEngine.createConfigDecodeResourcePool({ factory: () => ({ id: ++id }), maxSize: 2 });
  assertEq(pool.availableCount(), 2);
  const r1 = pool.acquire();
  const r2 = pool.acquire();
  assertEq(pool.availableCount(), 0);
  assertEq(pool.inUseCount(), 2);
  assertEq(pool.acquire(), null); // exhausted
  pool.release(r1);
  assertEq(pool.availableCount(), 1);
});
test("createConfigDecodeResourcePool — totalCreated", () => {
  const pool = decodeEngine.createConfigDecodeResourcePool({ maxSize: 3 });
  assertEq(pool.totalCreated(), 3);
});
test("createConfigDecodeResourcePool — drain", () => {
  const pool = decodeEngine.createConfigDecodeResourcePool({ maxSize: 2 });
  pool.acquire();
  pool.drain();
  assertEq(pool.availableCount(), 0);
  assertEq(pool.inUseCount(), 0);
});

