// STAGE 1073 — createDecodeResultFanOutDispatcher
test("createDecodeResultFanOutDispatcher — dispatch to multiple", () => {
  const fo = decodeEngine.createDecodeResultFanOutDispatcher();
  const results = [];
  fo.addHandler((d) => { results.push("a:" + d); return "a"; });
  fo.addHandler((d) => { results.push("b:" + d); return "b"; });
  const r = fo.dispatch("test");
  assertEq(results.length, 2);
  assertEq(r.length, 2);
  assertEq(fo.dispatchedCount(), 1);
});
test("createDecodeResultFanOutDispatcher — remove handler", () => {
  const fo = decodeEngine.createDecodeResultFanOutDispatcher();
  const idx = fo.addHandler(() => "x");
  fo.removeHandler(idx);
  assertEq(fo.handlerCount(), 0);
});
test("createDecodeResultFanOutDispatcher — clear", () => {
  const fo = decodeEngine.createDecodeResultFanOutDispatcher();
  fo.addHandler(() => {}); fo.dispatch("x");
  fo.clear();
  assertEq(fo.handlerCount(), 0);
  assertEq(fo.dispatchedCount(), 0);
});

