// STAGE 1075 — createConfigDecodeCircuitPool
test("createConfigDecodeCircuitPool — acquire least used", () => {
  const cp = decodeEngine.createConfigDecodeCircuitPool({ size: 2 });
  const c1 = cp.acquire();
  const c2 = cp.acquire();
  assert(c1.id !== c2.id || c1.uses !== c2.uses, "should distribute");
  assertEq(cp.totalUses(), 2);
});
test("createConfigDecodeCircuitPool — mark unhealthy", () => {
  const cp = decodeEngine.createConfigDecodeCircuitPool({ size: 2 });
  cp.markUnhealthy(0);
  assertEq(cp.healthyCount(), 1);
  const c = cp.acquire();
  assertEq(c.id, 1);
});
test("createConfigDecodeCircuitPool — reset", () => {
  const cp = decodeEngine.createConfigDecodeCircuitPool({ size: 3 });
  cp.acquire(); cp.acquire();
  cp.markUnhealthy(0);
  cp.reset();
  assertEq(cp.healthyCount(), 3);
  assertEq(cp.totalUses(), 0);
});

