// STAGE 1078 — computePayloadByteExponentialSmoothing
test("computePayloadByteExponentialSmoothing — smooths noise", () => {
  const buf = Buffer.from([10, 50, 10, 50, 10, 50]);
  const r = decodeEngine.computePayloadByteExponentialSmoothing(buf, { alpha: 0.3 });
  assertEq(r.smoothed.length, 6);
  assertEq(r.smoothed[0], 10);
  // Smoothed values should oscillate less than raw
  const rawRange = 40;
  const smoothRange = Math.max(...r.smoothed) - Math.min(...r.smoothed);
  assert(smoothRange < rawRange, "smoothing should reduce range");
});
test("computePayloadByteExponentialSmoothing — alpha=1 is raw", () => {
  const buf = Buffer.from([5, 10, 15]);
  const r = decodeEngine.computePayloadByteExponentialSmoothing(buf, { alpha: 1 });
  assertEq(r.smoothed[2], 15);
});
test("computePayloadByteExponentialSmoothing — empty", () => {
  const r = decodeEngine.computePayloadByteExponentialSmoothing(Buffer.alloc(0));
  assertEq(r.smoothed.length, 0);
});

