// STAGE 1083 — createConfigDecodeWatchdog
test("createConfigDecodeWatchdog — healthy when pinged", () => {
  const wd = decodeEngine.createConfigDecodeWatchdog({ timeoutMs: 100 });
  wd.ping(1000);
  assert(wd.check(1050));
});
test("createConfigDecodeWatchdog — stall detection", () => {
  let stalled = false;
  const wd = decodeEngine.createConfigDecodeWatchdog({ timeoutMs: 100, onStall: () => { stalled = true; } });
  wd.ping(1000);
  assert(!wd.check(1200));
  assert(stalled);
  assertEq(wd.stallCount(), 1);
});
test("createConfigDecodeWatchdog — reset", () => {
  const wd = decodeEngine.createConfigDecodeWatchdog({ timeoutMs: 50 });
  wd.ping(0);
  wd.check(200); // stall
  wd.reset();
  assertEq(wd.stallCount(), 0);
});

