// STAGE 1091 — createConfigDecodeStateChart
test("createConfigDecodeStateChart — transitions", () => {
  const sc = decodeEngine.createConfigDecodeStateChart({
    initial: "idle",
    transitions: { idle: { start: "running" }, running: { done: "idle", fail: "error" }, error: { reset: "idle" } }
  });
  assertEq(sc.state(), "idle");
  assert(sc.transition("start"));
  assertEq(sc.state(), "running");
  assert(sc.transition("done"));
  assertEq(sc.state(), "idle");
});
test("createConfigDecodeStateChart — invalid transition", () => {
  const sc = decodeEngine.createConfigDecodeStateChart({ initial: "a", transitions: { a: { go: "b" } } });
  assert(!sc.transition("nope"));
  assertEq(sc.state(), "a");
});
test("createConfigDecodeStateChart — history and reset", () => {
  const sc = decodeEngine.createConfigDecodeStateChart({ initial: "s0", transitions: { s0: { x: "s1" }, s1: {} } });
  sc.transition("x");
  assertEq(sc.history().length, 2);
  sc.reset();
  assertEq(sc.state(), "s0");
});

