// STAGE 1099 — createConfigDecodeBarrierSync
test("createConfigDecodeBarrierSync — releases at threshold", () => {
  const bs = decodeEngine.createConfigDecodeBarrierSync({ parties: 3 });
  assertEq(bs.arrive().released, false);
  assertEq(bs.arrive().released, false);
  const r = bs.arrive();
  assert(r.released);
  assertEq(r.generation, 1);
});
test("createConfigDecodeBarrierSync — resets after release", () => {
  const bs = decodeEngine.createConfigDecodeBarrierSync({ parties: 2 });
  bs.arrive(); bs.arrive(); // gen 1
  assertEq(bs.waiting(), 0);
  bs.arrive(); // new gen, 1 waiting
  assertEq(bs.waiting(), 1);
});
test("createConfigDecodeBarrierSync — reset", () => {
  const bs = decodeEngine.createConfigDecodeBarrierSync({ parties: 2 });
  bs.arrive();
  bs.reset();
  assertEq(bs.waiting(), 0);
  assertEq(bs.generation(), 0);
});

