// STAGE 1105 — createDecodeResultDiffPatch
test("createDecodeResultDiffPatch — create and apply", () => {
  const dp = decodeEngine.createDecodeResultDiffPatch();
  const before = { a: 1, b: 2 };
  const after = { a: 1, b: 3, c: 4 };
  const patch = dp.createPatch(before, after);
  assertEq(patch.length, 2); // b replaced, c added
  const result = dp.applyPatch(before, patch);
  assertEq(result.b, 3);
  assertEq(result.c, 4);
});
test("createDecodeResultDiffPatch — invert patch", () => {
  const dp = decodeEngine.createDecodeResultDiffPatch();
  const patch = [{ op: "add", key: "x", value: 1 }];
  const inv = dp.invertPatch(patch);
  assertEq(inv[0].op, "remove");
});
test("createDecodeResultDiffPatch — remove op", () => {
  const dp = decodeEngine.createDecodeResultDiffPatch();
  const before = { a: 1, b: 2 };
  const after = { a: 1 };
  const patch = dp.createPatch(before, after);
  assert(patch.some(p => p.op === "remove" && p.key === "b"));
});

