// STAGE 1107 — createConfigDecodeSemaphore
test("createConfigDecodeSemaphore — acquire and release", () => {
  const sem = decodeEngine.createConfigDecodeSemaphore({ permits: 2 });
  assert(sem.acquire());
  assert(sem.acquire());
  assert(!sem.acquire()); // exhausted
  assertEq(sem.available(), 0);
  sem.release();
  assertEq(sem.available(), 1);
});
test("createConfigDecodeSemaphore — waiting count", () => {
  const sem = decodeEngine.createConfigDecodeSemaphore({ permits: 1 });
  sem.acquire();
  sem.acquire(); // fails, increments waitCount
  assertEq(sem.waiting(), 1);
});
test("createConfigDecodeSemaphore — reset", () => {
  const sem = decodeEngine.createConfigDecodeSemaphore({ permits: 3 });
  sem.acquire(); sem.acquire();
  sem.reset();
  assertEq(sem.available(), 3);
});

