// STAGE 1111 — createConfigDecodeMiddlewarePipeline
test("createConfigDecodeMiddlewarePipeline — chain execution", () => {
  const mp = decodeEngine.createConfigDecodeMiddlewarePipeline();
  mp.use((ctx, next) => { ctx.steps.push("a"); return next(); });
  mp.use((ctx, next) => { ctx.steps.push("b"); return next(); });
  const ctx = { steps: [] };
  mp.execute(ctx);
  assertEq(ctx.steps.length, 2);
  assertEq(ctx.steps[0], "a");
  assertEq(ctx.steps[1], "b");
});
test("createConfigDecodeMiddlewarePipeline — short circuit", () => {
  const mp = decodeEngine.createConfigDecodeMiddlewarePipeline();
  mp.use((ctx) => { ctx.stopped = true; return ctx; });
  mp.use((ctx, next) => { ctx.reached = true; return next(); });
  const ctx = {};
  mp.execute(ctx);
  assert(ctx.stopped);
  assertEq(ctx.reached, undefined);
});
test("createConfigDecodeMiddlewarePipeline — clear", () => {
  const mp = decodeEngine.createConfigDecodeMiddlewarePipeline();
  mp.use(() => {}); mp.use(() => {});
  mp.clear();
  assertEq(mp.count(), 0);
});

