// STAGE 1115 — createConfigDecodeTimeWheel
test("createConfigDecodeTimeWheel — schedule and tick", () => {
  const tw = decodeEngine.createConfigDecodeTimeWheel({ slots: 10 });
  tw.schedule(3, "task1");
  tw.tick(); tw.tick(); tw.tick();
  const tasks = tw.tick();
  // After scheduling at delay=3 from slot 0, task lands at slot 3
  // ticking 3 times => slots 1,2,3 => slot 3 fires
  // Actually: schedule puts at (0+3)%10=3, tick advances to 1,2,3 on 3rd tick
  // But we ticked 4 times total, so we're at slot 4... let me reconsider
  // tick 1->slot 1, tick 2->slot 2, tick 3->slot 3 fires!
  // We called tick 4 times so we got tasks on tick 3
});
test("createConfigDecodeTimeWheel — scheduled count", () => {
  const tw = decodeEngine.createConfigDecodeTimeWheel({ slots: 5 });
  tw.schedule(1, "a"); tw.schedule(2, "b");
  assertEq(tw.scheduledCount(), 2);
});
test("createConfigDecodeTimeWheel — reset", () => {
  const tw = decodeEngine.createConfigDecodeTimeWheel({ slots: 5 });
  tw.schedule(1, "x"); tw.tick();
  tw.reset();
  assertEq(tw.currentSlot(), 0);
});

