// STAGE 1119 — createConfigDecodePubSubFilter
test("createConfigDecodePubSubFilter — pattern matching", () => {
  const ps = decodeEngine.createConfigDecodePubSubFilter();
  const received = [];
  ps.subscribe("decode.*", (topic, data) => { received.push({ topic, data }); });
  ps.publish("decode.start", 1);
  ps.publish("decode.end", 2);
  ps.publish("encode.start", 3); // no match
  assertEq(received.length, 2);
});
test("createConfigDecodePubSubFilter — exact topic", () => {
  const ps = decodeEngine.createConfigDecodePubSubFilter();
  let count = 0;
  ps.subscribe("exact", () => { count++; });
  assertEq(ps.publish("exact", null), 1);
  assertEq(ps.publish("other", null), 0);
});
test("createConfigDecodePubSubFilter — unsubscribe", () => {
  const ps = decodeEngine.createConfigDecodePubSubFilter();
  const id = ps.subscribe("*", () => {});
  assertEq(ps.subscriptionCount(), 1);
  ps.unsubscribe(id);
  assertEq(ps.subscriptionCount(), 0);
});

