// =========================================================================
// STAGE 1171: createConfigDecodeJobScheduler
// =========================================================================
test("createConfigDecodeJobScheduler — schedule and advance", () => {
  const sched = decodeEngine.createConfigDecodeJobScheduler();
  let ran = 0;
  sched.schedule(2, () => { ran++; });
  // First advance fires immediately (lastRun=-Infinity), then waits interval
  sched.advance(); // tick 1 — fires (initial)
  assertEq(ran, 1, "fires on first advance");
  sched.advance(); // tick 2 — not yet (only 1 tick since last)
  assertEq(ran, 1, "waits for interval");
  sched.advance(); // tick 3 — fires again
  assertEq(ran, 2, "fires after interval");
});
test("createConfigDecodeJobScheduler — cancel job", () => {
  const sched = decodeEngine.createConfigDecodeJobScheduler();
  let ran = 0;
  const id = sched.schedule(1, () => { ran++; });
  sched.cancel(id);
  sched.advance();
  assertEq(ran, 0, "cancelled job does not fire");
});
test("createConfigDecodeJobScheduler — jobCount", () => {
  const sched = decodeEngine.createConfigDecodeJobScheduler();
  sched.schedule(5, () => {});
  sched.schedule(3, () => {});
  assertEq(sched.jobCount(), 2, "two jobs scheduled");
});

