test("computePayloadByteMovingAverage — smoothed length matches", () => {
  const buf = Buffer.from([10, 20, 30, 40, 50]);
  const r = decodeEngine.computePayloadByteMovingAverage(buf, { windowSize: 3 });
  assertEq(r.smoothed.length, 5, "smoothed same length as input");
});
test("computePayloadByteMovingAverage — reduces variance", () => {
  const buf = Buffer.from([0, 100, 0, 100, 0, 100]);
  const r = decodeEngine.computePayloadByteMovingAverage(buf, { windowSize: 3 });
  const rawVar = [0,100,0,100,0,100].reduce((s,v) => s + (v-50)*(v-50), 0) / 6;
  const smoothVar = r.smoothed.reduce((s,v) => s + (v-50)*(v-50), 0) / r.smoothed.length;
  assert(smoothVar < rawVar, "smoothing reduces variance");
});
test("computePayloadByteMovingAverage — default window", () => {
  const buf = Buffer.from([1, 2, 3]);
  const r = decodeEngine.computePayloadByteMovingAverage(buf);
  assertEq(r.windowSize, 3, "default window is 3");
});

