// =========================================================================
// STAGE 1245: createDecodeResultLazyEvaluator
// =========================================================================
test("createDecodeResultLazyEvaluator — lazy evaluation", () => {
  let evalCount = 0;
  const le = decodeEngine.createDecodeResultLazyEvaluator();
  le.define("x", () => { evalCount++; return 42; });
  assertEq(evalCount, 0, "not evaluated yet");
  assertEq(le.evaluate("x"), 42, "evaluates to 42");
  assertEq(evalCount, 1, "evaluated once");
  le.evaluate("x"); // cached
  assertEq(evalCount, 1, "still evaluated once (cached)");
});
test("createDecodeResultLazyEvaluator — invalidate", () => {
  const le = decodeEngine.createDecodeResultLazyEvaluator();
  le.define("y", () => Math.random());
  const v1 = le.evaluate("y");
  le.invalidate("y");
  assert(!le.isEvaluated("y"), "invalidated");
});
test("createDecodeResultLazyEvaluator — definedCount", () => {
  const le = decodeEngine.createDecodeResultLazyEvaluator();
  le.define("a", () => 1); le.define("b", () => 2);
  assertEq(le.definedCount(), 2, "two defined");
});

