// STAGE 1267: createConfigDecodeStateMachine
test("createConfigDecodeStateMachine — transitions", () => {
  const sm = decodeEngine.createConfigDecodeStateMachine({
    initial: "idle",
    states: { idle: { on: { start: "running" } }, running: { on: { stop: "idle", pause: "paused" } }, paused: { on: { resume: "running" } } }
  });
  assertEq(sm.state(), "idle", "starts idle");
  assert(sm.transition("start"), "transition to running");
  assertEq(sm.state(), "running", "now running");
  assert(!sm.canTransition("start"), "cannot start again");
  assert(sm.canTransition("pause"), "can pause");
});
test("createConfigDecodeStateMachine — invalid transition", () => {
  const sm = decodeEngine.createConfigDecodeStateMachine({
    initial: "a",
    states: { a: { on: { go: "b" } }, b: {} }
  });
  assert(!sm.transition("nope"), "invalid event returns false");
  assertEq(sm.state(), "a", "state unchanged");
});
test("createConfigDecodeStateMachine — history and reset", () => {
  const sm = decodeEngine.createConfigDecodeStateMachine({
    initial: "x",
    states: { x: { on: { next: "y" } }, y: { on: { next: "z" } }, z: {} }
  });
  sm.transition("next"); sm.transition("next");
  const h = sm.history();
  assertEq(h.length, 3, "history has 3 entries");
  assertEq(h[2], "z", "last is z");
  sm.reset();
  assertEq(sm.state(), "x", "reset to initial");
});

// STAGE 1268: computePayloadBytePeakedness
test("computePayloadBytePeakedness — uniform distribution", () => {
  const bytes = [];
  for (let i = 0; i < 256; i++) bytes.push(i);
  const buf = Buffer.from(bytes);
  const r = decodeEngine.computePayloadBytePeakedness(buf);
  assert(r.kurtosis < 3, "uniform is platykurtic");
  assert(!r.isPeaked, "not peaked");
});
test("computePayloadBytePeakedness — concentrated distribution", () => {
  const bytes = new Array(100).fill(128);
  bytes[50] = 0; bytes[51] = 255;
  const buf = Buffer.from(bytes);
  const r = decodeEngine.computePayloadBytePeakedness(buf);
  assert(r.kurtosis > 3, "concentrated is leptokurtic");
  assert(r.isPeaked, "is peaked");
});
test("computePayloadBytePeakedness — returns excessKurtosis", () => {
  const buf = Buffer.from([1,2,3,4,5,6,7,8]);
  const r = decodeEngine.computePayloadBytePeakedness(buf);
  assertNear(r.excessKurtosis, r.kurtosis - 3, 1e-10, "excess = kurt - 3");
});

// STAGE 1269: createDecodeResultDependencyGraph
test("createDecodeResultDependencyGraph — basic deps", () => {
  const g = decodeEngine.createDecodeResultDependencyGraph();
  g.addEdge("a", "b"); g.addEdge("a", "c"); g.addEdge("b", "c");
  const deps = g.dependenciesOf("a");
  assert(deps.includes("b"), "a depends on b");
  assert(deps.includes("c"), "a depends on c");
  assertEq(g.nodeCount(), 3, "3 nodes");
  assertEq(g.edgeCount(), 3, "3 edges");
});
test("createDecodeResultDependencyGraph — dependentsOf", () => {
  const g = decodeEngine.createDecodeResultDependencyGraph();
  g.addEdge("a", "c"); g.addEdge("b", "c");
  const dependents = g.dependentsOf("c");
  assert(dependents.includes("a"), "a depends on c");
  assert(dependents.includes("b"), "b depends on c");
});
test("createDecodeResultDependencyGraph — topological sort", () => {
  const g = decodeEngine.createDecodeResultDependencyGraph();
  g.addEdge("build", "compile"); g.addEdge("compile", "parse"); g.addEdge("build", "link");
  const order = g.topologicalSort();
  assert(order.indexOf("build") < order.indexOf("compile"), "build before compile");
  assert(order.indexOf("compile") < order.indexOf("parse"), "compile before parse");
});

