// STAGE 1273: createDecodeResultObjectPool
test("createDecodeResultObjectPool — acquire and release", () => {
  let id = 0;
  const pool = decodeEngine.createDecodeResultObjectPool(() => ({ id: id++ }), { maxSize: 2 });
  const o1 = pool.acquire();
  const o2 = pool.acquire();
  assertEq(pool.stats().created, 2, "created 2");
  pool.release(o1);
  assertEq(pool.available(), 1, "1 available");
  const o3 = pool.acquire();
  assertEq(o3.id, o1.id, "reused o1");
  assertEq(pool.stats().reused, 1, "reused count 1");
});
test("createDecodeResultObjectPool — maxSize respected", () => {
  const pool = decodeEngine.createDecodeResultObjectPool(() => ({}), { maxSize: 1 });
  const o1 = pool.acquire();
  const o2 = pool.acquire();
  pool.release(o1); pool.release(o2);
  assertEq(pool.available(), 1, "capped at maxSize");
});
test("createDecodeResultObjectPool — drain", () => {
  const pool = decodeEngine.createDecodeResultObjectPool(() => ({}));
  pool.release(pool.acquire()); pool.release(pool.acquire());
  pool.drain();
  assertEq(pool.available(), 0, "drained");
});

