// STAGE 1291: createConfigDecodeCircuitBreaker
test("createConfigDecodeCircuitBreaker — opens after threshold", () => {
  const cb = decodeEngine.createConfigDecodeCircuitBreaker({ threshold: 3, resetTimeout: 1000 });
  assertEq(cb.state(), "closed", "starts closed");
  cb.recordFailure(100); cb.recordFailure(200); cb.recordFailure(300);
  assertEq(cb.state(), "open", "open after 3 failures");
  assert(!cb.canExecute(400), "cannot execute when open");
});
test("createConfigDecodeCircuitBreaker — half-open after timeout", () => {
  const cb = decodeEngine.createConfigDecodeCircuitBreaker({ threshold: 2, resetTimeout: 500 });
  cb.recordFailure(0); cb.recordFailure(100);
  assertEq(cb.state(), "open", "open");
  assert(cb.canExecute(700), "can execute after timeout");
  assertEq(cb.state(), "half-open", "now half-open");
});
test("createConfigDecodeCircuitBreaker — reset", () => {
  const cb = decodeEngine.createConfigDecodeCircuitBreaker({ threshold: 1 });
  cb.recordFailure(0);
  cb.reset();
  assertEq(cb.state(), "closed", "closed after reset");
  assertEq(cb.failureCount(), 0, "failures reset");
});

