// STAGE 1315: createConfigDecodeDebouncer
test("createConfigDecodeDebouncer — defers call", () => {
  const db = decodeEngine.createConfigDecodeDebouncer({ delay: 50 });
  let called = false;
  db.call(100, () => { called = true; return "ok"; });
  assert(!called, "not called immediately");
  const result = db.flush(160);
  assertEq(result, "ok", "flushed after delay");
});
test("createConfigDecodeDebouncer — too early flush", () => {
  const db = decodeEngine.createConfigDecodeDebouncer({ delay: 100 });
  db.call(0, () => "x");
  const result = db.flush(50);
  assertEq(result, null, "too early to flush");
});
test("createConfigDecodeDebouncer — cancel", () => {
  const db = decodeEngine.createConfigDecodeDebouncer({ delay: 10 });
  db.call(0, () => "y");
  db.cancel();
  assertEq(db.flush(1000), null, "cancelled");
  assert(!db.stats().hasPending, "no pending after cancel");
});

