// STAGE 1343: createConfigDecodeHysteresis
test("createConfigDecodeHysteresis — activation", () => {
  const h = decodeEngine.createConfigDecodeHysteresis({ high: 0.7, low: 0.3 });
  assert(!h.isActive(), "starts inactive");
  h.update(0.5); assert(!h.isActive(), "0.5 still inactive");
  h.update(0.8); assert(h.isActive(), "0.8 activates");
  h.update(0.5); assert(h.isActive(), "0.5 stays active (hysteresis)");
  h.update(0.2); assert(!h.isActive(), "0.2 deactivates");
});
test("createConfigDecodeHysteresis — thresholds", () => {
  const h = decodeEngine.createConfigDecodeHysteresis({ high: 0.9, low: 0.1 });
  const t = h.thresholds();
  assertEq(t.high, 0.9, "high threshold");
  assertEq(t.low, 0.1, "low threshold");
});
test("createConfigDecodeHysteresis — reset", () => {
  const h = decodeEngine.createConfigDecodeHysteresis({ high: 0.5, low: 0.1 });
  h.update(0.6);
  assert(h.isActive(), "active");
  h.reset();
  assert(!h.isActive(), "inactive after reset");
});

