// STAGE 1375: createConfigDecodeResourcePool
test("createConfigDecodeResourcePool — acquire and release", () => {
  let id = 0;
  const rp = decodeEngine.createConfigDecodeResourcePool(() => ({ id: id++ }), { maxSize: 3 });
  const r1 = rp.acquire();
  const r2 = rp.acquire();
  rp.release(r1);
  const r3 = rp.acquire();
  assertEq(r3.id, r1.id, "reused resource");
  assertEq(rp.stats().created, 2, "only 2 created");
});
test("createConfigDecodeResourcePool — stats", () => {
  const rp = decodeEngine.createConfigDecodeResourcePool(() => ({}));
  rp.acquire(); rp.acquire();
  const s = rp.stats();
  assertEq(s.acquired, 2, "2 acquired");
});
test("createConfigDecodeResourcePool — drain", () => {
  const rp = decodeEngine.createConfigDecodeResourcePool(() => ({}));
  rp.release(rp.acquire());
  rp.release(rp.acquire());
  const drained = rp.drain();
  assertEq(rp.available(), 0, "empty after drain");
  assert(drained.length > 0, "drained items returned");
});

