// STAGE 1417 — createDecodeResultPubSub
test("createDecodeResultPubSub — publish and subscribe", () => {
  const ps = decodeEngine.createDecodeResultPubSub();
  let received = null;
  ps.subscribe("topic1", (d) => { received = d; });
  const count = ps.publish("topic1", "hello");
  assertEq(count, 1, "1 delivered");
  assertEq(received, "hello", "received data");
});
test("createDecodeResultPubSub — unsubscribe", () => {
  const ps = decodeEngine.createDecodeResultPubSub();
  let count = 0;
  const unsub = ps.subscribe("t", () => { count++; });
  ps.publish("t");
  unsub();
  ps.publish("t");
  assertEq(count, 1, "only called once");
});
