// STAGE 1489 — createDecodeResultCircularBuffer
test("createDecodeResultCircularBuffer — wraps around", () => {
  const cb = decodeEngine.createDecodeResultCircularBuffer({ capacity: 3 });
  cb.write("a"); cb.write("b"); cb.write("c"); cb.write("d");
  assertEq(cb.size(), 3, "capped at 3");
  assertEq(cb.oldest(), "b", "oldest is b");
  assertEq(cb.latest(), "d", "latest is d");
});
test("createDecodeResultCircularBuffer — toArray order", () => {
  const cb = decodeEngine.createDecodeResultCircularBuffer({ capacity: 4 });
  cb.write(1); cb.write(2); cb.write(3);
  const arr = cb.toArray();
  assertEq(arr[0], 1, "first is 1");
  assertEq(arr[2], 3, "last is 3");
});
test("createDecodeResultCircularBuffer — read by offset", () => {
  const cb = decodeEngine.createDecodeResultCircularBuffer({ capacity: 5 });
  cb.write("x"); cb.write("y");
  assertEq(cb.read(0), "x", "offset 0");
  assertEq(cb.read(1), "y", "offset 1");
  assertEq(cb.read(5), undefined, "out of range");
});

