// STAGE 1551 — createConfigDecodeRetryPolicy
test("createConfigDecodeRetryPolicy — succeeds first try", () => {
  const rp = decodeEngine.createConfigDecodeRetryPolicy();
  const r = rp.execute(() => 42);
  assert(r.success, "succeeded");
  assertEq(r.result, 42, "correct result");
  assertEq(r.attempts, 1, "1 attempt");
});
test("createConfigDecodeRetryPolicy — retries on failure", () => {
  const rp = decodeEngine.createConfigDecodeRetryPolicy({ maxRetries: 2 });
  let calls = 0;
  const r = rp.execute(attempt => { calls++; if (attempt < 2) throw new Error("fail"); return "ok"; });
  assert(r.success, "eventually succeeded");
  assertEq(calls, 3, "3 calls");
});
test("createConfigDecodeRetryPolicy — all fail", () => {
  const rp = decodeEngine.createConfigDecodeRetryPolicy({ maxRetries: 1 });
  const r = rp.execute(() => { throw new Error("bad"); });
  assert(!r.success, "failed");
  assertEq(r.attempts, 2, "tried 2 times");
});

