// STAGE 1575 — createConfigDecodeCircuitBreaker
test("createConfigDecodeCircuitBreaker — closed on success", () => {
  const cb = decodeEngine.createConfigDecodeCircuitBreaker({ failureThreshold: 2 });
  const r = cb.execute(() => 42);
  assert(r.success, "succeeded");
  assertEq(r.result, 42, "correct result");
});
test("createConfigDecodeCircuitBreaker — opens on failures", () => {
  const cb = decodeEngine.createConfigDecodeCircuitBreaker({ failureThreshold: 2 });
  cb.execute(() => { throw new Error("f1"); });
  cb.execute(() => { throw new Error("f2"); });
  const r = cb.execute(() => 1);
  assert(!r.success, "circuit open");
  assertEq(r.state, "open", "state is open");
});
test("createConfigDecodeCircuitBreaker — reset", () => {
  const cb = decodeEngine.createConfigDecodeCircuitBreaker({ failureThreshold: 1 });
  cb.execute(() => { throw new Error("fail"); });
  cb.reset();
  const r = cb.execute(() => "ok");
  assert(r.success, "works after reset");
});

