// STAGE 1615 — createConfigDecodeLoadBalancer
test("createConfigDecodeLoadBalancer — round-robin", () => {
  const lb = decodeEngine.createConfigDecodeLoadBalancer({ strategy: "round-robin" });
  lb.addTarget("a"); lb.addTarget("b");
  assertEq(lb.next(), "a", "first is a");
  assertEq(lb.next(), "b", "second is b");
  assertEq(lb.next(), "a", "wraps to a");
});
test("createConfigDecodeLoadBalancer — least-loaded", () => {
  const lb = decodeEngine.createConfigDecodeLoadBalancer({ strategy: "least-loaded" });
  lb.addTarget("x"); lb.addTarget("y");
  lb.next(); // x gets load 1
  assertEq(lb.next(), "y", "picks y — less loaded");
  assertEq(lb.totalLoad(), 2, "total load 2");
});
test("createConfigDecodeLoadBalancer — empty", () => {
  const lb = decodeEngine.createConfigDecodeLoadBalancer();
  assertEq(lb.next(), null, "null when no targets");
  assertEq(lb.targetCount(), 0, "zero targets");
});

