// STAGE 1617 — createDecodeResultWriteAheadLog
test("createDecodeResultWriteAheadLog — append/replay", () => {
  const wal = decodeEngine.createDecodeResultWriteAheadLog();
  const lsn1 = wal.append("write", { k: 1 });
  const lsn2 = wal.append("write", { k: 2 });
  assertEq(lsn1, 1, "first LSN");
  assertEq(lsn2, 2, "second LSN");
  assertEq(wal.replay(2).length, 1, "replay from 2 gives 1 entry");
});
test("createDecodeResultWriteAheadLog — truncate", () => {
  const wal = decodeEngine.createDecodeResultWriteAheadLog();
  wal.append("a", 1); wal.append("b", 2); wal.append("c", 3);
  wal.truncate(3);
  assertEq(wal.count(), 1, "1 entry after truncate");
  assertEq(wal.latest().lsn, 3, "latest is lsn 3");
});
test("createDecodeResultWriteAheadLog — currentLSN", () => {
  const wal = decodeEngine.createDecodeResultWriteAheadLog();
  assertEq(wal.currentLSN(), 0, "initial LSN 0");
  wal.append("x", null);
  assertEq(wal.currentLSN(), 1, "LSN after one append");
});

