// STAGE 1621 — createDecodeResultBitmask
test("createDecodeResultBitmask — set/test/clear", () => {
  const bm = decodeEngine.createDecodeResultBitmask(16);
  bm.set(5);
  assertEq(bm.test(5), true, "bit 5 set");
  bm.clear(5);
  assertEq(bm.test(5), false, "bit 5 cleared");
});
test("createDecodeResultBitmask — popcount and toggle", () => {
  const bm = decodeEngine.createDecodeResultBitmask(8);
  bm.set(0); bm.set(3); bm.set(7);
  assertEq(bm.popcount(), 3, "3 bits set");
  bm.toggle(3);
  assertEq(bm.test(3), false, "toggled off");
  assertEq(bm.popcount(), 2, "2 bits after toggle");
});
test("createDecodeResultBitmask — and/or", () => {
  const a = decodeEngine.createDecodeResultBitmask(8);
  const b = decodeEngine.createDecodeResultBitmask(8);
  a.set(0); a.set(1); b.set(1); b.set(2);
  const andR = a.and(b);
  assertEq(andR.popcount(), 1, "AND: only bit 1");
  const orR = a.or(b);
  assertEq(orR.popcount(), 3, "OR: bits 0,1,2");
});

