// STAGE 1625 — createDecodeResultFenwickTree
test("createDecodeResultFenwickTree — update/query", () => {
  const ft = decodeEngine.createDecodeResultFenwickTree(8);
  ft.update(0, 3); ft.update(1, 5); ft.update(2, 7);
  assertEq(ft.query(0), 3, "prefix sum [0]");
  assertEq(ft.query(2), 15, "prefix sum [0..2] = 3+5+7");
});
test("createDecodeResultFenwickTree — rangeQuery", () => {
  const ft = decodeEngine.createDecodeResultFenwickTree(8);
  ft.update(0, 1); ft.update(1, 2); ft.update(2, 3); ft.update(3, 4);
  assertEq(ft.rangeQuery(1, 2), 5, "range [1..2] = 2+3");
  assertEq(ft.rangeQuery(0, 3), 10, "range [0..3] = 1+2+3+4");
});
test("createDecodeResultFenwickTree — set", () => {
  const ft = decodeEngine.createDecodeResultFenwickTree(8);
  ft.update(0, 10);
  ft.set(0, 25);
  assertEq(ft.query(0), 25, "set replaces value");
  assertEq(ft.size(), 8, "size is 8");
});

